var BLOCKS=[{"id":1,"title":"Grundlagen","sub":"Licht · Spektrum · Lichtwege · Farbmerkmale","ready":true,"icon":"💡"},{"id":2,"title":"Farbmischung","sub":"Additiv · subtraktiv · RGB · CMYK","ready":true,"icon":"🎨"},{"id":3,"title":"Farbkontraste","sub":"7 Kontraste · Wirkung · sichere Zuordnung","ready":true,"icon":"◐"},{"id":4,"title":"Licht & Farbsehen","sub":"Auge · Rezeptoren · Dämmerung · Farbfehler · Farbtemperatur","ready":true,"icon":"👁"},{"id":5,"title":"Farbsysteme","sub":"CIE · RAL Classic · RAL Design · NCS · Signalfarben","ready":true,"icon":"🧭"},{"id":6,"title":"Metamerie & Beurteilung","sub":"Lichtart · Spektrum · Reflexion · Wahrnehmung","ready":true,"icon":"🔎"},{"id":7,"title":"HBW & TSR","sub":"Hellbezugswert · solare Reflexion · Fassade · Wärmelast","ready":true,"icon":"☀️"},{"id":8,"title":"BFS 25 & BFS 26","sub":"Farbübereinstimmung · Farbveränderung · Praxisfälle","ready":true,"icon":"📋"}];
var LESSONS=[{"id":"b1l1","block":1,"title":"Optik & Licht","sub":"Was Licht ist und womit sich Optik befasst"},{"id":"b1l2","block":1,"title":"Sichtbares Spektrum","sub":"380–740 nm sicher einordnen"},{"id":"b1l3","block":1,"title":"Spektralfarben & Prisma","sub":"Weißes Licht wird sichtbar aufgespalten"},{"id":"b1l4","block":1,"title":"Absorption · Reflexion · Transmission","sub":"Die drei Lichtwege unterscheiden"},{"id":"b1l5","block":1,"title":"Sättigung · Helligkeit · Gegenstandsfarbe","sub":"Farbmerkmale und Reflexion verstehen"},{"id":"b2l1","block":2,"title":"Lichtfarben & Körperfarben","sub":"Die zwei Grundwelten der Farbmischung"},{"id":"b2l2","block":2,"title":"Additiv: Prinzip & RGB","sub":"Lichtfarben addieren"},{"id":"b2l3","block":2,"title":"Additiv: Mischresultate","sub":"Gelb, Cyan, Magenta und Weiß einordnen"},{"id":"b2l4","block":2,"title":"Subtraktiv: Prinzip & Primärfarben","sub":"Pigmente filtern Licht"},{"id":"b2l5","block":2,"title":"Subtraktiv: Anwendung","sub":"Filterwirkung und Verdunkelung verstehen"},{"id":"b2l6","block":2,"title":"Additiv vs. subtraktiv","sub":"Beide Systeme sicher auseinanderhalten"},{"id":"b3l1","block":3,"title":"Kontrast & Überblick","sub":"Begriff und sieben Farbkontraste sicher kennen"},{"id":"b3l2","block":3,"title":"Farbe-an-sich-Kontrast","sub":"Reine Farben nebeneinander beurteilen"},{"id":"b3l3","block":3,"title":"Hell-Dunkel-Kontrast","sub":"Helligkeiten und Tonwerte unterscheiden"},{"id":"b3l4","block":3,"title":"Kalt-Warm-Kontrast","sub":"Psychologisch warme und kalte Farbtöne kombinieren"},{"id":"b3l5","block":3,"title":"Komplementär-Kontrast","sub":"Gegenüberliegende Farben im Farbkreis erkennen"},{"id":"b3l6","block":3,"title":"Simultan-Kontrast","sub":"Psychologisch ergänzte Komplementärfarbe verstehen"},{"id":"b3l7","block":3,"title":"Quantitäts-Kontrast","sub":"Größenverhältnisse von Farbflächen beurteilen"},{"id":"b3l8","block":3,"title":"Qualitäts-Kontrast","sub":"Gesättigt-leuchtend gegen getrübt-stumpf unterscheiden"},{"id":"b4l1","block":4,"title":"Auge als optisches System","sub":"Linse, Netzhaut und Iris sicher zuordnen"},{"id":"b4l2","block":4,"title":"Rezeptoren & Signalweg","sub":"Wie Lichtreize als Impulse zum Gehirn gelangen"},{"id":"b4l3","block":4,"title":"Stäbchen & Zapfen","sub":"Helligkeit und buntes Farbsehen unterscheiden"},{"id":"b4l4","block":4,"title":"Tag · Dämmerung · Nacht","sub":"Welche Rezeptoren bei abnehmendem Licht übernehmen"},{"id":"b4l5","block":4,"title":"Farbfehlsichtigkeit","sub":"Zapfendefekte, Rot-Grün-Schwäche und Farbenblindheit"},{"id":"b4l6","block":4,"title":"Auge & Gehirn","sub":"Farbwahrnehmung als gemeinsamer Verarbeitungsprozess"},{"id":"b4l7","block":4,"title":"Farbtemperatur","sub":"Definition, Schwarzer Körper und Kelvin"},{"id":"b4l8","block":4,"title":"Lichtfarbe in der Praxis","sub":"Beleuchtungsempfehlungen und typische Kelvinwerte"},{"id":"b5l1","block":5,"title":"Farbton exakt bestimmen","sub":"Farbton, Helligkeit und Sättigung als Bezugsgößen"},{"id":"b5l2","block":5,"title":"CIE-Normvalenzsystem","sub":"Wahrnehmung und physikalischen Farbreiz in Beziehung setzen"},{"id":"b5l3","block":5,"title":"Farbordnungssysteme","sub":"RAL Classic, RAL Design und NCS einordnen"},{"id":"b5l4","block":5,"title":"RAL Classic","sub":"Nummerngruppen von Gelb bis Weiß/Schwarz sicher zuordnen"},{"id":"b5l5","block":5,"title":"RAL Design","sub":"CIELab-Bezug und systematische Ordnung verstehen"},{"id":"b5l6","block":5,"title":"RAL Classic vs. RAL Design","sub":"Sammlung und systematische Ordnung unterscheiden"},{"id":"b5l7","block":5,"title":"NCS & Farbcode","sub":"Natural Colour System und NCS S 3040-G40Y entschlüsseln"},{"id":"b5l8","block":5,"title":"RAL-Signalfarben","sub":"Signalgelb, Signalrot, Signalblau und Signalgrün anwenden"},{"id":"b6l1","block":6,"title":"Metamerie erkennen","sub":"Gleich bei einer Lichtart, unterschiedlich bei einer anderen"},{"id":"b6l2","block":6,"title":"Lichtarten vergleichen","sub":"Tageslicht und Kunstlicht als Lichtwechsel einordnen"},{"id":"b6l3","block":6,"title":"Metamere Lichtquellen","sub":"Gleiche Farbtemperatur, unterschiedliche spektrale Verteilung"},{"id":"b6l4","block":6,"title":"Spektrale Verteilung","sub":"Kontinuierliches Spektrum und schmale Spektralbänder"},{"id":"b6l5","block":6,"title":"Farbwiedergabeindex","sub":"Qualität der Farbwiedergabe einer Lichtquelle einordnen"},{"id":"b6l6","block":6,"title":"Glanz & Reflexion","sub":"Gerichtete und diffuse Reflexion unterscheiden"},{"id":"b6l7","block":6,"title":"Auge & Gehirn","sub":"Farbwahrnehmung als Verarbeitung und Interpretation"},{"id":"b6l8","block":6,"title":"Beurteilungsfaktoren","sub":"Licht, Oberfläche und Wahrnehmung fachlich auseinanderhalten"},{"id":"b7l1","block":7,"title":"TSR-Grundprinzip","sub":"Solare Reflexion einer pigmentierten Oberfläche"},{"id":"b7l2","block":7,"title":"TSR & Erwärmung","sub":"Warum mehr Reflexion die Aufheizung vermindert"},{"id":"b7l3","block":7,"title":"NIR & Pigmente","sub":"Dunkle Farbtöne mit geringer NIR-Absorption"},{"id":"b7l4","block":7,"title":"HBW vs. TSR","sub":"Sichtbarer Bereich und gesamtes Sonnenspektrum trennen"},{"id":"b7l5","block":7,"title":"Solarspektrum","sub":"UV · sichtbar · infrarot richtig gewichten"},{"id":"b7l6","block":7,"title":"Wandaufbau & HBW 20","sub":"WDVS und hochgedämmtes Mauerwerk beurteilen"},{"id":"b7l7","block":7,"title":"TSR 25 & Hersteller","sub":"Thermische Einordnung nach der Dino-Unterlage"},{"id":"b7l8","block":7,"title":"Praxisfälle dunkle Fassaden","sub":"HBW und TSR im richtigen Ablauf anwenden"},{"id":"b8l1","block":8,"title":"BFS 25: Geltungsbereich","sub":"Planung, Ausschreibung, Bemusterung und Abtönung"},{"id":"b8l2","block":8,"title":"BFS 25: Muster & Farbeindruck","sub":"Visueller Vergleich, Farbmusterkarten und Licht"},{"id":"b8l3","block":8,"title":"BFS 25: Oberfläche & Abtönung","sub":"Rauigkeit, Tönung und maschinelle Präzision"},{"id":"b8l4","block":8,"title":"BFS 25: Besondere Übereinstimmung","sub":"Originalmuster, Untergrund und Nachbestellung"},{"id":"b8l5","block":8,"title":"BFS 26: Grundbegriffe & Auswahl","sub":"Beschichtung, Stoff, Bindemittel, Pigment, PVK und Auswahl"},{"id":"b8l6","block":8,"title":"BFS 26: Witterung & Umwelt","sub":"Feuchte, UV, Umwelt und Licht/Dunkelheit"},{"id":"b8l7","block":8,"title":"BFS 26: Produkt & Untergrund","sub":"Pigmente, Bindemittel, PVK und Beschichtungsträger"},{"id":"b8l8","block":8,"title":"BFS 26: Fb-Code & Vergilbung","sub":"A1, Beständigkeitsklassen und Dunkelvergilbung"}];
var LEARNING={"b1l1":[{"title":"Optik","text":"Optik ist die Lehre vom Licht. Sie umfasst Wesen, Entstehung, Ausbreitung und Wechselwirkung des Lichts.","memo":"Merksatz: Optik = Licht verstehen."},{"title":"Licht","text":"Licht wird im Lösungsbogen als vom Auge bewertete elektromagnetische Strahlung beschrieben, die sich in Wellen nach allen Seiten ausbreitet.","memo":"Merksatz: Licht ist elektromagnetische Strahlung, die unser Auge bewertet."}],"b1l2":[{"title":"Sichtbarer Bereich","text":"Für das menschliche Auge nennt die Unterlage den Wellenlängenbereich von 380 nm bis 740 nm.","memo":"Merksatz: Sichtbar = 380–740 nm."},{"title":"Wellenlänge","text":"Die Wellenlänge des sichtbaren Lichts wird in Nanometern (nm) angegeben.","memo":"Merksatz: Lichtwellenlänge → nm."}],"b1l3":[{"title":"Weißes Licht und Prisma","text":"Weißes Licht enthält den sichtbaren Spektralbereich. Im Prisma werden verschiedene Wellenlängen unterschiedlich gebrochen und dadurch getrennt sichtbar.","memo":"Merksatz: Prisma trennt weißes Licht nach Wellenlängen."},{"title":"Spektralfarben","text":"Die Unterlage nennt Rot, Orange, Gelb, Grün, Blau, Indigo und Violett. Rot wird als langwellig, Violett als kurzwellig beschrieben.","memo":"Merksatz: Rot langwellig – Violett kurzwellig."}],"b1l4":[{"title":"Absorption","text":"Absorption bedeutet: Lichtwellen werden vom Untergrund aufgenommen bzw. „verschluckt“.","memo":"Merksatz: Absorption = aufnehmen."},{"title":"Reflexion","text":"Reflexion bedeutet: Lichtwellen werden vom Untergrund zurückgeworfen.","memo":"Merksatz: Reflexion = zurückwerfen."},{"title":"Transmission","text":"Transmission bedeutet: Lichtwellen werden durch den Untergrund hindurchgelassen bzw. scheinen durch.","memo":"Merksatz: Transmission = durchlassen."}],"b1l5":[{"title":"Sättigung","text":"Sättigung beschreibt laut Lösungsbogen den Grad der Buntheit einer Farbe – also wie stark die kräftige Spektralfarbe in ihr enthalten ist.","memo":"Merksatz: Sättigung = Grad der Buntheit."},{"title":"Helligkeit","text":"Helligkeit wird über die Menge des Lichts beschrieben, die von einer Oberfläche reflektiert wird.","memo":"Merksatz: Helligkeit hängt von reflektiertem Licht ab."},{"title":"Gegenstandsfarbe","text":"Gegenstände absorbieren bestimmte Anteile des Lichts und reflektieren andere. Das reflektierte farbige Licht gelangt zu unserem Auge.","memo":"Merksatz: Farbe sehen = Licht auswählen und reflektieren."}],"b2l1":[{"title":"Zwei Arten","text":"Die Unterlage unterscheidet Lichtfarben und Körperfarben. Lichtfarben gehören zum Lichtspektrum; Körperfarben gehen auf Eigenschaften materieller Körper zurück.","memo":"Merksatz: Lichtfarbe leuchtet – Körperfarbe filtert."},{"title":"Zwei Mischprinzipien","text":"Lichtfarben werden additiv gemischt. Körperfarben bzw. Pigmente werden subtraktiv gemischt.","memo":"Merksatz: Licht additiv – Pigment subtraktiv."}],"b2l2":[{"title":"Additive Primärfarben","text":"Der Lösungsbogen nennt Rot, Grün und Blau als Primärfarben der additiven Farbmischung.","memo":"Merksatz: RGB = Rot, Grün, Blau."},{"title":"Prinzip","text":"Bei der additiven Mischung überlagern sich farbige Lichtquellen. Ihre Strahlungsenergie addiert sich; die Mischung wird heller.","memo":"Merksatz: Addieren von Licht macht heller."},{"title":"Endpunkt","text":"Treffen Rot, Grün und Blau in gleicher Menge zusammen, erscheint das Licht laut Lösungsbogen weiß.","memo":"Merksatz: RGB zusammen = Weiß."}],"b2l3":[{"title":"Mischresultate","text":"Als Beispiel nennt „Farben sehen“: rotes + grünes Licht ergibt Gelb. Weitere Überschneidungen ergeben Cyanblau und Magentarot.","memo":"Merksatz: Lichtüberlagerung erzeugt neue Lichtfarben."},{"title":"Vollständige Überlagerung","text":"Wo sich alle drei additiven Lichtfarben überlagern, entsteht weißes Licht.","memo":"Merksatz: Drei additive Grundfarben → Weiß."}],"b2l4":[{"title":"Subtraktive Primärfarben","text":"Der Lösungsbogen nennt Gelb, Cyan und Magenta als Primärfarben der subtraktiven Farbmischung.","memo":"Merksatz: Subtraktiv = Gelb, Cyan, Magenta."},{"title":"Prinzip","text":"Bei der subtraktiven Mischung wird Strahlungsenergie durch Filtern oder Absorbieren weggenommen.","memo":"Merksatz: Subtrahieren = Licht wegnehmen."},{"title":"Endpunkt","text":"Sind Gelb, Cyan und Magenta laut Lösungsbogen gleichzeitig in gleicher Menge beteiligt, entsteht schwarzes Farbmittel.","memo":"Merksatz: GCM zusammen = Schwarz."}],"b2l5":[{"title":"Körperfarben als Filter","text":"Körperfarben absorbieren bestimmte Anteile des Lichts. Mit jeder zusätzlichen Körperfarbe wird mehr Licht herausgefiltert und die Mischung dunkler.","memo":"Merksatz: Mehr Filter → weniger Licht → dunkler."},{"title":"Unterrichtsbeispiel","text":"Die Unterlage nennt: Werden vor eine weiße Lichtquelle Blau und Gelb geschoben, entsteht Grün.","memo":"Merksatz: Subtraktiv arbeitet durch Ausfiltern."}],"b2l6":[{"title":"Der Kernunterschied","text":"Additiv arbeitet mit Lichtquellen und addiert Strahlungsenergie. Subtraktiv arbeitet mit Körperfarben/Pigmenten und entzieht Lichtanteile.","memo":"Merksatz: RGB addiert – GCM/CMYK subtrahiert."},{"title":"Praxisbeispiele","text":"Monitore, Beamer und Leuchtmittel stehen im Lösungsbogen für additive Mischung; Druckerfarben für subtraktive Mischung.","memo":"Merksatz: Bildschirm = Licht, Druck = Pigment."}],"b3l1":[{"title":"Was ist ein Farbkontrast?","text":"Von einem Farbkontrast spricht der Lösungsbogen, wenn zwischen zwei oder mehreren nebeneinanderliegenden Farben deutliche Unterschiede bestehen.","memo":"Merksatz: Kontrast = deutlicher Unterschied nebeneinanderliegender Farben."},{"title":"Farben beeinflussen sich","text":"Kontrastfarben können die Wirkung von Farben verstärken oder abschwächen. Farben beeinflussen sich in ihrer Farbwirkung gegenseitig.","memo":"Merksatz: Farben wirken nicht isoliert – Nachbarfarben verändern die Wirkung."},{"title":"Die sieben Kontraste","text":"Der Lösungsbogen nennt: Farbe-an-sich-, Hell-Dunkel-, Kalt-Warm-, Komplementär-, Simultan-, Quantitäts- und Qualitäts-Kontrast.","memo":"Merksatz: 7 Kontraste – Wirkung, Helligkeit, Temperatur, Gegenfarbe, Auge, Fläche, Sättigung."}],"b3l2":[{"title":"Farbe-an-sich-Kontrast","text":"Er entsteht durch die Nebeneinanderstellung reiner Farben. Die stärkste Kontrastwirkung nennt der Lösungsbogen bei den Primärfarben.","memo":"Merksatz: Reine Farben nebeneinander – Primärfarben wirken am stärksten."}],"b3l3":[{"title":"Hell-Dunkel-Kontrast","text":"Er entsteht durch die Kombination unterschiedlicher Helligkeiten und Tonwerte. Das ist bei bunten und unbunten Farben möglich.","memo":"Merksatz: Hell gegen dunkel – bunt oder unbunt."}],"b3l4":[{"title":"Kalt-Warm-Kontrast","text":"Er kombiniert Farbtöne, die psychologisch als warm bzw. kalt empfunden werden. Als stärkste Wirkung nennt der Lösungsbogen Orange/Rot gegenüber Blau/Grün.","memo":"Merksatz: Warm gegen kalt – besonders stark Orange/Rot gegen Blau/Grün."}],"b3l5":[{"title":"Komplementär-Kontrast","text":"Er entsteht durch die Kombination von Farben, die sich im Farbkreis gegenüberliegen. Der Lösungsbogen beschreibt dabei Primärfarbe und gegenüberliegende Sekundärfarbe.","memo":"Merksatz: Komplementär = im Farbkreis gegenüber."}],"b3l6":[{"title":"Simultan-Kontrast","text":"Beim Simultan-Kontrast ist eine Grundfarbe real vorhanden und wird vom Auge erfasst. Psychologisch wird die zugehörige Komplementärfarbe ungewollt „dazu addiert“.","memo":"Merksatz: Simultan = das Auge ergänzt psychologisch die Komplementärfarbe."}],"b3l7":[{"title":"Quantitäts-Kontrast","text":"Der Quantitäts-Kontrast bezieht sich auf das Größenverhältnis von zwei oder mehreren Farbflächen.","memo":"Merksatz: Quantität = Verhältnis der Flächengrößen."}],"b3l8":[{"title":"Qualitäts-Kontrast","text":"Der Qualitäts-Kontrast beschreibt den Gegensatz von gesättigten, leuchtenden Farben zu getrübten, stumpfen Farben.","memo":"Merksatz: Qualität = leuchtend-gesättigt gegen getrübt-stumpf."}],"b4l1":[{"title":"Linse und Netzhaut","text":"Die Übersicht „Farben sehen“ vergleicht das Auge mit einer Digitalkamera: Einfallendes Licht wird von der Linse fokussiert und gebündelt auf die Netzhaut gelenkt.","memo":"Merksatz: Linse bündelt – Netzhaut empfängt."},{"title":"Iris","text":"Die Iris regelt abhängig von der Helligkeit wie eine Blende die Menge des einfallenden Lichts.","memo":"Merksatz: Iris = Blende des Auges."}],"b4l2":[{"title":"Sensoren der Netzhaut","text":"Die Netzhaut besitzt Sensoren für unterschiedliches Licht. Die Unterlage teilt sie in zwei Arten von Rezeptoren ein: Stäbchen und Zapfen.","memo":"Merksatz: Netzhaut = Rezeptoren für Licht."},{"title":"Vom Reiz zum Gehirn","text":"Die Rezeptoren nehmen Licht auf und erzeugen über eine chemische Reaktion Impulse. Diese werden an das Farbzentrum des Gehirns weitergeleitet.","memo":"Merksatz: Lichtreiz → Rezeptor → Impuls → Gehirn."}],"b4l3":[{"title":"Stäbchen","text":"Stäbchen reagieren laut Übersicht auf alle Farben etwa gleich und erfassen unfarbige Helligkeitseindrücke. Würden wir nur mit Stäbchen sehen, erschiene die Welt schwarzweiß.","memo":"Merksatz: Stäbchen = Hell/Dunkel."},{"title":"Zapfen","text":"Zapfen sind für das Farbsehen zuständig. Die Unterlage nennt drei Arten, die für Rot, Blau und Grün empfindlich sind. Im Gehirn werden Farbbereiche und Helligkeitseindrücke zusammengeführt.","memo":"Merksatz: Zapfen = bunt; Rot, Blau, Grün."}],"b4l4":[{"title":"Heller Tag","text":"Bei hellem Tageslicht arbeiten Zapfen und Stäbchen zusammen.","memo":"Merksatz: Heller Tag = Zapfen + Stäbchen."},{"title":"Dämmerung und Nacht","text":"Mit abnehmendem Licht übernehmen immer stärker die Stäbchen. Im Dunkel der Nacht sind laut Übersicht allein die Stäbchen aktiv.","memo":"Merksatz: Je dunkler, desto mehr Stäbchen."}],"b4l5":[{"title":"Farbfehlsichtigkeit","text":"Die Übersicht führt Farbfehlsichtigkeiten auf einen Defekt einer Zapfenart zurück. Als Beispiel nennt sie die Rot-Grün-Schwäche, bei der Rot und Grün nicht auseinandergehalten werden können.","memo":"Merksatz: Defekte Zapfen können Farbfehlsichtigkeit verursachen."},{"title":"Farbenblindheit","text":"Sind laut Unterlage alle Zapfenarten defekt, wird dies als Farbenblindheit bezeichnet. Außerdem wird angegeben, dass statistisch mehr Männer als Frauen unter diesen Defekten leiden.","memo":"Merksatz: Alle Zapfenarten defekt → Farbenblindheit."}],"b4l6":[{"title":"Farbe entsteht beim Sehen","text":"Die Übersicht betont: Farbe ist nicht einfach „da“, sondern entsteht im Moment des Sehens durch die Zusammenarbeit von Auge und Gehirn.","memo":"Merksatz: Farbwahrnehmung = Auge + Gehirn."},{"title":"Verarbeiten und Interpretieren","text":"Das Gehirn empfängt und verarbeitet Licht- und Helligkeitsimpulse. Jeder Moment des Sehens wird fortlaufend neu verarbeitet und interpretiert. Das Kleid-Beispiel zeigt, dass Menschen dieselbe Abbildung unterschiedlich farbig wahrnehmen können.","memo":"Merksatz: Wahrnehmung wird ständig verarbeitet und interpretiert."}],"b4l7":[{"title":"Definition","text":"Die Unterlage „Licht - Farbtemperatur“ beschreibt die Farbtemperatur als Maß, mit dem der Farbeindruck einer Lichtquelle quantitativ bestimmt wird.","memo":"Merksatz: Farbtemperatur beschreibt den Farbeindruck einer Lichtquelle."},{"title":"Schwarzer Körper und Kelvin","text":"Definiert wird die Farbtemperatur über die Temperatur eines Schwarzen Körpers bzw. Planckschen Strahlers, dessen Lichtwirkung der beschriebenen Farbe unter festgelegten Bedingungen am ähnlichsten ist. Die Einheit ist Kelvin (K).","memo":"Merksatz: Farbtemperatur → Schwarzer Körper → Kelvin."}],"b4l8":[{"title":"Beleuchtung nach Zweck","text":"Die Unterlage empfiehlt tagsüber grundsätzlich neutralweißes Licht und in den Abendstunden warmweißes Licht für eine Wohlfühlatmosphäre. An dunklen Tagen wird eine Lichtfarbe zwischen 6000 und 8000 Kelvin genannt.","memo":"Merksatz: Tag neutralweiß – Abend warmweiß – dunkle Tage 6000–8000 K."},{"title":"Typische Werte aus der Tabelle","text":"Als charakteristische Beispiele nennt die Tabelle unter anderem: Kerze 1500 K, Leuchtstofflampe neutralweiß 4000 K, Vormittags-/Nachmittagssonne 5500 K und bedeckter Himmel 6500–7500 K.","memo":"Merksatz: Kerze 1500 · Neutralweiß 4000 · Sonne 5500 · bedeckter Himmel 6500–7500 K."}],"b5l1":[{"title":"Drei Bezugsgößen","text":"Für eine exakte Farbtonbestimmung nennt der Lösungsbogen drei Bezugsgößen: Farbton, Helligkeit und Sättigung.","memo":"Merksatz: Exakt bestimmen = Farbton + Helligkeit + Sättigung."},{"title":"Beispiel Grün","text":"Die Unterlage verdeutlicht die drei Größen am Beispiel Grün: Farbton = Grün, Helligkeit = helles oder dunkles Grün, Sättigung = schwach oder stark getöntes Grün.","memo":"Merksatz: Was? Wie hell? Wie bunt?"}],"b5l2":[{"title":"CIE-Normvalenzsystem","text":"Der Lösungsbogen beschreibt das CIE-Normvalenzsystem bzw. CIE-Normfarbsystem als ein von der Internationalen Beleuchtungskommission (CIE) definiertes Farbsystem.","memo":"Merksatz: CIE = Internationales Normfarbsystem."},{"title":"Wozu dient es?","text":"Es stellt eine Relation zwischen der menschlichen Farbwahrnehmung und den physikalischen Ursachen des Farbreizes her und erfasst die Gesamtheit wahrnehmbarer Farben.","memo":"Merksatz: CIE verbindet Wahrnehmung und Farbreiz."}],"b5l3":[{"title":"Mögliche Systeme","text":"Als mögliche Farbordnungssysteme nennt der Lösungsbogen RAL Classic, RAL Design und NCS (Natural Colour System).","memo":"Merksatz: RAL Classic · RAL Design · NCS."},{"title":"Zweck der Ordnung","text":"Die Unterlagen behandeln diese Systeme als Hilfen zur eindeutigen Ordnung und Kommunikation von Farben. Beim NCS wird die Farbkommunikation zwischen Designern, Herstellern, Händlern und Kunden ausdrücklich genannt.","memo":"Merksatz: Farbsysteme schaffen gemeinsame Farbbezeichnungen."}],"b5l4":[{"title":"RAL-Classic-Farbordnung","text":"Der Lösungsbogen ordnet die Tausendergruppen so zu: 1000 Gelb, 2000 Orange, 3000 Rot, 4000 Violett, 5000 Blau, 6000 Grün, 7000 Grau, 8000 Braun, 9000 Weiß/Schwarz.","memo":"Merksatz: 1 Gelb · 2 Orange · 3 Rot · 4 Violett · 5 Blau · 6 Grün · 7 Grau · 8 Braun · 9 Weiß/Schwarz."},{"title":"Nummerngruppe lesen","text":"Für die im Unterricht abgefragte Farbordnung ist die erste Tausendergruppe die entscheidende Zuordnung zur Farbfamilie.","memo":"Merksatz: Tausendergruppe → Farbfamilie."}],"b5l5":[{"title":"Einführung und Umfang","text":"Laut Lösungsbogen wurde RAL Design 1993 eingeführt und umfasst 1625 genormte Farben.","memo":"Merksatz: RAL Design: 1993 · 1625 Farben."},{"title":"Systematische Ordnung","text":"RAL Design folgt dem international verwendeten Lab-Farbmaßsystem. Die Farben werden nach Buntton (H, Hue), Helligkeit (L, Lightness) und Buntheit (C, Chroma) systematisch geordnet.","memo":"Merksatz: RAL Design ordnet nach H · L · C."},{"title":"CIELab-Bezug","text":"Der Lösungsbogen sagt, dass die genormten RAL-Design-Farben mit Koordinaten im CIELab-Farbenraum beschrieben werden und verweist auf das 1976 von der CIE festgelegte Lab-Farbmaßsystem.","memo":"Merksatz: RAL Design → CIELab-Koordinaten."}],"b5l6":[{"title":"Der Kernunterschied","text":"Der Lösungsbogen stellt RAL Design der Farbsammlung RAL Classic gegenüber. RAL Design ist nach Buntton, Helligkeit und Buntheit systematisch geordnet.","memo":"Merksatz: RAL Classic = Farbsammlung; RAL Design = systematische Ordnung."},{"title":"Wann ist die Systematik sichtbar?","text":"Bei RAL Design sind H, L und C die ausdrücklich genannten Ordnungskriterien. Die RAL-Classic-Aufgabe arbeitet dagegen mit fest zugeordneten Nummerngruppen für Farbfamilien.","memo":"Merksatz: Design → HLC; Classic → Nummerngruppen."}],"b5l7":[{"title":"Was ist NCS?","text":"NCS steht für Natural Colour System. Laut Lösungsbogen ist es ein branchenübergreifendes Farbsystem zur weltweiten Farbkommunikation. Es basiert darauf, wie Farben visuell wahrgenommen werden.","memo":"Merksatz: NCS = wahrnehmungsbasiertes System zur Farbkommunikation."},{"title":"Beispielcode NCS S 3040-G40Y","text":"Der Lösungsbogen entschlüsselt NCS S 3040-G40Y mit 30 % Schwarzanteil, 40 % Buntanteil und G40Y = Grün mit 40 % Gelbanteil.","memo":"Merksatz: S 3040-G40Y → 30 % Schwarz · 40 % Bunt · Grün mit 40 % Gelb."},{"title":"Bewusst keine Zusatzregel","text":"Der Trainer übernimmt für NCS nur die im Lösungsbogen ausdrücklich gezeigte Dechiffrierung. Ein zusätzlicher Weißanteil wird in diesem Block nicht ausgerechnet, weil er in dieser Aufgabe nicht angegeben wird.","memo":"Merksatz: Nur das abfragen, was die Quelle wirklich vorgibt."}],"b5l8":[{"title":"Signalgelb und Signalrot","text":"Signalgelb: RAL 1003 = Achtung Gefahr; Beispiele sind Hinweise auf Gefahren und Kennzeichnung von Hindernissen. Signalrot: RAL 3001 = Halt! Verbot!; Beispiele sind Verbotszeichen, Haltzeichen und Not-Befehls-Einrichtungen.","memo":"Merksatz: 1003 Gefahr · 3001 Halt/Verbot."},{"title":"Signalblau und Signalgrün","text":"Signalblau: RAL 5005 = Gebote und Hinweise; Beispiel: Verpflichtung zum Tragen der PSA. Signalgrün: RAL 6032 = Sicherheit, Hilfe; Beispiele: Rettungswege, Notausgänge und medizinische Hilfseinrichtungen.","memo":"Merksatz: 5005 Gebot · 6032 Sicherheit/Hilfe."}],"b6l1":[{"title":"Metamerie","text":"Der Lösungsbogen definiert Metamerie so: Zwei Farben sehen bei einer bestimmten Lichtart gleich aus, zeigen aber bei mindestens einer anderen Lichtquelle einen Farbtonunterschied.","memo":"Merksatz: Erst gleich – bei Lichtwechsel verschieden."},{"title":"Entscheidend ist der Lichtwechsel","text":"Für Metamerie reicht nicht allein eine Farbabweichung. Kennzeichnend ist, dass sich die Übereinstimmung der beiden Farben mit der Lichtquelle verändert.","memo":"Merksatz: Metamerie zeigt sich beim Wechsel der Lichtquelle."}],"b6l2":[{"title":"Tageslicht und Kunstlicht","text":"Der Lösungsbogen nennt Tageslicht und Kunstlicht ausdrücklich als Beispiele für unterschiedliche Lichtarten, unter denen ein metameres Farbpaar anders wirken kann.","memo":"Merksatz: Tageslicht ↔ Kunstlicht kann Metamerie sichtbar machen."},{"title":"Nicht jede Abweichung ist Metamerie","text":"Sind zwei Farben schon unter derselben betrachteten Lichtart unterschiedlich, erfüllt dieses Beobachtungsergebnis allein noch nicht die Definition der Metamerie.","memo":"Merksatz: Metamerie braucht Gleichheit bei einer und Unterschied bei einer anderen Lichtquelle."}],"b6l3":[{"title":"Metamere Lichtquellen","text":"Die Farbtemperatur-Unterlage erklärt, dass Lichtquellen mit gleicher Farbtemperatur eine sehr unterschiedliche spektrale Verteilung haben können. Solche Lichtquellen werden dort als metamere Lichtquellen bezeichnet.","memo":"Merksatz: Gleiche Farbtemperatur heißt nicht gleiches Spektrum."},{"title":"Begriff sauber trennen","text":"Die Unterlagen verwenden „Metamerie“ für zwei Farben, deren Übereinstimmung von der Lichtquelle abhängt, und „metamere Lichtquellen“ für Lichtquellen gleicher Farbtemperatur mit unterschiedlicher spektraler Verteilung.","memo":"Merksatz: Metamere Farben ≠ metamere Lichtquellen."}],"b6l4":[{"title":"Kontinuierliches Spektrum","text":"Die Licht-Unterlage nennt Glühlampen als Beispiel dafür, dass metameres Licht ein kontinuierliches Spektrum aufweisen kann.","memo":"Merksatz: Beispiel kontinuierlich → Glühlampe."},{"title":"Schmale Spektralbänder","text":"Energiesparlampen und Flachbildschirme werden als Beispiele genannt, bei denen sich das Licht auf einige schmale Spektralbänder beschränken kann.","memo":"Merksatz: Beispiel Bänder → Energiesparlampe / Flachbildschirm."},{"title":"Folge für die Einordnung","text":"Darum beschreibt eine gleiche Farbtemperatur nach der Unterlage nicht automatisch dieselbe spektrale Zusammensetzung des Lichts.","memo":"Merksatz: Kelvin allein beschreibt nicht das gesamte Spektrum."}],"b6l5":[{"title":"Farbwiedergabeindex","text":"Die Farbtemperatur-Unterlage sagt: Der Farbwiedergabeindex gibt die Qualität der Farbwiedergabe bei Beleuchtung mit einer Lichtquelle an.","memo":"Merksatz: Farbwiedergabeindex = Qualität der Farbwiedergabe."},{"title":"Was die Quelle nicht vorgibt","text":"Die vorliegenden Dino-Unterlagen nennen an dieser Stelle keine konkrete Indexskala, keinen Grenzwert und keine Prüfklasse. Der Trainer ergänzt deshalb keine solchen Zahlen.","memo":"Merksatz: Nur die Bedeutung lernen – keine erfundene Skala."}],"b6l6":[{"title":"Glänzende Oberfläche","text":"Der Lösungsbogen beschreibt glänzende Oberflächen als glatt. Das einfallende Licht wird gleichmäßig gerichtet reflektiert.","memo":"Merksatz: Glatt + gerichtet reflektiert = glänzend."},{"title":"Matte Oberfläche","text":"Matte Oberflächen werden als uneben beschrieben. Das einfallende Licht wird unregelmäßig diffus in mehrere Richtungen reflektiert.","memo":"Merksatz: Uneben + diffus reflektiert = matt."},{"title":"Nicht mit Metamerie verwechseln","text":"Glanz und Mattheit werden in den Unterlagen über die Art der Reflexion erklärt. Das ist eine andere Aussage als die Metamerie-Definition über den Wechsel der Lichtquelle.","memo":"Merksatz: Reflexionsart und Metamerie getrennt beurteilen."}],"b6l7":[{"title":"Farbe entsteht beim Sehen","text":"„Farben sehen“ beschreibt Farbe nicht als etwas, das unabhängig von der Wahrnehmung einfach da ist: Farbwahrnehmung entsteht in der Zusammenarbeit von Auge und Gehirn.","memo":"Merksatz: Farbsehen = Auge + Gehirn."},{"title":"Verarbeitung im Gehirn","text":"Das Gehirn empfängt und verarbeitet die Licht- und Helligkeitsimpulse und interpretiert unser Sehen fortlaufend neu.","memo":"Merksatz: Wahrnehmung wird verarbeitet und interpretiert."},{"title":"Beispiel Kleid","text":"Die Unterlage nutzt das unterschiedlich wahrgenommene Kleid als Beispiel dafür, wie stark Auge und Gehirn gemeinsam die Farbwahrnehmung prägen können.","memo":"Merksatz: Gleicher Reiz kann unterschiedlich wahrgenommen werden."}],"b6l8":[{"title":"Drei Faktoren aus den Unterlagen","text":"Für die Beurteilung von Farbe liefern die vorliegenden Unterlagen drei klar getrennte Einflussbereiche: Lichtquelle bzw. Lichtart, Reflexionsverhalten der Oberfläche sowie Wahrnehmungsverarbeitung durch Auge und Gehirn.","memo":"Merksatz: Licht · Oberfläche · Wahrnehmung auseinanderhalten."},{"title":"Metamerie sicher erkennen","text":"Ein metamerer Fall liegt nach dem Lösungsbogen dann vor, wenn zwei Farben unter einer Lichtart gleich aussehen und bei mindestens einer anderen Lichtquelle einen Farbtonunterschied zeigen.","memo":"Merksatz: Lichtwechsel ist das Erkennungsmerkmal."},{"title":"Bewusst keine Musterflächen-Regel","text":"Die aktuell verwendeten Dino-Unterlagen geben in diesem Themenabschnitt keine konkrete Vorschrift zu Musterflächen oder normierten Beurteilungsbedingungen vor. Solche Regeln werden in diesem Block deshalb nicht ergänzt.","memo":"Merksatz: Keine Regel erfinden, die die Quelle nicht liefert."}],"b7l1":[{"title":"Was der TSR-Wert beschreibt","text":"Der TSR-Wert beschreibt das solare Reflexionsvermögen einer pigmentierten Oberfläche: den Anteil der einfallenden Sonnenstrahlungsenergie, der von der Oberfläche zurückgestrahlt wird.","memo":"Merksatz: TSR = Anteil der Sonnenenergie, der zurückreflektiert wird."},{"title":"Hoher TSR","text":"Je höher der TSR-Wert ist, desto stärker wird die solare Strahlung reflektiert.","memo":"Merksatz: Hoher TSR = viel solare Reflexion."}],"b7l2":[{"title":"Reflexion und Temperatur","text":"Die TSR-Unterlage beschreibt den TSR-Wert als umgekehrt proportional zur Aufheizung: Ein höherer Reflexionswert führt zu einem geringeren Temperaturanstieg gegenüber der Umgebung.","memo":"Merksatz: Mehr TSR → weniger Aufheizung."},{"title":"Oberflächentemperatur","text":"Ein höherer TSR-Wert bewirkt laut Unterlage eine niedrigere Oberflächentemperatur bei Sonneneinstrahlung.","memo":"Merksatz: Hoher TSR entlastet die Oberfläche thermisch."}],"b7l3":[{"title":"NIR-Bereich","text":"Die Unterlage nennt den nahen Infrarotbereich (NIR). Durch Pigmente mit möglichst geringer Absorption im NIR können selbst bei sehr dunklen Farbtönen niedrigere Oberflächentemperaturen erreicht werden.","memo":"Merksatz: Dunkel + NIR-geringe Absorption kann thermisch günstiger sein."},{"title":"Wärmegedämmte Systeme","text":"Gerade bei wärmegedämmten Oberflächen kann sich eine geringere Oberflächentemperatur laut Unterlage möglicherweise vorteilhaft auf die Dauerhaftigkeit des Systems auswirken.","memo":"Merksatz: Weniger Wärmelast kann das System schonen."}],"b7l4":[{"title":"HBW und sichtbares Licht","text":"Der Hellbezugswert (HBW) berücksichtigt laut TSR-Unterlage nur die sichtbare elektromagnetische Strahlung (VIS).","memo":"Merksatz: HBW betrachtet den sichtbaren Bereich."},{"title":"TSR und gesamtes Sonnenspektrum","text":"TSR bezieht sich auf die Energieeinstrahlung im gesamten Sonnenspektrum vom ultravioletten bis zum infraroten Bereich. Deshalb korrelieren TSR und HBW nicht zwingend.","memo":"Merksatz: TSR ist umfassender als HBW."},{"title":"Herstellerbezug","text":"Aufgrund unterschiedlicher und herstellerspezifischer Produktzusammensetzungen können TSR und HBW nicht in gleicher Weise zueinander gesetzt werden. Den TSR-Wert muss der Hersteller bestätigen.","memo":"Merksatz: TSR nicht aus HBW ableiten – Herstellerwert verwenden."}],"b7l5":[{"title":"Verteilung im Sonnenspektrum","text":"Die Grafik der Unterlage teilt die relevante Solarstrahlung mit 3 % ultraviolett, 39 % sichtbar und 58 % infrarot auf.","memo":"Merksatz: 3 % UV · 39 % sichtbar · 58 % IR."},{"title":"Warum HBW allein nicht reicht","text":"Der HBW spiegelt den Farbeindruck im sichtbaren Bereich wider und erfasst damit in der Grafik nur rund 39 % des Energieeintrags des Sonnenlichts.","memo":"Merksatz: Sichtbar ist nur ein Teil der solaren Wärmelast."}],"b7l6":[{"title":"Kritische Wandaufbauten","text":"Eine Bewertung der Machbarkeit bzw. Funktionalität kann insbesondere bei Wärmedämm-Verbundsystemen und hochwärmegedämmtem Mauerwerk notwendig werden.","memo":"Merksatz: WDVS und hochgedämmtes Mauerwerk thermisch mitdenken."},{"title":"HBW > 20 nach Unterlage","text":"Für eine generelle Oberflächenbeschichtung bzw. einen Farbanstrich entsprechend den anerkannten Regeln der Technik ist laut Unterlage derzeit der HBW > 20 heranzuziehen.","memo":"Merksatz: Standardregel der Unterlage: HBW über 20."},{"title":"Grenze der Aussagekraft","text":"Der HBW allein hat laut Unterlage eine unzureichende Aussagekraft hinsichtlich Aufheizverhalten und resultierender Oberflächentemperatur.","memo":"Merksatz: HBW allein beschreibt die thermische Belastung nicht vollständig."}],"b7l7":[{"title":"TSR als umfassendere Beurteilung","text":"Für die physikalische Belastung des Systemaufbaus infolge solarer Einstrahlung trägt der TSR-Wert laut Unterlage umfassender zur Beurteilung bei als der HBW.","memo":"Merksatz: Für Wärmelast ist TSR die umfassendere Größe."},{"title":"TSR ≥ 25 %","text":"Die Unterlage nennt Herstelleruntersuchungen, nach denen ein TSR-Wert von mindestens 25 % für eine funktionstaugliche Ausführung als thermisch sicher einzustufen ist. Die Bewertung bezieht sich auf ASTM G173 (1000 W/m²).","memo":"Merksatz: Dino-Unterlage: TSR ≥ 25 % = thermisch sicher eingeordnet."},{"title":"Bestätigung erforderlich","text":"Der TSR-Wert muss laut Fazit der Unterlage seitens des Herstellers bestätigt werden.","memo":"Merksatz: TSR-Wert vom Hersteller bestätigen lassen."}],"b7l8":[{"title":"Dunkler Farbton","text":"Zur Bewertung der Funktionstauglichkeit einer Beschichtung mit dunklen Farbtönen ist bei Unterschreitung eines HBW von 20 laut Fazit der TSR-Wert heranzuziehen.","memo":"Merksatz: Dunkel und HBW < 20 → TSR prüfen."},{"title":"Entscheidungsfolge","text":"Liegt der bestätigte TSR-Wert bei mindestens 25 %, stuft die verwendete Unterlage die Beschichtung als thermisch sicher ein.","memo":"Merksatz: HBW unter 20 → bestätigten TSR ansehen → ab 25 % thermisch sicher nach Quelle."},{"title":"Quellenkonflikt transparent","text":"Der allgemeine Farbenlehre-Lösungsbogen vereinfacht den Zusammenhang zwischen HBW und TSR. Für diesen Lernblock folgt der Trainer der ausführlicheren TSR-Übersicht, die ausdrücklich sagt, dass beide Werte nicht zwingend korrelieren.","memo":"Merksatz: TSR nicht automatisch aus dem HBW ableiten."}],"b8l1":[{"title":"Geltungsbereich BFS 25","text":"Der Lösungsbogen nennt Festlegungen und Informationen für Planung der Farbgebung, Ausschreibung, Bemusterung und Abtönung von Beschichtungsstoffen sowie deren handwerkliche Verarbeitung.","memo":"Merksatz: BFS 25 begleitet den Farbton von der Planung bis zur Ausführung."},{"title":"Farbunterschiede am Bau","text":"Die Richtlinie beschreibt Farbdifferenzen bei bestimmten Anwendungen von Beschichtungsstoffen in und an Bauwerken.","memo":"Merksatz: BFS 25 = Farbübereinstimmung am Bau beurteilen."},{"title":"Übliche Abmusterung","text":"Farben für handwerklich ausgeführte Beschichtungen an und in Bauwerken werden in aller Regel durch visuellen Vergleich abgemustert.","memo":"Merksatz: Am Bau wird üblicherweise visuell verglichen."}],"b8l2":[{"title":"Farbmusterkarten","text":"Bei Farbmusterkarten ist zu beachten, dass viele Codierungen in unterschiedlichen Farbvarianten im Umlauf sind. Es muss genau bestimmt sein, nach welcher Vorlage die Beschichtung auszuführen ist.","memo":"Merksatz: Farbkarte nur mit eindeutig bestimmter Vorlage verwenden."},{"title":"Farbeindruck","text":"Der Farbeindruck entsteht erst durch Licht bzw. Beleuchtung. Das Auge nimmt bei farbigen Oberflächen die Summe aus Licht und Reflexionseigenschaften der Oberfläche wahr.","memo":"Merksatz: Farbeindruck = Licht + Oberfläche + Wahrnehmung."},{"title":"Metamerie in BFS 25","text":"Die Erscheinung einer Farbe hängt auch vom Spektrum des einwirkenden Lichts bzw. seiner Farbtemperatur ab. Ein unter Kunstlicht fast gleiches Farbpaar kann bei Tageslicht eine deutliche Abweichung zeigen.","memo":"Merksatz: Lichtwechsel kann eine Farbübereinstimmung verändern."}],"b8l3":[{"title":"Rauigkeit","text":"Die Oberflächenstruktur bewirkt Schattenbildung und verhindert gerichtete Reflexion. Gleichfarbige Oberflächen können mit zunehmender Rauigkeit dunkler wirken.","memo":"Merksatz: Rauere Struktur kann gleichfarbig dunkler wirken lassen."},{"title":"Abtönung","text":"Manuell wird mit Volltonfarben, Farbkonzentraten oder durch Mischen abgetönt. Ansonsten werden farbige Beschichtungsstoffe über Tönautomaten beim Hersteller, Handel oder in größeren Malerbetrieben zubereitet.","memo":"Merksatz: Abtönung manuell oder maschinell."},{"title":"Maschinelle Genauigkeit","text":"Die Farbtongenauigkeit der maschinellen Abtönung hängt laut Lösungsbogen von Pflege und Bedienung der Anlage, der Qualität der Rezepturen und Farbpasten sowie den Basismaterialien ab.","memo":"Merksatz: Maschine + Rezeptur + Farbpaste + Basis beeinflussen die Genauigkeit."}],"b8l4":[{"title":"Wann normal nicht reicht","text":"Steht die Beschichtung vor Ort in direktem Bezug zu einer Fläche oder einem Objekt, mit dem sie farblich übereinstimmen muss, reicht die normale Anforderung nicht aus – außer beide sind deutlich durch Abstand, Spalt, Innen- oder Außenecke getrennt.","memo":"Merksatz: Direkter Farbvergleich am Objekt verlangt besondere Übereinstimmung."},{"title":"Originalmuster und Vertragsgrundlage","text":"Bei gewünschter Übereinstimmung mit einem Bauteil oder Einrichtungsgegenstand muss ein Originalmuster vorliegen. Mit dem abgetönten Beschichtungsstoff wird in vorgesehener Applikationstechnik ein Muster angefertigt, verglichen und als Vertragsgrundlage vereinbart. Der Vergleich erfolgt vor Ort.","memo":"Merksatz: Originalmuster + Muster in geplanter Technik + Vergleich vor Ort."},{"title":"Untergrund und Nachbestellung","text":"Bei großem Farbunterschied zum Untergrund sind zusätzliche, auf den Deckbeschichtungston abgestimmte Beschichtungen nötig, bis der Untergrundeinfluss ausgeschaltet ist. Nachbestellungen müssen ausdrücklich als solche bezeichnet und für größtmögliche Übereinstimmung mit Nassmuster versehen werden.","memo":"Merksatz: Untergrund neutralisieren; Nachbestellung kennzeichnen + Nassmuster."}],"b8l5":[{"title":"Beschichtung und Beschichtungsstoff","text":"Eine Beschichtung ist die durch ein- oder mehrmaliges Auftragen entstehende durchgehende Schicht. Der Beschichtungsstoff ist das flüssige, pasten- oder pulverförmige Produkt, das aufgetragen wird und diese Schicht mit bestimmten Eigenschaften ergibt.","memo":"Merksatz: Stoff wird aufgetragen – Beschichtung ist die entstandene Schicht."},{"title":"Bindemittel, Pigment und Farbe","text":"Bindemittel ist der nichtflüchtige Anteil eines Beschichtungsstoffes ohne Pigmente und Füllstoffe. Pigment ist ein unlösliches Farbmittel aus feinen Teilchen. Farbe wird als Sinneseindruck aus visueller Wahrnehmung von Strahlung einer gegebenen spektralen Zusammensetzung beschrieben.","memo":"Merksatz: Bindemittel bindet; Pigment färbt; Farbe wird wahrgenommen."},{"title":"PVK und Auswahl","text":"Die PVK ist das prozentuale Verhältnis des Volumens von Pigmenten, Füllstoffen und anderen nichtfilmbildenden festen Teilchen zum Gesamtvolumen der nichtflüchtigen Anteile. Bei der Stoffauswahl zählen Untergrund, Nutzung, Witterungsbeanspruchung sowie gewünschter Oberflächeneffekt.","memo":"Merksatz: PVK = Festteilvolumen-Anteil; Auswahl nach Untergrund, Nutzung, Witterung, Effekt."}],"b8l6":[{"title":"Witterung, Feuchte und UV","text":"Feuchte und UV-Strahlung greifen die Oberfläche der Beschichtung an und können nicht zu vermeidende Farbveränderungen hervorrufen. In Innenräumen sind diese Einflüsse laut Unterlage in der Regel deutlich geringer.","memo":"Merksatz: Außen wirken Feuchte und UV stark auf die Farbbeständigkeit."},{"title":"Umwelteinflüsse","text":"Als mögliche Ursachen nennt die Unterlage sauren Regen, Industrieabgase, Schmutzablagerungen und mikrobiologischen Befall.","memo":"Merksatz: Umwelt kann Farbe durch Chemie, Schmutz und Bewuchs verändern."},{"title":"Licht und Dunkelheit","text":"Oxidativ trocknende Lacke neigen bei Lichtabschluss, zum Beispiel in Fensterfalzen, zur Vergilbung (Dunkelvergilbung).","memo":"Merksatz: Oxidativ trocknend + Lichtabschluss → Dunkelvergilbung möglich."}],"b8l7":[{"title":"Produktbezogene Faktoren","text":"Die Unterlage nennt als produktbezogene Einflussfaktoren Buntpigmente, Bindemittelart, Glanzgrad/PVK und die Helligkeit des Farbtons. Anorganische Buntpigmente sind in der Regel farbbeständiger als organische; die Farbtonvielfalt ist bei organischen Pigmenten größer.","memo":"Merksatz: Pigment, Bindemittel, PVK/Glanz und Helligkeit beeinflussen die Beständigkeit."},{"title":"Bindemittel und PVK","text":"Bindemittel für Fassadenbeschichtungen sollen möglichst UV-stabil sein. Hochgebundene organische Fassadenfarben mit niedriger PVK binden Pigmente besser ein als schwach gebundene Systeme mit hoher PVK.","memo":"Merksatz: Mehr Bindemittel / niedrigere PVK kann Pigmente besser einbinden."},{"title":"Untergrundbezogene Faktoren","text":"Als Untergrundeinflüsse nennt der Lösungsbogen Alkalität, unterschiedliche Untergründe bzw. Strukturen, Holzinhaltsstoffe und Weichmacher. Feuchte und Wärme können die Wirkung von Holzinhaltsstoffen fördern.","memo":"Merksatz: Auch der Beschichtungsträger kann Farbveränderungen verursachen."}],"b8l8":[{"title":"Fb-Code","text":"Die Tabelle klassifiziert alterungsbedingte Farbveränderungen über Bindemittelklassen A bis C und Pigmentgruppen 1 bis 3. Die Zunahme der Farbveränderung verläuft laut Tabelle von Gruppe 1 zu 2 zu 3 und von Klasse A zu B zu C.","memo":"Merksatz: Im Fb-Code steigt die erwartete Farbveränderung Richtung 3 und Richtung C."},{"title":"A1 bei Lacken","text":"Für Lacke nennt die Tabelle im Feld A1 Acryl-Lack und PUR-Lack.","memo":"Merksatz: A1-Lacke = Acryl und PUR."},{"title":"Dunkelvergilbung","text":"Als zwei Bindemittel bzw. Lackgruppen mit typischer Dunkelvergilbung nennt der Lösungsbogen Alkydharzlacke und Öllacke.","memo":"Merksatz: Alkydharz- und Öllacke können dunkel vergilben."}]};
var EXERCISES=[{"id":"f24-b1-l1-q01","lesson":"b1l1","prompt":"Was versteht der Lösungsbogen unter „Optik“?","options":["Die Lehre vom Licht.","Die Lehre von Pigmenten.","Die Lehre von Farbsystemen.","Die Lehre von Beschichtungsstoffen."],"correct":0,"why":"Optik wird im Dino-Lösungsbogen als Lehre vom Licht definiert.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l1-q02","lesson":"b1l1","prompt":"Welche vier Bereiche umfasst die Optik laut Unterrichtsunterlage?","options":["Wesen, Entstehung, Ausbreitung und Wechselwirkung des Lichts.","Farbton, Glanz, Deckvermögen und Verlauf.","Absorption, Härte, Haftung und Dichte.","Pigment, Bindemittel, Lösemittel und Additive."],"correct":0,"why":"Die Definition nennt ausdrücklich Wesen, Entstehung, Ausbreitung und Wechselwirkung des Lichts.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l1-q03","lesson":"b1l1","prompt":"Wie wird „Licht“ im Farbenlehre-Lösungsbogen beschrieben?","options":["Als vom Auge bewertete elektromagnetische Strahlung.","Als ausschließlich sichtbare Wärmeenergie.","Als reflektiertes Pigment ohne Strahlung.","Als mechanische Schwingung von Oberflächen."],"correct":0,"why":"Der Lösungsbogen beschreibt Licht als vom Auge bewertete elektromagnetische Strahlung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l1-q04","lesson":"b1l1","prompt":"Wie breitet sich Licht laut Lösungsbogen aus?","options":["In Wellen nach allen Seiten.","Nur geradlinig nach unten.","Ausschließlich in festen Stoffen.","Nur in Richtung einer reflektierenden Fläche."],"correct":0,"why":"Die Unterrichtsdefinition ergänzt, dass sich Licht in Wellen nach allen Seiten ausbreitet.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l2-q01","lesson":"b1l2","prompt":"Welcher Wellenlängenbereich ist für das menschliche Auge laut Unterlage sichtbar?","options":["Etwa 380–740 nm.","Etwa 80–240 nm.","Etwa 740–1400 nm.","Etwa 10–80 nm."],"correct":0,"why":"Der Dino-Lösungsbogen nennt 380 bis 740 Nanometer als sichtbaren Bereich.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l2-q02","lesson":"b1l2","prompt":"Welche Einheit wird in der Unterlage für die Wellenlänge des sichtbaren Lichts verwendet?","options":["Nanometer (nm).","Kelvin (K).","Pascal (Pa).","Lux pro Quadratmeter (lx/m²)."],"correct":0,"why":"Der sichtbare Wellenlängenbereich wird mit 380–740 nm angegeben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l2-q03","lesson":"b1l2","prompt":"Liegt eine Wellenlänge von 700 nm im in der Unterlage genannten sichtbaren Bereich?","options":["Ja, sie liegt zwischen 380 und 740 nm.","Nein, sichtbar beginnt erst oberhalb 740 nm.","Nein, sichtbar endet bereits bei 500 nm.","Nur bei völliger Dunkelheit."],"correct":0,"why":"700 nm liegt innerhalb des angegebenen Bereichs von 380 bis 740 nm.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l2-q04","lesson":"b1l2","prompt":"Welche Aussage passt zum sichtbaren Bereich nach der Dino-Unterlage?","options":["380 nm markiert ungefähr die kurzwellige Grenze des genannten Bereichs.","380 nm ist die Einheit der Farbtemperatur.","740 nm ist laut Unterlage die kurzwellige Grenze.","Der sichtbare Bereich wird in Prozent angegeben."],"correct":0,"why":"Die Unterlage grenzt den sichtbaren Bereich mit 380 nm und 740 nm ein.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l3-q01","lesson":"b1l3","prompt":"Wann werden die Spektralfarben nach der Unterlage sichtbar?","options":["Wenn weißes Licht im Prisma nach Wellenlängen unterschiedlich gebrochen wird.","Wenn alle Lichtwellen vollständig absorbiert werden.","Wenn eine Oberfläche nur matt geschliffen wird.","Wenn Pigmente ohne Licht miteinander vermischt werden."],"correct":0,"why":"Im Prisma werden verschiedene Wellenlängen unterschiedlich stark gebrochen; dadurch werden die Spektralfarben sichtbar.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l3-q02","lesson":"b1l3","prompt":"Welche Reihe nennt die Spektralfarben in der Unterrichtsunterlage?","options":["Rot, Orange, Gelb, Grün, Blau, Indigo, Violett.","Rot, Braun, Beige, Grau, Schwarz, Weiß, Gold.","Cyan, Magenta, Gelb, Schwarz, Weiß, Grau, Silber.","Gelb, Ocker, Umbra, Siena, Grün, Blau, Schwarz."],"correct":0,"why":"Der Lösungsbogen nennt Rot, Orange, Gelb, Grün, Blau, Indigo und Violett.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l3-q03","lesson":"b1l3","prompt":"Warum werden verschiedene Spektralfarben im Prisma getrennt sichtbar?","options":["Weil Strahlung verschiedener Wellenlängen unterschiedlich gebrochen wird.","Weil jede Farbe dieselbe Wellenlänge besitzt.","Weil das Prisma alle Farben schwarz färbt.","Weil nur die Helligkeit, nicht aber die Wellenlänge verändert wird."],"correct":0,"why":"Die unterschiedliche Brechung der Wellenlängen trennt das weiße Licht in sichtbare Spektralfarben.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l3-q04","lesson":"b1l3","prompt":"Welche Aussage zu Rot und Violett gibt der Lösungsbogen beim Regenbogen an?","options":["Rot hat eine lange, Violett eine kurze Wellenlänge.","Rot und Violett haben exakt dieselbe Wellenlänge.","Violett hat die längere Wellenlänge als Rot.","Die Wellenlänge spielt beim Regenbogen keine Rolle."],"correct":0,"why":"Die Unterrichtsantwort begründet die Anordnung mit langer Wellenlänge bei Rot und kurzer bei Violett.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l3-q05","lesson":"b1l3","prompt":"Wodurch entsteht ein Regenbogen nach dem Hinweis im Lösungsbogen?","options":["Durch gebrochenes Licht an Wassertropfen eines Regenschauers.","Durch Pigmentmischung in der Luft.","Durch vollständige Absorption des Sonnenlichts.","Durch Wärmeleitung zwischen Regentropfen."],"correct":0,"why":"Der Lösungsbogen nennt gebrochenes Licht an Wassertropfen als Ursache.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q01","lesson":"b1l4","prompt":"Was bedeutet „Absorption“ bei Licht?","options":["Lichtwellen werden vom Untergrund aufgenommen bzw. „verschluckt“.","Lichtwellen werden gerichtet zurückgeworfen.","Lichtwellen scheinen vollständig durch.","Lichtwellen werden in Kelvin umgerechnet."],"correct":0,"why":"Die Dino-Unterlage beschreibt Absorption als Aufnehmen bzw. Verschlucken von Lichtwellen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q02","lesson":"b1l4","prompt":"Was bedeutet „Reflexion“ bei Licht?","options":["Lichtwellen werden vom Untergrund zurückgeworfen.","Lichtwellen werden vollständig aufgenommen.","Lichtwellen werden durch den Untergrund geleitet.","Lichtwellen verlieren ihre Wellenlänge vollständig."],"correct":0,"why":"Reflexion ist laut Lösungsbogen das Zurückwerfen von Lichtwellen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q03","lesson":"b1l4","prompt":"Was bedeutet „Transmission“ bei Licht?","options":["Lichtwellen werden durch den Untergrund hindurchgelassen.","Lichtwellen werden vollständig absorbiert.","Lichtwellen werden ausschließlich zurückgeworfen.","Lichtwellen werden in Pigmente umgewandelt."],"correct":0,"why":"Transmission wird in der Unterlage als Durchscheinen bzw. Durchlassen beschrieben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q04","lesson":"b1l4","prompt":"Eine Oberfläche wirft einfallendes Licht zurück. Welcher Vorgang ist gemeint?","options":["Reflexion.","Absorption.","Transmission.","Sättigung."],"correct":0,"why":"Zurückgeworfenes Licht entspricht der Reflexion.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q05","lesson":"b1l4","prompt":"Licht wird von einem Material aufgenommen und nicht zurückgeworfen. Welcher Begriff passt?","options":["Absorption.","Transmission.","Reflexion.","Farbtemperatur."],"correct":0,"why":"Aufgenommenes bzw. verschlucktes Licht ist Absorption.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l4-q06","lesson":"b1l4","prompt":"Licht kann durch ein Material hindurchscheinen. Welcher Vorgang beschreibt das?","options":["Transmission.","Absorption.","Reflexion.","Metamerie."],"correct":0,"why":"Durchscheinen bzw. Hindurchlassen von Licht wird als Transmission bezeichnet.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l5-q01","lesson":"b1l5","prompt":"Was beschreibt die „Sättigung“ laut Farbenlehre-Lösungsbogen?","options":["Den Grad der Buntheit einer Farbe.","Die Temperatur einer Lichtquelle.","Die Dicke einer Beschichtung.","Die Menge des Bindemittels."],"correct":0,"why":"Sättigung gibt laut Lösungsbogen an, wie stark die ursprünglich kräftige Spektralfarbe enthalten ist und damit den Grad der Buntheit.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l5-q02","lesson":"b1l5","prompt":"Was beschreibt die „Helligkeit“ laut Lösungsbogen?","options":["Die Menge des Lichts, die von einer Oberfläche reflektiert wird.","Die Anzahl der verwendeten Pigmente.","Die Temperatur des Untergrunds.","Die Wellenlänge eines einzelnen Bindemittels."],"correct":0,"why":"Helligkeit wird dort über die von einer Oberfläche reflektierte Lichtmenge beschrieben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l5-q03","lesson":"b1l5","prompt":"Welche drei Bezugsgößen nennt der Farbenlehre-Lösungsbogen für eine exakte Farbtonbestimmung?","options":["Farbton, Helligkeit und Sättigung.","Glanz, Viskosität und Dichte.","Deckkraft, Trocknung und Haftung.","Kelvin, Lux und Pascal."],"correct":0,"why":"Im Lösungsbogen werden Farbton, Helligkeit und Sättigung als drei Bezugsgößen genannt.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b1-l5-q04","lesson":"b1l5","prompt":"Wie erhalten Gegenstände nach „Farben sehen“ ihre sichtbare Farbe?","options":["Sie absorbieren bestimmte Strahlungsanteile und reflektieren andere.","Sie erzeugen ohne Licht selbst immer dieselbe Spektralfarbe.","Sie wandeln jede Strahlung vollständig in Wärme um.","Sie lassen grundsätzlich alle Wellenlängen unverändert durch."],"correct":0,"why":"Die Unterlage erklärt Gegenstandsfarben über unterschiedlich absorbierte und reflektierte Anteile des Lichts.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b1-l5-q05","lesson":"b1l5","prompt":"Was sehen wir nach der Unterlage im Grunde, wenn wir die Farbe eines Gegenstands wahrnehmen?","options":["Farbiges Licht, das über die Oberfläche des Gegenstands zu uns gelangt.","Das Bindemittel des Gegenstands ohne Lichteinfluss.","Ausschließlich die Temperatur der Oberfläche.","Nur die mechanische Struktur des Materials."],"correct":0,"why":"„Farben sehen“ beschreibt Farbe als wahrgenommenes farbiges Licht, das über die Oberfläche eines Gegenstands zu uns gelangt.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l1-q01","lesson":"b2l1","prompt":"Welche zwei Grundarten von Farben unterscheidet „Farben sehen“ für die Farbmischung?","options":["Lichtfarben und Körperfarben.","Primärfarben und Lackfarben.","Mineralfarben und Metallfarben.","Deckfarben und Lasurfarben."],"correct":0,"why":"Die Unterlage unterscheidet grundsätzlich Lichtfarben und Körperfarben.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l1-q02","lesson":"b2l1","prompt":"Womit sind Lichtfarben in der Unterlage verbunden?","options":["Mit farbigen Lichtquellen und dem Lichtspektrum.","Nur mit gedruckten Pigmenten.","Nur mit mineralischen Untergründen.","Mit der Schichtdicke eines Lackfilms."],"correct":0,"why":"Lichtfarben tauchen im Lichtspektrum auf und werden bei der additiven Mischung durch Lichtquellen überlagert.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l1-q03","lesson":"b2l1","prompt":"Worauf gehen Körperfarben laut „Farben sehen“ zurück?","options":["Auf die Eigenschaften materieller Körper.","Ausschließlich auf elektrische Spannung.","Nur auf die Temperatur einer Lampe.","Auf die Lautstärke einer Lichtquelle."],"correct":0,"why":"Körperfarben werden in der Unterlage auf Eigenschaften materieller Körper zurückgeführt.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l1-q04","lesson":"b2l1","prompt":"Welches Beispiel nennt der Lösungsbogen für additive Farbmischung?","options":["Monitore, Beamer oder Leuchtmittel.","Druckerfarben.","Putzmörtel.","Holzlasuren ohne Lichteinwirkung."],"correct":0,"why":"Für additive Farbmischung nennt der Lösungsbogen Monitore, Beamer und Leuchtmittel.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l1-q05","lesson":"b2l1","prompt":"Welches Beispiel nennt der Lösungsbogen für subtraktive Farbmischung?","options":["Druckerfarben.","Beamerlicht.","Monitore.","Leuchtmittel."],"correct":0,"why":"Der Lösungsbogen nennt Druckerfarben als Beispiel für subtraktive Pigmentmischung.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l2-q01","lesson":"b2l2","prompt":"Welche Primärfarben nennt der Lösungsbogen für die additive Farbmischung?","options":["Rot, Grün und Blau.","Cyan, Magenta und Gelb.","Rot, Gelb und Schwarz.","Orange, Violett und Braun."],"correct":0,"why":"Der Lösungsbogen nennt Grün, Rot und Blau als Primärfarben der additiven Lichtmischung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l2-q02","lesson":"b2l2","prompt":"Was wird bei der additiven Farbmischung miteinander gemischt?","options":["Farbige Lichtquellen bzw. Lichtfarben.","Ausschließlich Pigmente.","Bindemittel und Lösemittel.","Nur schwarze und weiße Körperfarben."],"correct":0,"why":"Additive Farbmischung entsteht durch Addition farbiger Lichtquellen.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l2-q03","lesson":"b2l2","prompt":"Was entsteht laut Lösungsbogen, wenn Rot, Grün und Blau als Lichtfarben in gleicher Menge zusammentreffen?","options":["Weißes Licht.","Schwarzes Farbmittel.","Braunes Pigment.","Transparentes Bindemittel."],"correct":0,"why":"Gleich große Anteile der drei additiven Primärfarben ergeben laut Lösungsbogen weißes Licht.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l2-q04","lesson":"b2l2","prompt":"Warum werden Mischungen bei additiver Farbmischung heller?","options":["Weil sich die Strahlungsenergie der Lichtfarben addiert.","Weil immer mehr Licht absorbiert wird.","Weil Pigmente chemisch schwarz reagieren.","Weil die Farbtemperatur automatisch auf 0 K fällt."],"correct":0,"why":"„Farben sehen“ erklärt die Aufhellung damit, dass sich die Strahlungsenergie der Lichtfarben addiert.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l2-q05","lesson":"b2l2","prompt":"Unter welcher Kurzbezeichnung ist die additive Farbmischung im Lösungsbogen bekannt?","options":["RGB-System.","CMYK-System.","NCS-System.","RAL-Classic-System."],"correct":0,"why":"Der Lösungsbogen nennt für die additive Farbmischung das RGB-System.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l2-q06","lesson":"b2l2","prompt":"Welche Farbe gehört NICHT zu den additiven Primärfarben des Lösungsbogens?","options":["Cyan.","Rot.","Grün.","Blau."],"correct":0,"why":"Cyan gehört nicht zum dort genannten additiven Primärfarbensatz Rot, Grün, Blau.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l3-q01","lesson":"b2l3","prompt":"Welche Lichtfarbe entsteht laut „Farben sehen“, wenn rotes und grünes Licht überlagert werden?","options":["Gelb.","Schwarz.","Blau.","Grau."],"correct":0,"why":"Die Unterlage nennt Rot + Grün als Beispiel und gibt Gelb als Mischfarbe an.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l3-q02","lesson":"b2l3","prompt":"Welche Farbe entsteht in der Mitte, wenn sich die drei additiven Lichtfarben vollständig überlagern?","options":["Weiß.","Schwarz.","Braun.","Grau."],"correct":0,"why":"Bei vollständiger Überlagerung der drei Lichtfarben entsteht laut Unterlage weißes Licht.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l3-q03","lesson":"b2l3","prompt":"Welche zwei weiteren Mischfarben nennt „Farben sehen“ bei den übrigen Überschneidungen zusätzlich zu Gelb?","options":["Cyanblau und Magentarot.","Braun und Grau.","Ocker und Umbra.","Schwarz und Weiß."],"correct":0,"why":"Die Unterlage nennt bei den weiteren Überschneidungen Cyanblau und Magentarot.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l3-q04","lesson":"b2l3","prompt":"Zwei Scheinwerfer projizieren rotes und grünes Licht auf dieselbe Stelle. Welche Farbe ist nach dem Unterrichtsbeispiel zu erwarten?","options":["Gelb.","Schwarz.","Cyan.","Violett."],"correct":0,"why":"Das Unterrichtsbeispiel zur additiven Mischung: rotes + grünes Licht ergibt Gelb.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l3-q05","lesson":"b2l3","prompt":"Was passiert mit der Helligkeit, wenn bei additiver Mischung weitere Lichtanteile hinzukommen?","options":["Die Mischung wird heller.","Die Mischung wird grundsätzlich dunkler.","Die Helligkeit bleibt immer unverändert.","Die Mischung wird automatisch schwarz."],"correct":0,"why":"Bei additiver Mischung addiert sich Strahlungsenergie; dadurch entstehen hellere Farbtöne.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l3-q06","lesson":"b2l3","prompt":"Welche Kombination kennzeichnet das Endergebnis der additiven Grundfarben im Lösungsbogen richtig?","options":["Rot + Grün + Blau → Weiß.","Cyan + Magenta + Gelb → Weiß.","Rot + Grün + Blau → Schwarz.","Gelb + Cyan + Magenta → Rot."],"correct":0,"why":"Der Lösungsbogen ordnet Weiß der gleichzeitigen additiven Mischung von Rot, Grün und Blau zu.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l4-q01","lesson":"b2l4","prompt":"Welche Primärfarben nennt der Lösungsbogen für die subtraktive Farbmischung?","options":["Gelb, Cyan und Magenta.","Rot, Grün und Blau.","Rot, Orange und Gelb.","Blau, Grün und Schwarz."],"correct":0,"why":"Der Lösungsbogen nennt Gelb, Cyan und Magenta als Primärfarben der subtraktiven Pigmentmischung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l4-q02","lesson":"b2l4","prompt":"Was wird bei der subtraktiven Farbmischung laut Lösungsbogen gemischt?","options":["Pigmente bzw. Farbmittel.","Nur farbige Lichtkegel.","Nur elektrische Signale.","Ausschließlich transparente Bindemittel."],"correct":0,"why":"Der Lösungsbogen beschreibt die subtraktive Farbmischung als Pigmentmischung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l4-q03","lesson":"b2l4","prompt":"Was bedeutet „subtraktiv“ in der Erklärung von „Farben sehen“?","options":["Strahlungsenergie wird durch Filtern oder Absorbieren weggenommen.","Strahlungsenergie wird durch Lichtquellen addiert.","Pigmente erzeugen ohne Licht neue Strahlung.","Alle Wellenlängen werden stärker reflektiert."],"correct":0,"why":"Subtraktiv bedeutet dort, dass durch Ausfiltern bzw. Absorbieren Strahlungsenergie entzogen wird.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l4-q04","lesson":"b2l4","prompt":"Was geschieht laut Unterlage, wenn immer mehr Körperfarben miteinander gemischt werden?","options":["Das Ergebnis wird dunkler.","Das Ergebnis wird immer heller.","Das Ergebnis wird zwingend weiß.","Die Helligkeit bleibt unabhängig von der Mischung gleich."],"correct":0,"why":"Mit jeder zusätzlichen Körperfarbe wird Licht entzogen; deshalb wird die Mischung dunkler.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l4-q05","lesson":"b2l4","prompt":"Was entsteht laut Lösungsbogen, wenn Gelb, Cyan und Magenta in gleicher Menge beteiligt sind?","options":["Schwarzes Farbmittel.","Weißes Licht.","Reines Rotlicht.","Transparentes Material."],"correct":0,"why":"Der Lösungsbogen beschreibt als Endergebnis der drei subtraktiven Primärfarben schwarzes Farbmittel.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l4-q06","lesson":"b2l4","prompt":"Unter welcher Kurzbezeichnung führt der Lösungsbogen die subtraktive Farbmischung?","options":["CMYK-System.","RGB-System.","NCS-System.","CIE-RGB-Lichtsystem."],"correct":0,"why":"Im Unterrichts-Lösungsbogen wird die subtraktive Mischung als CMYK-System bezeichnet.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l5-q01","lesson":"b2l5","prompt":"Wie wirken Körperfarben bei der subtraktiven Mischung nach „Farben sehen“?","options":["Wie Filter, die bestimmte Lichtanteile absorbieren.","Wie zusätzliche Lichtquellen, die Strahlung erzeugen.","Wie Spiegel, die immer sämtliche Wellenlängen vollständig reflektieren.","Wie Wärmequellen ohne Einfluss auf Licht."],"correct":0,"why":"Körperfarben werden in der Unterlage als Filter beschrieben, die bestimmte Teile des Lichts absorbieren.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l5-q02","lesson":"b2l5","prompt":"Welche Mischfarbe nennt „Farben sehen“ beim Vorschalten von Blau und Gelb vor eine weiße Lichtquelle?","options":["Grün.","Rot.","Schwarz.","Magenta."],"correct":0,"why":"Die Unterlage nennt Blau und Gelb vor einer weißen Lichtquelle als Beispiel für Grün.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l5-q03","lesson":"b2l5","prompt":"Warum wird eine subtraktive Mischung mit zusätzlichen Körperfarben dunkler?","options":["Weil jede weitere Körperfarbe zusätzliche Lichtanteile herausfiltert.","Weil zusätzliche Lichtquellen Strahlungsenergie addieren.","Weil die Wellenlänge jeder Farbe auf 0 nm sinkt.","Weil automatisch mehr weißes Licht erzeugt wird."],"correct":0,"why":"Mit jeder weiteren Körperfarbe wird laut Unterlage Licht abgezogen.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l5-q04","lesson":"b2l5","prompt":"Ein Verfahren nimmt Strahlungsenergie durch Absorption aus dem Licht heraus. Welche Mischungsart ist gemeint?","options":["Subtraktive Farbmischung.","Additive Farbmischung.","Nur Reflexion ohne Farbmischung.","Farbtemperaturmessung."],"correct":0,"why":"Das Wegnehmen von Strahlungsenergie durch Filtern oder Absorbieren kennzeichnet die subtraktive Mischung.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b2-l5-q05","lesson":"b2l5","prompt":"Welches Praxisbeispiel passt am besten zur subtraktiven Farbmischung nach dem Lösungsbogen?","options":["Mehrere Druckerfarben werden miteinander kombiniert.","Rotes und grünes Scheinwerferlicht überlagern sich.","Drei farbige Lichtkegel eines Beamers überlagern sich.","Ein Monitor erzeugt Farben aus Lichtpunkten."],"correct":0,"why":"Druckerfarben werden im Lösungsbogen ausdrücklich als Beispiel für subtraktive Pigmentmischung genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q01","lesson":"b2l6","prompt":"Welche Zuordnung ist nach den Unterrichtsunterlagen richtig?","options":["Additiv = Lichtfarben; subtraktiv = Körperfarben/Pigmente.","Additiv = Pigmente; subtraktiv = nur Lichtfarben.","Additiv = RAL; subtraktiv = NCS.","Additiv = matt; subtraktiv = glänzend."],"correct":0,"why":"Die Unterlagen trennen additive Lichtmischung und subtraktive Körper-/Pigmentmischung.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q02","lesson":"b2l6","prompt":"Welche System-Zuordnung verwendet der Lösungsbogen?","options":["Additiv → RGB; subtraktiv → CMYK.","Additiv → CMYK; subtraktiv → RGB.","Additiv → NCS; subtraktiv → RAL Classic.","Additiv → BFS 25; subtraktiv → BFS 26."],"correct":0,"why":"RGB wird dort der additiven, CMYK der subtraktiven Farbmischung zugeordnet.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q03","lesson":"b2l6","prompt":"Welche Endergebnisse werden in den Lösungsbögen gegenübergestellt?","options":["Additiv: Weiß; subtraktiv: Schwarz.","Additiv: Schwarz; subtraktiv: Weiß.","Beide Mischungen ergeben immer Grau.","Beide Mischungen ergeben immer Gelb."],"correct":0,"why":"Die Unterrichtsantworten geben Weiß für die drei additiven und Schwarz für die drei subtraktiven Primärfarben an.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q04","lesson":"b2l6","prompt":"Du mischst farbige Lichtkegel eines Beamers. Welche Mischungsart trainierst du?","options":["Additive Farbmischung.","Subtraktive Farbmischung.","Nur Transmission.","Pigmentalterung."],"correct":0,"why":"Beamer werden im Lösungsbogen als Beispiel für additive Lichtmischung genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q05","lesson":"b2l6","prompt":"Du kombinierst Druckerfarben. Welche Mischungsart ist nach dem Lösungsbogen gemeint?","options":["Subtraktive Farbmischung.","Additive Farbmischung.","Nur Reflexion.","Farbtemperaturmischung."],"correct":0,"why":"Druckerfarben werden ausdrücklich als Beispiel der subtraktiven Mischung genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b2-l6-q06","lesson":"b2l6","prompt":"Welche Wirkung unterscheidet beide Mischungsarten in der Dino-Unterlage am klarsten?","options":["Additiv addiert Lichtenergie und wird heller; subtraktiv filtert Licht und wird dunkler.","Beide addieren Lichtenergie und werden heller.","Beide filtern Licht und werden dunkler.","Additiv und subtraktiv unterscheiden sich nur im Namen."],"correct":0,"why":"Die Unterlagen stellen genau diesen Gegensatz heraus: Strahlungsenergie addieren versus Lichtanteile herausfiltern.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b3-l1-q01","lesson":"b3l1","prompt":"Wann spricht man laut Lösungsbogen von einem Farbkontrast?","options":["Wenn zwischen zwei oder mehreren nebeneinanderliegenden Farben deutliche Unterschiede bestehen.","Wenn zwei Farben exakt gleich aussehen.","Wenn nur eine einzelne Farbe ohne Umgebung betrachtet wird.","Wenn ausschließlich die Schichtdicke einer Beschichtung verändert wird."],"correct":0,"why":"Der Lösungsbogen definiert Farbkontrast über deutliche Unterschiede zwischen nebeneinanderliegenden Farben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l1-q02","lesson":"b3l1","prompt":"Welche Aussage zur Farbwirkung trifft der Lösungsbogen?","options":["Farben können sich gegenseitig in ihrer Wirkung beeinflussen.","Farben wirken unabhängig von allen Nachbarfarben immer gleich.","Nur unbunte Farben beeinflussen einander.","Kontraste verändern ausschließlich die Trocknungszeit."],"correct":0,"why":"Die Unterlage sagt ausdrücklich, dass sich Farben in ihrer Farbwirkung gegenseitig beeinflussen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l1-q03","lesson":"b3l1","prompt":"Wie können Kontrastfarben die Wirkung einer Farbe beeinflussen?","options":["Sie können die Farbwirkung verstärken oder abschwächen.","Sie können nur die Farbwirkung vollständig aufheben.","Sie verändern nur die physische Schichtdicke.","Sie wirken ausschließlich auf den Glanzgrad."],"correct":0,"why":"Der Lösungsbogen nennt sowohl Verstärkung als auch Abschwächung der Farbwirkung.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l1-q04","lesson":"b3l1","prompt":"Welche Aufzählung enthält nur die sieben im Lösungsbogen genannten Farbkontraste?","options":["Farbe-an-sich, Hell-Dunkel, Kalt-Warm, Komplementär, Simultan, Quantität, Qualität.","Additiv, subtraktiv, Reflexion, Transmission, Absorption, Glanz, Metamerie.","RAL, NCS, CIE, RGB, CMYK, HBW, TSR.","Farbton, Helligkeit, Sättigung, Deckkraft, Verlauf, Härte, Haftung."],"correct":0,"why":"Genau diese sieben Kontrastarten werden in Aufgabe 14 des Farbenlehre-Lösungsbogens genannt.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l1-q05","lesson":"b3l1","prompt":"Zwei nebeneinanderliegende Farben unterscheiden sich deutlich und verändern dadurch ihre gegenseitige Wirkung. Welcher Oberbegriff passt?","options":["Farbkontrast.","Transmission.","Farbmischung.","Absorption."],"correct":0,"why":"Deutliche Unterschiede nebeneinanderliegender Farben und gegenseitige Wirkungsbeeinflussung kennzeichnen den Farbkontrast.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l1-q06","lesson":"b3l1","prompt":"Welche Beobachtung passt am besten zum Grundgedanken der Farbkontraste?","options":["Die Wirkung einer Farbe kann sich durch eine benachbarte Farbe verändern.","Eine Farbe wirkt unabhängig von ihrer Umgebung immer identisch.","Nur die Materialdicke bestimmt die wahrgenommene Farbwirkung.","Kontraste entstehen ausschließlich durch Lichtdurchlässigkeit."],"correct":0,"why":"Die Unterlage betont die gegenseitige Beeinflussung der Farbwirkung.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q01","lesson":"b3l2","prompt":"Wie entsteht der Farbe-an-sich-Kontrast?","options":["Durch die Nebeneinanderstellung reiner Farben.","Durch unterschiedliche Größen von Farbflächen.","Durch den Gegensatz von hell und dunkel.","Durch psychologisch ergänzte Komplementärfarben."],"correct":0,"why":"Der Lösungsbogen definiert ihn als Nebeneinanderstellung reiner Farben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q02","lesson":"b3l2","prompt":"Wann ist der Farbe-an-sich-Kontrast laut Lösungsbogen am stärksten?","options":["Bei Primärfarben.","Bei ausschließlich unbunten Grautönen.","Bei identischen Farbtönen.","Bei möglichst ähnlichen Helligkeiten ohne Buntheit."],"correct":0,"why":"Die stärkste Kontrastwirkung wird bei den Primärfarben genannt.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q03","lesson":"b3l2","prompt":"Welche Eigenschaft steht beim Farbe-an-sich-Kontrast im Mittelpunkt?","options":["Die Eigenwirkung reiner Farbtöne nebeneinander.","Das Größenverhältnis der Farbflächen.","Der Unterschied zwischen gesättigt und getrübt.","Die psychologische Ergänzung einer Gegenfarbe."],"correct":0,"why":"Entscheidend ist die Nebeneinanderstellung reiner Farben.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q04","lesson":"b3l2","prompt":"Wodurch unterscheidet sich der Farbe-an-sich-Kontrast vom Hell-Dunkel-Kontrast?","options":["Er beruht auf reinen Farbtönen, nicht primär auf unterschiedlichen Helligkeiten.","Er beruht ausschließlich auf Flächengrößen.","Er entsteht nur durch Komplementärfarben.","Er setzt eine psychologisch ergänzte Farbe voraus."],"correct":0,"why":"Beim Farbe-an-sich-Kontrast stehen reine Farben nebeneinander; Hell-Dunkel beruht auf Helligkeits- und Tonwertunterschieden.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q05","lesson":"b3l2","prompt":"Mehrere reine, deutlich verschiedene Farbtöne stehen direkt nebeneinander. Welcher Kontrast ist gemeint?","options":["Farbe-an-sich-Kontrast.","Quantitäts-Kontrast.","Simultan-Kontrast.","Hell-Dunkel-Kontrast."],"correct":0,"why":"Reine Farben nebeneinander kennzeichnen den Farbe-an-sich-Kontrast.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l2-q06","lesson":"b3l2","prompt":"Eine Gestaltung soll den stärksten Farbe-an-sich-Kontrast nach dem Lösungsbogen nutzen. Welche Auswahl passt?","options":["Primärfarben nebeneinander.","Zwei identische Grautöne.","Nur unterschiedlich große Flächen derselben Farbe.","Eine reale Grundfarbe mit psychologisch ergänzter Gegenfarbe."],"correct":0,"why":"Der Lösungsbogen nennt die Primärfarben als stärkste Form des Farbe-an-sich-Kontrasts.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q01","lesson":"b3l3","prompt":"Wodurch entsteht der Hell-Dunkel-Kontrast?","options":["Durch unterschiedliche Helligkeiten und Tonwerte.","Durch gegenüberliegende Farben im Farbkreis.","Nur durch unterschiedliche Flächengrößen.","Durch psychologisch ergänzte Komplementärfarben."],"correct":0,"why":"Der Lösungsbogen nennt unterschiedliche Helligkeiten und Tonwerte als Grundlage.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q02","lesson":"b3l3","prompt":"Bei welchen Farben ist der Hell-Dunkel-Kontrast möglich?","options":["Bei bunten und unbunten Farben.","Nur bei Primärfarben.","Nur bei unbunten Farben.","Nur bei Komplementärfarben."],"correct":0,"why":"Die Unterlage sagt ausdrücklich: bei bunten und unbunten Farben möglich.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q03","lesson":"b3l3","prompt":"Welcher Unterschied ist für den Hell-Dunkel-Kontrast entscheidend?","options":["Der Helligkeits- bzw. Tonwertunterschied.","Der Flächenanteil allein.","Die Lage im Farbkreis allein.","Die Frage, ob eine Farbe psychologisch ergänzt wird."],"correct":0,"why":"Der Kontrast beruht auf verschiedenen Helligkeiten und Tonwerten.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q04","lesson":"b3l3","prompt":"Warum kann ein Hell-Dunkel-Kontrast auch mit unbunten Farben entstehen?","options":["Weil unterschiedliche Helligkeiten und Tonwerte ausreichen.","Weil unbunte Farben immer Primärfarben sind.","Weil unbunte Farben im Farbkreis gegenüberliegen.","Weil unbunte Farben stets gesättigt leuchten."],"correct":0,"why":"Für den Hell-Dunkel-Kontrast sind Helligkeits- und Tonwertunterschiede entscheidend, nicht Buntheit.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q05","lesson":"b3l3","prompt":"Zwei Flächen unterscheiden sich vor allem durch deutlich verschiedene Helligkeiten. Welcher Kontrast liegt nahe?","options":["Hell-Dunkel-Kontrast.","Quantitäts-Kontrast.","Farbe-an-sich-Kontrast.","Simultan-Kontrast."],"correct":0,"why":"Deutlich verschiedene Helligkeiten kennzeichnen den Hell-Dunkel-Kontrast.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l3-q06","lesson":"b3l3","prompt":"Eine bunte helle Fläche steht neben einer deutlich dunkleren bunten Fläche. Welcher Kontrast kann dadurch entstehen?","options":["Hell-Dunkel-Kontrast.","Nur Qualitäts-Kontrast.","Nur Simultan-Kontrast.","Kein Farbkontrast, weil beide Flächen bunt sind."],"correct":0,"why":"Der Hell-Dunkel-Kontrast ist laut Unterlage ausdrücklich auch bei bunten Farben möglich.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q01","lesson":"b3l4","prompt":"Was wird beim Kalt-Warm-Kontrast kombiniert?","options":["Psychologisch warm und kalt empfundene Farbtöne.","Nur unterschiedlich große Farbflächen.","Nur reine Primärfarben.","Gesättigte und getrübte Farben unabhängig von Temperaturwirkung."],"correct":0,"why":"Der Lösungsbogen definiert den Kontrast über warm bzw. kalt psychologisch empfundene Farbtöne.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q02","lesson":"b3l4","prompt":"Welche Kombination nennt der Lösungsbogen als stärkste Kalt-Warm-Kontrastwirkung?","options":["Orange/Rot gegenüber Blau/Grün.","Gelb gegenüber Weiß.","Schwarz gegenüber Grau.","Cyan gegenüber Magenta unabhängig von Temperaturempfinden."],"correct":0,"why":"Als stärkste Wirkung nennt die Unterlage Orange/Rot und Blau/Grün.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q03","lesson":"b3l4","prompt":"Worauf bezieht sich „kalt“ und „warm“ in diesem Kontrast?","options":["Auf die psychologische Empfindung der Farbtöne.","Auf die gemessene Oberflächentemperatur.","Auf die Trocknungstemperatur der Beschichtung.","Auf den Flammpunkt des Materials."],"correct":0,"why":"Im Lösungsbogen steht ausdrücklich „psychologisch empfundenen Farbtönen“.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q04","lesson":"b3l4","prompt":"Was unterscheidet den Kalt-Warm-Kontrast vom Komplementär-Kontrast?","options":["Kalt-Warm beruht auf Temperaturempfinden, Komplementär auf gegenüberliegenden Farben im Farbkreis.","Kalt-Warm beruht auf Flächengröße, Komplementär auf Helligkeit.","Kalt-Warm beruht auf Sättigung, Komplementär auf Transmission.","Zwischen beiden gibt es laut Lösungsbogen keinen Unterschied."],"correct":0,"why":"Die beiden Definitionen nutzen unterschiedliche Kriterien: psychologische Temperaturwirkung versus Gegenüberlage im Farbkreis.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q05","lesson":"b3l4","prompt":"Eine Gestaltung stellt psychologisch warm wirkende Rot-/Orangetöne kalten Blau-/Grüntönen gegenüber. Welcher Kontrast wird betont?","options":["Kalt-Warm-Kontrast.","Quantitäts-Kontrast.","Hell-Dunkel-Kontrast.","Simultan-Kontrast."],"correct":0,"why":"Rot/Orange gegen Blau/Grün wird im Lösungsbogen als besonders starke Kalt-Warm-Wirkung genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l4-q06","lesson":"b3l4","prompt":"Bei einer Beurteilung geht es nicht um die reale Materialtemperatur, sondern darum, ob Farbtöne warm oder kalt wirken. Welcher Kontrast ist relevant?","options":["Kalt-Warm-Kontrast.","Qualitäts-Kontrast.","Quantitäts-Kontrast.","Farbe-an-sich-Kontrast."],"correct":0,"why":"Die Unterlage beschreibt den Kalt-Warm-Kontrast ausdrücklich als psychologische Empfindung.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q01","lesson":"b3l5","prompt":"Wie definiert der Lösungsbogen den Komplementär-Kontrast?","options":["Als Kombination von Farben, die im Farbkreis gegenüberliegen.","Als Kombination unterschiedlich großer Farbflächen.","Als Gegensatz von gesättigt und getrübt.","Als Unterschied zwischen hell und dunkel."],"correct":0,"why":"Komplementärfarben liegen laut Lösungsbogen im Farbkreis gegenüber.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q02","lesson":"b3l5","prompt":"Welche Beziehung nennt der Lösungsbogen beim Komplementär-Kontrast?","options":["Primärfarbe und gegenüberliegende Sekundärfarbe.","Zwei identische Primärfarben.","Nur zwei unbunte Farben.","Zwei Farben mit gleichem Tonwert."],"correct":0,"why":"Die Unterrichtsdefinition nennt Primär- und gegenüberliegende Sekundärfarbe.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q03","lesson":"b3l5","prompt":"Welches Kriterium entscheidet beim Komplementär-Kontrast?","options":["Die Gegenüberlage der Farben im Farbkreis.","Nur die Flächengröße.","Nur die Helligkeit.","Nur der Grad der Buntheit."],"correct":0,"why":"Kennzeichen ist die Lage der Farben zueinander im Farbkreis.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q04","lesson":"b3l5","prompt":"Was unterscheidet Komplementär- und Simultan-Kontrast grundlegend?","options":["Beim Komplementär-Kontrast werden gegenüberliegende Farben kombiniert; beim Simultan-Kontrast wird die Komplementärfarbe psychologisch ergänzt.","Beim Komplementär-Kontrast geht es nur um Helligkeit; beim Simultan-Kontrast nur um Flächengröße.","Beide Kontraste werden im Lösungsbogen identisch definiert.","Der Simultan-Kontrast betrifft nur unbunte Farben."],"correct":0,"why":"Komplementär beschreibt reale Gegenfarben im Farbkreis, Simultan die psychologische Ergänzung der Gegenfarbe.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q05","lesson":"b3l5","prompt":"Zwei verwendete Farbtöne liegen sich im Farbkreis gegenüber. Welcher Kontrast ist gemeint?","options":["Komplementär-Kontrast.","Quantitäts-Kontrast.","Qualitäts-Kontrast.","Hell-Dunkel-Kontrast."],"correct":0,"why":"Gegenüberliegende Farben im Farbkreis kennzeichnen den Komplementär-Kontrast.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l5-q06","lesson":"b3l5","prompt":"Eine Primärfarbe wird gezielt mit ihrer gegenüberliegenden Sekundärfarbe kombiniert. Welcher Kontrast wird nach dem Lösungsbogen genutzt?","options":["Komplementär-Kontrast.","Farbe-an-sich-Kontrast allein.","Simultan-Kontrast ohne reale Gegenfarbe.","Quantitäts-Kontrast."],"correct":0,"why":"Genau diese Beziehung nennt die Unterrichtsdefinition des Komplementär-Kontrasts.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q01","lesson":"b3l6","prompt":"Was geschieht beim Simultan-Kontrast laut Lösungsbogen psychologisch?","options":["Die zugehörige Komplementärfarbe wird ungewollt „dazu addiert“.","Die Grundfarbe wird vollständig unsichtbar.","Die Fläche wird physisch größer.","Die Farbe wird automatisch heller."],"correct":0,"why":"Die Unterlage beschreibt eine psychologisch ungewollt dazu addierte Komplementärfarbe.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q02","lesson":"b3l6","prompt":"Welche Farbe ist beim Simultan-Kontrast laut Definition real vorhanden?","options":["Die Grundfarbe.","Nur die psychologisch ergänzte Komplementärfarbe.","Keine Farbe.","Ausschließlich eine unbunte Farbe."],"correct":0,"why":"Der Lösungsbogen sagt: Die Grundfarbe ist real vorhanden und wird vom Auge erfasst.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q03","lesson":"b3l6","prompt":"Warum ist der Simultan-Kontrast kein bloßes Nebeneinander zweier real aufgetragener Komplementärfarben?","options":["Weil die Komplementärfarbe psychologisch vom Auge ergänzt wird.","Weil beim Simultan-Kontrast nur die Flächengröße zählt.","Weil beim Simultan-Kontrast keine Grundfarbe vorhanden ist.","Weil der Effekt ausschließlich durch Helligkeitsunterschiede entsteht."],"correct":0,"why":"Das besondere Merkmal ist die psychologische Ergänzung der zugehörigen Komplementärfarbe.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q04","lesson":"b3l6","prompt":"Welche Aussage trifft den Simultan-Kontrast am genauesten?","options":["Eine reale Grundfarbe wird wahrgenommen; das Auge ergänzt psychologisch ihre Komplementärfarbe.","Zwei real vorhandene Farben müssen nur unterschiedlich groß sein.","Zwei reine Primärfarben müssen nebeneinanderliegen.","Gesättigte und getrübte Farben werden gegenübergestellt."],"correct":0,"why":"Das entspricht der Formulierung des Lösungsbogens.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q05","lesson":"b3l6","prompt":"Eine Komplementärfarbe ist nicht real aufgetragen, wird aber durch die Wahrnehmung zur Grundfarbe psychologisch ergänzt. Welcher Kontrast liegt vor?","options":["Simultan-Kontrast.","Komplementär-Kontrast als reine reale Farbkombination.","Quantitäts-Kontrast.","Hell-Dunkel-Kontrast."],"correct":0,"why":"Psychologisch ergänzte Komplementärfarbe ist das Kennzeichen des Simultan-Kontrasts.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l6-q06","lesson":"b3l6","prompt":"Bei einer Farbwahrnehmung „erzeugt“ das Auge zur realen Grundfarbe ungewollt die zugehörige Gegenfarbe. Wie heißt dieser Effekt im Lösungsbogen?","options":["Simultan-Kontrast.","Qualitäts-Kontrast.","Farbe-an-sich-Kontrast.","Kalt-Warm-Kontrast."],"correct":0,"why":"Der Simultan-Kontrast wird genau so beschrieben.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q01","lesson":"b3l7","prompt":"Worauf bezieht sich der Quantitäts-Kontrast?","options":["Auf das Größenverhältnis von zwei oder mehreren Farbflächen.","Auf den Grad der Buntheit.","Auf die Lage im Farbkreis.","Auf psychologisch warme und kalte Farbtöne."],"correct":0,"why":"Der Lösungsbogen definiert den Quantitäts-Kontrast über das Größenverhältnis von Farbflächen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q02","lesson":"b3l7","prompt":"Welcher Begriff passt zum Verhältnis der Flächengrößen verschiedener Farben?","options":["Quantitäts-Kontrast.","Qualitäts-Kontrast.","Simultan-Kontrast.","Komplementär-Kontrast."],"correct":0,"why":"Quantität bezieht sich in der Unterrichtsdefinition auf die Größe der Farbflächen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q03","lesson":"b3l7","prompt":"Was ist beim Quantitäts-Kontrast das entscheidende Gestaltungsmerkmal?","options":["Wie groß die beteiligten Farbflächen im Verhältnis zueinander sind.","Ob die Farben im Farbkreis gegenüberliegen.","Ob eine Farbe leuchtend oder getrübt ist.","Ob eine Farbe warm oder kalt empfunden wird."],"correct":0,"why":"Entscheidend ist das Größenverhältnis der Farbflächen.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q04","lesson":"b3l7","prompt":"Wodurch unterscheidet sich Quantitäts- vom Qualitäts-Kontrast?","options":["Quantität betrifft Flächengrößen; Qualität betrifft gesättigt-leuchtend gegenüber getrübt-stumpf.","Quantität betrifft Helligkeit; Qualität betrifft nur Farbkreispositionen.","Quantität betrifft Temperaturwirkung; Qualität betrifft Transmission.","Beide beruhen laut Lösungsbogen ausschließlich auf Flächengrößen."],"correct":0,"why":"Die Definitionen unterscheiden Größenverhältnis und Farbsättigungs-/Leuchtwirkungs-Gegensatz.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q05","lesson":"b3l7","prompt":"Zwei Farbflächen werden vor allem wegen ihres stark unterschiedlichen Flächenanteils miteinander verglichen. Welcher Kontrast ist gemeint?","options":["Quantitäts-Kontrast.","Kalt-Warm-Kontrast.","Simultan-Kontrast.","Farbe-an-sich-Kontrast."],"correct":0,"why":"Der Größenanteil der Farbflächen ist das Merkmal des Quantitäts-Kontrasts.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l7-q06","lesson":"b3l7","prompt":"Bei einer Gestaltung wird nur das Verhältnis „kleine Farbfläche zu großer Farbfläche“ verändert. Welcher Kontrast wird damit unmittelbar beeinflusst?","options":["Quantitäts-Kontrast.","Komplementär-Kontrast.","Hell-Dunkel-Kontrast.","Simultan-Kontrast."],"correct":0,"why":"Das Größenverhältnis der Flächen ist die Definition des Quantitäts-Kontrasts.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q01","lesson":"b3l8","prompt":"Welchen Gegensatz beschreibt der Qualitäts-Kontrast?","options":["Gesättigte, leuchtende Farben gegenüber getrübten, stumpfen Farben.","Große Farbflächen gegenüber kleinen Farbflächen.","Warme Farbtöne gegenüber kalten Farbtönen.","Gegenüberliegende Farben im Farbkreis."],"correct":0,"why":"Der Lösungsbogen definiert genau diesen Gegensatz.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q02","lesson":"b3l8","prompt":"Welche Farbbeschreibung gehört zur einen Seite des Qualitäts-Kontrasts?","options":["Gesättigt und leuchtend.","Nur großflächig.","Nur hell und unbunt.","Ausschließlich psychologisch ergänzt."],"correct":0,"why":"Die Unterlage nennt gesättigte, leuchtende Farben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q03","lesson":"b3l8","prompt":"Welche Farbbeschreibung bildet laut Lösungsbogen den Gegenpol beim Qualitäts-Kontrast?","options":["Getrübt und stumpf.","Nur kleinflächig.","Immer komplementär.","Nur kalt empfunden."],"correct":0,"why":"Getrübte, stumpfe Farben stehen den gesättigten, leuchtenden gegenüber.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q04","lesson":"b3l8","prompt":"Worauf zielt der Qualitäts-Kontrast im Unterschied zum Quantitäts-Kontrast?","options":["Auf den Gegensatz der Farbqualität bzw. Sättigungswirkung statt auf Flächengrößen.","Auf die Flächengröße statt auf die Farbwirkung.","Nur auf die Lage im Farbkreis.","Nur auf unterschiedliche Helligkeiten."],"correct":0,"why":"Qualität beschreibt leuchtend/gesättigt gegen getrübt/stumpf; Quantität das Größenverhältnis.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q05","lesson":"b3l8","prompt":"Eine stark gesättigte, leuchtende Farbe steht neben einer getrübten, stumpfen Farbe. Welcher Kontrast entsteht?","options":["Qualitäts-Kontrast.","Quantitäts-Kontrast.","Simultan-Kontrast.","Kalt-Warm-Kontrast."],"correct":0,"why":"Das ist die Definition des Qualitäts-Kontrasts aus dem Lösungsbogen.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b3-l8-q06","lesson":"b3l8","prompt":"Bei einer Gestaltung bleibt die Flächengröße gleich, aber eine Farbe ist leuchtend gesättigt und die andere stumpf getrübt. Welcher Kontrast steht im Vordergrund?","options":["Qualitäts-Kontrast.","Quantitäts-Kontrast.","Hell-Dunkel-Kontrast zwingend.","Komplementär-Kontrast zwingend."],"correct":0,"why":"Der relevante Gegensatz ist gesättigt-leuchtend zu getrübt-stumpf und damit Qualität.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b4-l1-q01","lesson":"b4l1","prompt":"Welche Aufgabe hat die Linse laut „Farben sehen“?","options":["Sie fokussiert das einfallende Licht.","Sie erzeugt die Lichtfarbe.","Sie misst die Farbtemperatur.","Sie ersetzt die Netzhaut."],"correct":0,"why":"Die Unterlage sagt, dass das einfallende Licht von der Linse fokussiert wird.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l1-q02","lesson":"b4l1","prompt":"Wohin fällt das von der Linse gebündelte Licht?","options":["Auf die Netzhaut.","Auf die Iris.","Auf den Sehnerv vor der Linse.","Auf die Pupille als Rezeptorfläche."],"correct":0,"why":"Das fokussierte Licht fällt gebündelt auf die Netzhaut.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l1-q03","lesson":"b4l1","prompt":"Welche Aufgabe übernimmt die Iris in der Beschreibung des Auges?","options":["Sie regelt je nach Helligkeit die Menge des Lichts.","Sie erzeugt die Nervenimpulse.","Sie unterscheidet Rot und Grün.","Sie bündelt das Licht auf der Netzhaut."],"correct":0,"why":"Die Iris wird mit einer Blende verglichen und regelt die Lichtmenge.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l1-q04","lesson":"b4l1","prompt":"Womit vergleicht die Unterlage die Iris funktional?","options":["Mit einer Blende.","Mit einem Farbkreis.","Mit einem Pigmentfilter.","Mit einem Prisma."],"correct":0,"why":"Die Iris regelt die Lichtmenge „wie eine Blende“.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l1-q05","lesson":"b4l1","prompt":"Bei wechselnder Helligkeit muss im Auge die einfallende Lichtmenge geregelt werden. Welches Bauteil nennt die Unterlage dafür?","options":["Die Iris.","Die Netzhaut.","Die Linse allein.","Den Sehnerv."],"correct":0,"why":"Die Iris regelt abhängig von der Helligkeit die Menge des Lichts.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l1-q06","lesson":"b4l1","prompt":"Welche Reihenfolge entspricht der Beschreibung in „Farben sehen“?","options":["Einfallendes Licht → Linse fokussiert → Licht fällt gebündelt auf die Netzhaut.","Netzhaut → Linse erzeugt Licht → Iris färbt es.","Iris → Netzhaut fokussiert → Linse empfängt Impulse.","Sehnerv → Linse → Licht entsteht auf der Iris."],"correct":0,"why":"So beschreibt die Unterlage den optischen Weg des einfallenden Lichts.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q01","lesson":"b4l2","prompt":"Wo befinden sich laut Unterlage die Sensoren, die unterschiedliches Licht aufnehmen?","options":["Auf der Netzhaut.","In der Linse.","In der Iris.","Im Glaskörper als Lichtquelle."],"correct":0,"why":"Die Netzhaut besitzt die lichtempfindlichen Sensoren.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q02","lesson":"b4l2","prompt":"In wie viele Arten von Rezeptoren teilt die Übersicht die lichtaufnehmenden Sensoren ein?","options":["In zwei Arten.","In eine Art.","In vier Arten.","In sieben Arten."],"correct":0,"why":"Die Unterlage spricht von zwei Arten von Rezeptoren.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q03","lesson":"b4l2","prompt":"Was erzeugen die Rezeptoren über eine chemische Reaktion?","options":["Impulse.","Pigmente.","Kelvinwerte.","Spektralfarben im Prisma."],"correct":0,"why":"Über eine chemische Reaktion entstehen Impulse.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q04","lesson":"b4l2","prompt":"Wohin werden die von den Rezeptoren erzeugten Impulse weitergeleitet?","options":["An das Farbzentrum des Gehirns.","An die Linse.","An die Iris.","An die Oberfläche des Gegenstands."],"correct":0,"why":"Die Impulse werden laut Übersicht an das Farbzentrum des Gehirns weitergeleitet.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q05","lesson":"b4l2","prompt":"Welche Prozesskette passt zur Unterrichtsunterlage?","options":["Lichtaufnahme → chemische Reaktion → Impulse → Farbzentrum des Gehirns.","Farbzentrum → Pigmentbildung → Linse → Lichtquelle.","Iris → Kelvinmessung → Netzhaut → Prisma.","Lichtaufnahme → Druckfarbe → Absorption → Farbsystem."],"correct":0,"why":"Genau diese Abfolge wird für die Rezeptoren beschrieben.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l2-q06","lesson":"b4l2","prompt":"Ein Lichtreiz wird auf der Netzhaut aufgenommen. Was folgt laut Beschreibung, bevor das Gehirn ihn verarbeitet?","options":["Die Rezeptoren erzeugen über eine chemische Reaktion Impulse.","Die Iris wandelt ihn in Pigmente um.","Die Linse berechnet die Farbtemperatur.","Die Netzhaut erzeugt unmittelbar eine Körperfarbe."],"correct":0,"why":"Zwischen Lichtaufnahme und Verarbeitung im Gehirn stehen die von den Rezeptoren erzeugten Impulse.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l3-q01","lesson":"b4l3","prompt":"Welche Rezeptoren erfassen laut Farbenlehre-Lösungsbogen unfarbige Helligkeitseindrücke?","options":["Die Stäbchen.","Die Zapfen.","Die Iris.","Die Linse."],"correct":0,"why":"Der Lösungsbogen ordnet Hell/Dunkel bzw. unfarbige Helligkeitseindrücke den Stäbchen zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b4-l3-q02","lesson":"b4l3","prompt":"Welche Rezeptoren sind für unterschiedliche Farbeindrücke zuständig?","options":["Die Zapfen.","Die Stäbchen.","Die Iris.","Der Sehnerv allein."],"correct":0,"why":"Der Lösungsbogen ordnet die bunte Wahrnehmung den Zapfen zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b4-l3-q03","lesson":"b4l3","prompt":"Für welche drei Farbbereiche nennt „Farben sehen“ unterschiedliche Zapfenarten?","options":["Rot, Blau und Grün.","Rot, Gelb und Schwarz.","Cyan, Magenta und Gelb.","Orange, Violett und Weiß."],"correct":0,"why":"Die Übersicht nennt drei Zapfenarten für Rot, Blau und Grün.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l3-q04","lesson":"b4l3","prompt":"Wie beschreibt die Unterlage die Reaktion der Stäbchen auf Farben?","options":["Sie reagieren auf alle Farben etwa gleich.","Sie reagieren nur auf Rot.","Sie reagieren nur auf Grün und Blau.","Sie reagieren ausschließlich auf Weiß."],"correct":0,"why":"Stäbchen reagieren laut Übersicht auf alle Farben etwa gleich und liefern Helligkeitseindrücke.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l3-q05","lesson":"b4l3","prompt":"Wie würde die Welt laut Unterlage erscheinen, wenn wir nur mit Stäbchen sehen würden?","options":["Schwarzweiß.","Nur rot.","Nur blau.","Unverändert bunt."],"correct":0,"why":"Die Übersicht sagt ausdrücklich, dass die Welt bei reinem Stäbchensehen schwarzweiß erschiene.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l3-q06","lesson":"b4l3","prompt":"Für eine bunte Wahrnehmung werden laut Übersicht im Gehirn welche Informationen zusammengeführt?","options":["Die drei Farbbereiche der Zapfen und die entsprechenden Helligkeitseindrücke.","Nur die Flächengröße farbiger Gegenstände.","Nur die Kelvinzahl der Lichtquelle.","Ausschließlich die Signale der Iris."],"correct":0,"why":"Die Unterlage erklärt buntes Sehen durch das Zusammenführen der drei Farbbereiche und Helligkeitseindrücke.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q01","lesson":"b4l4","prompt":"Welche Rezeptoren arbeiten laut Übersicht bei hellem Tag zusammen?","options":["Zapfen und Stäbchen.","Nur Stäbchen.","Nur Zapfen.","Iris und Linse ohne Rezeptoren."],"correct":0,"why":"Bei hellem Tag arbeiten Zapfen und Stäbchen zusammen.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q02","lesson":"b4l4","prompt":"Welche Rezeptoren sind laut Unterlage im Dunkel der Nacht allein aktiv?","options":["Die Stäbchen.","Die Zapfen.","Die Iris.","Die Linse."],"correct":0,"why":"Im Dunkel der Nacht sind laut Übersicht allein die Stäbchen aktiv.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q03","lesson":"b4l4","prompt":"Was geschieht mit abnehmendem Licht und Beginn der Dämmerung?","options":["Immer mehr übernehmen die Stäbchen das Sehen.","Immer mehr übernehmen ausschließlich die Zapfen.","Die Netzhaut stellt ihre Arbeit vollständig ein.","Die Iris ersetzt die Rezeptoren."],"correct":0,"why":"Die Unterlage beschreibt den zunehmenden Anteil der Stäbchen bei sinkender Helligkeit.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q04","lesson":"b4l4","prompt":"Welche Reihenfolge entspricht dem Übergang vom Tag zur Nacht?","options":["Tag: Zapfen + Stäbchen → Dämmerung: zunehmend Stäbchen → Nacht: Stäbchen allein.","Tag: nur Stäbchen → Dämmerung: nur Zapfen → Nacht: beide.","Tag: nur Zapfen → Dämmerung: Iris allein → Nacht: Linse allein.","Tag: Netzhaut aus → Dämmerung: Netzhaut an → Nacht: Zapfen allein."],"correct":0,"why":"So beschreibt die Übersicht die Verschiebung der Rezeptorarbeit bei abnehmendem Licht.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q05","lesson":"b4l4","prompt":"Es wird immer dunkler. Welcher Rezeptortyp gewinnt laut Unterrichtsunterlage zunehmend an Bedeutung?","options":["Die Stäbchen.","Die Zapfen.","Die Iris.","Die Linse."],"correct":0,"why":"Mit abnehmendem Licht übernehmen immer stärker die Stäbchen.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l4-q06","lesson":"b4l4","prompt":"Eine Beobachtung findet im Dunkel der Nacht statt. Welcher Wahrnehmungsanteil steht nach der Unterlage im Vordergrund?","options":["Unfarbige Helligkeitseindrücke über die Stäbchen.","Bunte Wahrnehmung ausschließlich über Zapfen.","Farbtemperaturmessung durch die Iris.","Additive Farbmischung in der Linse."],"correct":0,"why":"Da nachts allein die Stäbchen aktiv sind, steht die unfarbige Helligkeitswahrnehmung im Vordergrund.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q01","lesson":"b4l5","prompt":"Wann kommt es laut Übersicht zu Farbfehlsichtigkeiten?","options":["Wenn eine Zapfenart defekt ist.","Wenn eine Stäbchenart eine größere Fläche hat.","Wenn die Iris heller gefärbt ist.","Wenn die Linse Licht fokussiert."],"correct":0,"why":"Die Unterlage nennt einen Defekt einer Zapfenart als Ursache für Farbfehlsichtigkeit.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q02","lesson":"b4l5","prompt":"Welches Beispiel für eine Farbfehlsichtigkeit nennt die Unterlage?","options":["Die Rot-Grün-Schwäche.","Die Hell-Dunkel-Schwäche der Iris.","Die Kelvin-Schwäche.","Die Reflexionsschwäche der Linse."],"correct":0,"why":"Als bekanntes Beispiel wird die Rot-Grün-Schwäche genannt.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q03","lesson":"b4l5","prompt":"Was können Betroffene mit Rot-Grün-Schwäche laut Übersicht nicht sicher auseinanderhalten?","options":["Rot und Grün.","Blau und Weiß.","Schwarz und Weiß.","Gelb und Violett in jedem Fall."],"correct":0,"why":"Die Unterlage beschreibt die Rot-Grün-Schwäche genau so.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q04","lesson":"b4l5","prompt":"Wie nennt die Unterlage den Zustand, wenn alle Zapfenarten defekt sind?","options":["Farbenblindheit.","Metamerie.","Farbtemperatur.","Quantitäts-Kontrast."],"correct":0,"why":"Sind alle Zapfenarten defekt, spricht die Übersicht von Farbenblindheit.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q05","lesson":"b4l5","prompt":"Bei einer Person ist laut Unterrichtsmodell eine Zapfenart defekt. Welche Einordnung passt?","options":["Es kann eine Farbfehlsichtigkeit vorliegen.","Es liegt automatisch eine höhere Farbtemperatur vor.","Es ist zwingend nur das Stäbchensehen betroffen.","Es handelt sich um additive Farbmischung."],"correct":0,"why":"Die Unterlage verknüpft den Defekt einer Zapfenart mit Farbfehlsichtigkeit.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l5-q06","lesson":"b4l5","prompt":"Warum kann eine Rot-Grün-Schwäche laut Unterlage im Straßenverkehr, etwa bei Ampeln, Schwierigkeiten verursachen?","options":["Weil Betroffene Rot und Grün nicht auseinanderhalten können.","Weil die Iris dann keine Lichtmenge mehr regelt.","Weil Stäbchen ausschließlich rotes Licht aufnehmen.","Weil die Farbtemperatur von Ampeln nicht in Kelvin angegeben wird."],"correct":0,"why":"Die Übersicht nennt den Straßenverkehr mit Ampeln als Beispiel und erklärt die Schwierigkeit mit der fehlenden Unterscheidung von Rot und Grün.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q01","lesson":"b4l6","prompt":"Wann entsteht Farbe laut Abschnitt „Auge und Gehirn – ein gutes Team“?","options":["Im Moment des Sehens.","Erst beim Trocknen eines Pigments.","Nur beim Messen in Kelvin.","Ausschließlich im Prisma."],"correct":0,"why":"Die Unterlage sagt ausdrücklich, Farbe entstehe im Moment des Sehens.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q02","lesson":"b4l6","prompt":"Woraus besteht unsere Farbwahrnehmung laut Übersicht?","options":["Aus der Zusammenarbeit zwischen Auge und Gehirn.","Nur aus der Arbeit der Iris.","Nur aus der Oberflächenstruktur.","Nur aus der Farbtemperatur."],"correct":0,"why":"Die Farbwahrnehmung wird als Zusammenarbeit zwischen Augen und Gehirn beschrieben.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q03","lesson":"b4l6","prompt":"Welche Impulse empfängt und verarbeitet das Gehirn laut Unterlage?","options":["Licht- und Helligkeitsimpulse.","Nur Temperaturimpulse.","Nur Pigmentimpulse.","Nur Flächengrößenimpulse."],"correct":0,"why":"Die Übersicht nennt Licht- und Helligkeitsimpulse.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q04","lesson":"b4l6","prompt":"Wie beschreibt die Unterlage den Ablauf unseres Sehens über die Zeit?","options":["Jeder Moment wird ununterbrochen neu verarbeitet und interpretiert.","Ein Farbeindruck wird einmal erzeugt und danach nie neu bewertet.","Nur bei Dunkelheit wird neu interpretiert.","Das Gehirn verarbeitet ausschließlich feste Farbcodes."],"correct":0,"why":"Die Unterlage betont die fortlaufende neue Verarbeitung und Interpretation.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q05","lesson":"b4l6","prompt":"Das bekannte Kleid wird von manchen blau/schwarz und von anderen weiß/gold wahrgenommen. Wofür nutzt die Unterlage dieses Beispiel?","options":["Dafür, wie stark Auge und Gehirn gemeinsam Farbwahrnehmung bestimmen.","Als Beweis für subtraktive Druckfarben.","Als Beispiel für einen Quantitäts-Kontrast.","Als Messverfahren für Kelvinwerte."],"correct":0,"why":"Das Kleid-Beispiel soll die Zusammenarbeit von Auge und Gehirn bei der Farbwahrnehmung verdeutlichen.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l6-q06","lesson":"b4l6","prompt":"Welche Aussage passt zur Unterrichtsaussage „Farbe ist nicht einfach da“?","options":["Farbwahrnehmung entsteht durch Verarbeitung und Interpretation von Sehinformationen.","Farbe hängt laut Unterlage ausschließlich von der Flächengröße ab.","Farbe entsteht unabhängig von Auge und Gehirn.","Farbe ist nur die Temperatur eines Gegenstands."],"correct":0,"why":"Die Übersicht beschreibt Farbe als Ergebnis des Sehens und der Verarbeitung durch Auge und Gehirn.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b4-l7-q01","lesson":"b4l7","prompt":"Was ist die Farbtemperatur laut Unterlage „Licht - Farbtemperatur“?","options":["Ein Maß, um den Farbeindruck einer Lichtquelle quantitativ zu bestimmen.","Ein Maß für die Flächengröße einer Farbe.","Ein Maß für die Pigmentmenge einer Beschichtung.","Ein Maß für die Rauheit einer Oberfläche."],"correct":0,"why":"So definiert die Unterrichtsunterlage die Farbtemperatur.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l7-q02","lesson":"b4l7","prompt":"In welcher Einheit wird die Farbtemperatur angegeben?","options":["Kelvin (K).","Nanometer (nm).","Pascal (Pa).","Prozent (%)."],"correct":0,"why":"Die Einheit der Farbtemperatur ist Kelvin.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l7-q03","lesson":"b4l7","prompt":"Worüber wird die Farbtemperatur in der Unterlage definiert?","options":["Über die Temperatur eines Schwarzen Körpers bzw. Planckschen Strahlers.","Über den Hellbezugswert einer Fassade.","Über die Größe einer Farbfläche.","Über die Zahl der Zapfen auf der Netzhaut."],"correct":0,"why":"Die Definition bezieht sich auf einen Schwarzen Körper bzw. Planckschen Strahler.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l7-q04","lesson":"b4l7","prompt":"Welche praktische Vergleichsbedingung nennt die Unterlage bei der Farbtemperatur?","options":["Die Lichtwirkung soll bei gleicher Helligkeit und festgelegten Beobachtungsbedingungen der beschriebenen Farbe möglichst ähnlich sein.","Die Flächengröße muss immer gleich sein.","Die Pigmentmenge muss auf null reduziert werden.","Die Beobachtung muss ausschließlich bei völliger Dunkelheit erfolgen."],"correct":0,"why":"Die Unterlage beschreibt den praktischen Vergleich ausdrücklich bei gleicher Helligkeit und festgelegten Beobachtungsbedingungen.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l7-q05","lesson":"b4l7","prompt":"Du sollst den Farbeindruck einer Lichtquelle zahlenmäßig beschreiben. Welche Größe nennt die Dino-Unterlage dafür?","options":["Die Farbtemperatur.","Den Quantitäts-Kontrast.","Die Transmission.","Die Sättigung einer Körperfarbe."],"correct":0,"why":"Die Farbtemperatur dient der quantitativen Bestimmung des Farbeindrucks einer Lichtquelle.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l7-q06","lesson":"b4l7","prompt":"Ein Wert ist mit „4000 K“ angegeben. Welche Größe wird damit in diesem Themenblock beschrieben?","options":["Die Farbtemperatur einer Lichtquelle.","Die sichtbare Wellenlänge.","Die Helligkeit in Prozent.","Die Anzahl der Rezeptoren."],"correct":0,"why":"Kelvin ist die Einheit der Farbtemperatur.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q01","lesson":"b4l8","prompt":"Welche Lichtfarbe empfiehlt die Unterlage prinzipiell für tagsüber?","options":["Neutralweißes Licht.","Warmweißes Licht ausschließlich.","Nur Kerzenlicht.","Ausschließlich Licht mit 1500 K."],"correct":0,"why":"Für tagsüber wird prinzipiell neutralweißes Licht empfohlen.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q02","lesson":"b4l8","prompt":"Welche Lichtfarbe nennt die Unterlage für die Abendstunden als bewährt für eine Wohlfühlatmosphäre?","options":["Warmweißes Licht.","Neutralweißes Licht zwingend.","Nur bedecktes Himmelslicht.","Ausschließlich 15.000–27.000 K."],"correct":0,"why":"Für die Abendstunden wird warmweißes Licht als Beispiel für eine Wohlfühlatmosphäre genannt.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q03","lesson":"b4l8","prompt":"Welchen Bereich nennt die Unterlage an dunklen Tagen als generell empfehlenswerte Lichtfarbe?","options":["6000 bis 8000 Kelvin.","1500 bis 2000 Kelvin.","2600 bis 2800 Kelvin.","15.000 bis 27.000 Kelvin."],"correct":0,"why":"Im Abschnitt zur angenehmen Farbtemperatur werden für dunkle Tage 6000–8000 K genannt.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q04","lesson":"b4l8","prompt":"Welche Zuordnung stammt aus der Tabelle „Charakteristische Farbtemperaturen“?","options":["Kerze – 1500 K.","Kerze – 7500 K.","Kerze – 15.000 K.","Kerze – 4000 K."],"correct":0,"why":"Die Tabelle ordnet einer Kerze 1500 K zu.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q05","lesson":"b4l8","prompt":"Du suchst in der Tabelle die Leuchtstofflampe „Neutralweiß“. Welcher Wert ist angegeben?","options":["4000 K.","1500 K.","5500 K.","6500–7500 K."],"correct":0,"why":"Für die Leuchtstofflampe (Neutralweiß) nennt die Tabelle 4000 K.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b4-l8-q06","lesson":"b4l8","prompt":"Ein Lichtwert von 7000 K soll der Tabelle zugeordnet werden. Welcher Eintrag passt dazu?","options":["Bedeckter Himmel (6500–7500 K).","Kerze (1500 K).","Glühlampe 40 W (2600 K).","Spätabendsonne kurz vor Dämmerungsbeginn (3400 K)."],"correct":0,"why":"7000 K liegt im Tabellenbereich 6500–7500 K für bedeckten Himmel.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b5-l1-q01","lesson":"b5l1","prompt":"Welche drei Bezugsgößen nennt der Lösungsbogen für eine exakte Farbtonbestimmung?","options":["Farbton, Helligkeit und Sättigung.","Farbtemperatur, Glanz und Schichtdicke.","Absorption, Reflexion und Transmission.","Rot, Grün und Blau."],"correct":0,"why":"Aufgabe 17 nennt ausdrücklich Farbton, Helligkeit und Sättigung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l1-q02","lesson":"b5l1","prompt":"Welche Bezuggröße beantwortet im Unterrichtsbeispiel die Frage, ob ein Grün hell oder dunkel ist?","options":["Die Helligkeit.","Die Sättigung.","Der Farbton.","Die Transmission."],"correct":0,"why":"Helligkeit wird mit „helles oder dunkles Grün“ erläutert.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l1-q03","lesson":"b5l1","prompt":"Welche Bezuggröße beschreibt im Beispiel, ob ein Grün schwach oder stark getönt ist?","options":["Die Sättigung.","Die Helligkeit.","Der Farbton.","Die Reflexion."],"correct":0,"why":"Sättigung wird mit „schwach oder stark getöntes Grün“ erklärt.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l1-q04","lesson":"b5l1","prompt":"Welche Bezuggröße liefert beim Beispiel schlicht die Angabe „Grün“?","options":["Der Farbton.","Die Helligkeit.","Die Sättigung.","Die Farbtemperatur."],"correct":0,"why":"Der Lösungsbogen ordnet „Grün“ dem Farbton zu.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l1-q05","lesson":"b5l1","prompt":"Ein Farbton soll exakt beschrieben werden. Angegeben sind „Grün“ und „dunkel“, aber nicht wie stark getönt er ist. Welche Bezuggröße fehlt?","options":["Die Sättigung.","Der Farbton.","Die Helligkeit.","Die Transmission."],"correct":0,"why":"Für die exakte Bestimmung nennt die Quelle alle drei Größen; hier fehlt die Sättigung.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l1-q06","lesson":"b5l1","prompt":"Welche Beschreibung enthält alle drei im Lösungsbogen geforderten Bezugsgößen?","options":["Grün, dunkel und stark getönt.","Grün und matt.","4000 K und Grün.","Reflektierend und dunkel."],"correct":0,"why":"„Grün“ liefert den Farbton, „dunkel“ die Helligkeit und „stark getönt“ die Sättigung.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q01","lesson":"b5l2","prompt":"Wofür steht die Abkürzung CIE in der Unterrichtsunterlage?","options":["Commission internationale de l’éclairage / Internationale Beleuchtungskommission.","Colour Index Europe.","Central Institute of Enamels.","Chromatic Interior Evaluation."],"correct":0,"why":"Der Lösungsbogen nennt die Internationale Beleuchtungskommission und die französische Bezeichnung.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q02","lesson":"b5l2","prompt":"Was erfasst das CIE-Normvalenzsystem laut Lösungsbogen?","options":["Die Gesamtheit wahrnehmbarer Farben.","Nur RAL-Classic-Farben.","Nur Sicherheitsfarben.","Nur Schwarz- und Weißtöne."],"correct":0,"why":"Aufgabe 16 sagt ausdrücklich, dass es die Gesamtheit wahrnehmbarer Farben erfasst.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q03","lesson":"b5l2","prompt":"Welche zwei Seiten setzt das CIE-Normvalenzsystem in Beziehung?","options":["Menschliche Farbwahrnehmung und physikalische Ursachen des Farbreizes.","RAL-Nummer und Herstellername.","Farbtemperatur und Schichtdicke.","Glanzgrad und Trocknungszeit."],"correct":0,"why":"Der Lösungsbogen beschreibt genau diese Relation.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q04","lesson":"b5l2","prompt":"Wie wird das CIE-Normvalenzsystem in Aufgabe 16 außerdem bezeichnet?","options":["CIE-Normfarbsystem.","RAL-Classic-System.","NCS-Sicherheitscode.","CMYK-Normdrucksystem."],"correct":0,"why":"Die Quelle nennt „CIE-Normvalenzsystem oder CIE-Normfarbsystem“.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q05","lesson":"b5l2","prompt":"Du suchst ein System, das Wahrnehmung und physikalischen Farbreiz zueinander in Beziehung setzt. Welches nennt der Lösungsbogen?","options":["Das CIE-Normvalenzsystem.","RAL Classic.","Die additive Farbmischung.","Den Quantitäts-Kontrast."],"correct":0,"why":"Genau dafür wird das CIE-Normvalenzsystem beschrieben.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l2-q06","lesson":"b5l2","prompt":"Welche Aussage passt zur Rolle des CIE-Systems in der Unterlage?","options":["Es schafft eine Relation zwischen dem gesehenen Farbeindruck und den physikalischen Ursachen des Farbreizes.","Es ordnet nur Gefahrenzeichen nach vier RAL-Nummern.","Es ist ausschließlich eine Sammlung von 1625 RAL-Farben.","Es beschreibt nur die Mischung von Druckerpigmenten."],"correct":0,"why":"Das ist der Kern der Definition in Aufgabe 16.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q01","lesson":"b5l3","prompt":"Welche drei Farbordnungssysteme werden im Lösungsbogen ausdrücklich genannt?","options":["RAL Classic, RAL Design und NCS.","RGB, CMYK und TSR.","BFS 25, BFS 26 und CIE-Lichtart.","HBW, TSR und NCS."],"correct":0,"why":"Aufgabe 18a nennt RAL Classic, RAL Design und NCS.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q02","lesson":"b5l3","prompt":"Wofür steht NCS?","options":["Natural Colour System.","National Coating Standard.","Neutral Colour Scale.","Natural Contrast Scheme."],"correct":0,"why":"Aufgabe 19 nennt ausdrücklich „NCS – Natural Colour System“.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q03","lesson":"b5l3","prompt":"Welches der genannten Systeme wird als branchenübergreifend und weltweit für Farbkommunikation genutzt beschrieben?","options":["NCS.","Nur RAL Classic.","Das RGB-System.","Der Hellbezugswert."],"correct":0,"why":"Diese Beschreibung gehört in Aufgabe 19 zum NCS.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q04","lesson":"b5l3","prompt":"Welche beiden Systeme tragen im Lösungsbogen den gemeinsamen Namen RAL?","options":["RAL Classic und RAL Design.","NCS und CIE.","RGB und CMYK.","RAL Classic und NCS."],"correct":0,"why":"Aufgabe 18 nennt RAL Classic und RAL Design als zwei RAL-Systeme.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q05","lesson":"b5l3","prompt":"Ein Designer und ein Hersteller benötigen laut NCS-Beschreibung eine gemeinsame Farbbezeichnung. Welches System wird dafür ausdrücklich als Farbkommunikationssystem beschrieben?","options":["NCS.","TSR.","HBW.","Additive Farbmischung."],"correct":0,"why":"Der Lösungsbogen nennt die Farbkommunikation zwischen Designern und Herstellern ausdrücklich beim NCS.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l3-q06","lesson":"b5l3","prompt":"Welche Antwort besteht ausschließlich aus in Aufgabe 18 genannten Farbordnungssystemen?","options":["RAL Classic – RAL Design – NCS.","RAL Classic – RGB – HBW.","NCS – TSR – CMYK.","RAL Design – Kelvin – CIE-Lichtart."],"correct":0,"why":"Nur diese drei werden dort als Farbordnungssysteme genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q01","lesson":"b5l4","prompt":"Welche Farbfamilie gehört laut RAL-Classic-Farbordnung zur 1000er-Gruppe?","options":["Gelb.","Orange.","Blau.","Braun."],"correct":0,"why":"Der Lösungsbogen ordnet 1000 = Gelb zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q02","lesson":"b5l4","prompt":"Welche Farbfamilie gehört zur 5000er-Gruppe?","options":["Blau.","Grün.","Rot.","Grau."],"correct":0,"why":"Der Lösungsbogen ordnet 5000 = Blau zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q03","lesson":"b5l4","prompt":"Welche RAL-Classic-Zuordnung ist für die 3000er-Gruppe richtig?","options":["3000 = Rot.","3000 = Grün.","3000 = Braun.","3000 = Weiß/Schwarz."],"correct":0,"why":"In der RAL-Classic-Liste steht 3000 für Rot.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q04","lesson":"b5l4","prompt":"Welche RAL-Classic-Zuordnung ist für die 7000er-Gruppe richtig?","options":["7000 = Grau.","7000 = Gelb.","7000 = Violett.","7000 = Blau."],"correct":0,"why":"In der RAL-Classic-Liste steht 7000 für Grau.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q05","lesson":"b5l4","prompt":"Ein RAL-Classic-Farbton liegt in der 8000er-Gruppe. Welcher Farbfamilie ordnet ihn die Unterrichtsliste zu?","options":["Braun.","Orange.","Grün.","Weiß/Schwarz."],"correct":0,"why":"8000 ist im Lösungsbogen der Farbfamilie Braun zugeordnet.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l4-q06","lesson":"b5l4","prompt":"Welche Reihenfolge entspricht der Unterrichtsliste für 4000, 5000 und 6000?","options":["Violett – Blau – Grün.","Blau – Grün – Grau.","Rot – Violett – Blau.","Orange – Rot – Violett."],"correct":0,"why":"Die Liste nennt 4000 Violett, 5000 Blau, 6000 Grün.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q01","lesson":"b5l5","prompt":"In welchem Jahr wurde RAL Design laut Lösungsbogen eingeführt?","options":["1993.","1976.","2003.","1965."],"correct":0,"why":"Aufgabe 18b nennt 1993 als Einführungsjahr.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q02","lesson":"b5l5","prompt":"Wie viele genormte Farben umfasst RAL Design laut Lösungsbogen?","options":["1625.","899.","520.","740."],"correct":0,"why":"Die Quelle nennt 1625 genormte Farben.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q03","lesson":"b5l5","prompt":"Mit welchen Koordinaten werden die RAL-Design-Farben laut Unterlage beschrieben?","options":["Mit Koordinaten im CIELab-Farbenraum.","Nur mit RAL-Classic-Tausendergruppen.","Nur mit Kelvinwerten.","Mit HBW und TSR."],"correct":0,"why":"Der Lösungsbogen nennt ausdrücklich Koordinaten im CIELab-Farbenraum.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q04","lesson":"b5l5","prompt":"Nach welchen drei Größen ist RAL Design systematisch geordnet?","options":["Buntton (H), Helligkeit (L) und Buntheit (C).","Rot, Grün und Blau.","Schwarzanteil, Weißanteil und TSR.","Absorption, Reflexion und Transmission."],"correct":0,"why":"Die Quelle nennt H/Hue, L/Lightness und C/Chroma.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q05","lesson":"b5l5","prompt":"Du möchtest in RAL Design die Ordnungskriterien nennen. Welche Kurzfolge passt?","options":["H – L – C.","R – G – B.","C – M – Y.","H – B – W."],"correct":0,"why":"RAL Design wird nach Hue, Lightness und Chroma geordnet.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l5-q06","lesson":"b5l5","prompt":"Welche Aussage beschreibt RAL Design nach der Dino-Unterlage korrekt?","options":["Es folgt dem Lab-Farbmaßsystem und ordnet Farben systematisch nach H, L und C.","Es ordnet ausschließlich vier Signalfarben.","Es besteht nur aus neun Tausendergruppen ohne weitere Systematik.","Es ist die additive Mischung von Rot, Grün und Blau."],"correct":0,"why":"So beschreibt Aufgabe 18b den Aufbau von RAL Design.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q01","lesson":"b5l6","prompt":"Was stellt der Lösungsbogen RAL Design ausdrücklich gegenüber?","options":["Der Farbsammlung RAL Classic.","Dem NCS-Code G40Y.","Dem TSR-Wert.","Der Netzhaut."],"correct":0,"why":"Aufgabe 18b sagt „Im Gegensatz zur Farbsammlung RAL Classic …“.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q02","lesson":"b5l6","prompt":"Welche Systematik gehört zu RAL Design und nicht zur in Aufgabe 18c gezeigten RAL-Classic-Farbordnung?","options":["Buntton, Helligkeit und Buntheit (H, L, C).","1000 Gelb, 2000 Orange usw.","Signalgelb RAL 1003.","Signalgrün RAL 6032."],"correct":0,"why":"H, L und C werden ausdrücklich für RAL Design genannt.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q03","lesson":"b5l6","prompt":"Worin zeigt sich laut Lösungsbogen der Unterschied zwischen RAL Classic und RAL Design?","options":["RAL Design ist systematisch nach H, L und C geordnet; RAL Classic wird als Farbsammlung mit Nummerngruppen dargestellt.","RAL Classic basiert auf Kelvin, RAL Design auf Nanometern.","RAL Design enthält nur Signalfarben, RAL Classic nur NCS-Codes.","Beide werden als identisch aufgebaut beschrieben."],"correct":0,"why":"Das ist die Gegenüberstellung aus Aufgabe 18b/c.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q04","lesson":"b5l6","prompt":"Welche Aussage gehört zur RAL-Classic-Farbordnung aus der Unterlage?","options":["9000 = Weiß/Schwarz.","H = Buntton, L = Helligkeit, C = Buntheit als einzige Nummernfolge.","1625 Farben werden nur durch G40Y beschrieben.","30 % Schwarz und 40 % Bunt sind RAL-Classic-Gruppen."],"correct":0,"why":"Die 9000er-Gruppe ist in der RAL-Classic-Liste Weiß/Schwarz.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q05","lesson":"b5l6","prompt":"Du siehst eine systematische Beschreibung nach Hue, Lightness und Chroma. Welches RAL-System passt laut Unterrichtsunterlage?","options":["RAL Design.","RAL Classic.","NCS S 3040-G40Y als RAL-System.","Signalrot RAL 3001 als eigenes System."],"correct":0,"why":"H, L und C sind die Ordnungskriterien von RAL Design.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l6-q06","lesson":"b5l6","prompt":"Du lernst die Folge 1000 Gelb, 2000 Orange, 3000 Rot. Zu welchem System gehört diese Ordnung im Lösungsbogen?","options":["RAL Classic.","RAL Design.","NCS.","CIE-Normvalenzsystem."],"correct":0,"why":"Diese Nummernfolge steht unter „Farbordnung nach RAL Classic“.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q01","lesson":"b5l7","prompt":"Wie lautet der im Lösungsbogen verwendete NCS-Beispielcode?","options":["NCS S 3040-G40Y.","RAL 3040-G40Y.","NCS S 1003-RAL.","CIE S 3040-K40."],"correct":0,"why":"Aufgabe 20 verwendet genau NCS S 3040-G40Y.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q02","lesson":"b5l7","prompt":"Welcher Schwarzanteil wird für NCS S 3040-G40Y angegeben?","options":["30 %.","40 %.","70 %.","10 %."],"correct":0,"why":"Der Lösungsbogen entschlüsselt den Code mit 30 % Schwarzanteil.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q03","lesson":"b5l7","prompt":"Welcher Buntanteil wird für NCS S 3040-G40Y angegeben?","options":["40 %.","30 %.","60 %.","100 %."],"correct":0,"why":"Der Lösungsbogen nennt 40 % Buntanteil.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q04","lesson":"b5l7","prompt":"Wie wird G40Y im Beispielcode erklärt?","options":["Grün mit 40 % Gelbanteil.","Gelb mit 40 % Grünanteil.","Grau mit 40 % Weißanteil.","Grün mit 40 % Schwarzanteil."],"correct":0,"why":"Aufgabe 20 gibt „G40Y → Grün mit 40 % Gelbanteil“ an.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q05","lesson":"b5l7","prompt":"Welche vollständige Dechiffrierung entspricht der Quelle für NCS S 3040-G40Y?","options":["30 % Schwarzanteil, 40 % Buntanteil, Grün mit 40 % Gelbanteil.","40 % Schwarzanteil, 30 % Buntanteil, Gelb mit 40 % Grünanteil.","30 % Helligkeit, 40 K Farbtemperatur, Grün ohne Gelb.","3040 % Schwarzanteil, kein Buntanteil, reines Gelb."],"correct":0,"why":"Genau diese drei Angaben stehen im Lösungsbogen.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l7-q06","lesson":"b5l7","prompt":"Welche Aussage zum NCS übernimmt der Trainer bewusst NICHT als zusätzliche Rechenregel aus dieser Aufgabe?","options":["Einen nicht angegebenen Weißanteil selbst auszurechnen.","Den angegebenen Schwarzanteil von 30 % zu nennen.","Den angegebenen Buntanteil von 40 % zu nennen.","G40Y als Grün mit 40 % Gelbanteil zu lesen."],"correct":0,"why":"Die Quelle gibt bei Aufgabe 20 nur Schwarzanteil, Buntanteil und G40Y-Deutung an; der Trainer ergänzt keine weitere Regel.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q01","lesson":"b5l8","prompt":"Welche RAL-Nummer nennt die Unterlage für Signalgelb?","options":["RAL 1003.","RAL 3001.","RAL 5005.","RAL 6032."],"correct":0,"why":"Aufgabe 21 ordnet Signalgelb RAL 1003 zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q02","lesson":"b5l8","prompt":"Welche RAL-Nummer nennt die Unterlage für Signalgrün?","options":["RAL 6032.","RAL 1003.","RAL 3001.","RAL 5005."],"correct":0,"why":"Aufgabe 21 ordnet Signalgrün RAL 6032 zu.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q03","lesson":"b5l8","prompt":"Welche Bedeutung gehört laut Lösungsbogen zu Signalrot RAL 3001?","options":["Halt! Verbot!","Achtung Gefahr.","Gebote und Hinweise.","Sicherheit, Hilfe."],"correct":0,"why":"Signalrot RAL 3001 wird mit „Halt! Verbot!“ verbunden.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q04","lesson":"b5l8","prompt":"Welche Bedeutung gehört zu Signalblau RAL 5005?","options":["Gebote und Hinweise.","Halt! Verbot!","Achtung Gefahr.","Sicherheit, Hilfe."],"correct":0,"why":"Signalblau RAL 5005 steht in der Quelle für Gebote und Hinweise.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q05","lesson":"b5l8","prompt":"Eine Kennzeichnung soll laut Unterrichtsbeispiel auf die Verpflichtung zum Tragen der PSA hinweisen. Welche Signalfarbe wird genannt?","options":["Signalblau, RAL 5005.","Signalgelb, RAL 1003.","Signalrot, RAL 3001.","Signalgrün, RAL 6032."],"correct":0,"why":"Die Verpflichtung zum Tragen der PSA ist das Beispiel zu Signalblau RAL 5005.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b5-l8-q06","lesson":"b5l8","prompt":"Für Rettungswege, Notausgänge und medizinische Hilfseinrichtungen nennt die Unterlage welche Kennzeichnung?","options":["Signalgrün, RAL 6032 – Sicherheit, Hilfe.","Signalrot, RAL 3001 – Halt, Verbot.","Signalgelb, RAL 1003 – Achtung Gefahr.","Signalblau, RAL 5005 – Gebote und Hinweise."],"correct":0,"why":"Diese Beispiele sind in Aufgabe 21 Signalgrün RAL 6032 zugeordnet.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q01","lesson":"b6l1","prompt":"Was versteht der Farbenlehre-Lösungsbogen unter „Metamerie“?","options":["Zwei Farben sehen bei einer Lichtart gleich aus und zeigen bei mindestens einer anderen Lichtquelle einen Farbtonunterschied.","Zwei Farben sehen unter jeder Lichtquelle immer unterschiedlich aus.","Eine Farbe wird durch Pigmentmischung grundsätzlich heller.","Zwei Lichtquellen haben immer dieselbe spektrale Verteilung."],"correct":0,"why":"Genau so beschreibt Aufgabe 22 die Metamerie.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q02","lesson":"b6l1","prompt":"Welches Merkmal gehört zwingend zur Metamerie-Definition der Unterlage?","options":["Die Beurteilung verändert sich beim Wechsel der Lichtquelle.","Die Oberfläche muss hochglänzend sein.","Die Farben müssen RAL-Nummern besitzen.","Der Farbton muss ausschließlich im Tageslicht abweichen."],"correct":0,"why":"Der Lichtwechsel ist der Kern der Definition: zunächst gleich, bei einer anderen Lichtquelle verschieden.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q03","lesson":"b6l1","prompt":"Zwei Farben wirken unter Lichtquelle A gleich, unter Lichtquelle B aber verschieden. Wie nennt der Lösungsbogen diese Eigenschaft?","options":["Metamerie.","Transmission.","Quantitätskontrast.","Sättigung."],"correct":0,"why":"Das Beispiel erfüllt exakt die Definition von Metamerie.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q04","lesson":"b6l1","prompt":"Welche Beobachtung passt NICHT zur Definition von Metamerie?","options":["Zwei Farben sind unter jeder betrachteten Lichtquelle gleich.","Unter einer Lichtart wirken zwei Farben gleich.","Nach einem Lichtwechsel wird ein Farbtonunterschied sichtbar.","Die Übereinstimmung der Farben hängt von der Lichtquelle ab."],"correct":0,"why":"Wenn die Farben unter allen betrachteten Lichtquellen gleich bleiben, tritt der definierende Lichtwechsel-Effekt nicht auf.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q05","lesson":"b6l1","prompt":"Ein Muster und eine Fläche stimmen unter Beleuchtung A überein. Unter Beleuchtung B ist ein Farbtonunterschied sichtbar. Welche Einordnung folgt direkt aus der Dino-Definition?","options":["Das ist ein metamerer Fall.","Das ist automatisch ein Hell-Dunkel-Kontrast.","Das beweist ausschließlich eine matte Oberfläche.","Das ist per Definition additive Farbmischung."],"correct":0,"why":"Die Farben sind unter einer Lichtart gleich und unter einer anderen verschieden.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l1-q06","lesson":"b6l1","prompt":"Zwei Farbtöne unterscheiden sich bereits unter der ersten und auch unter der zweiten Lichtquelle. Was kann man daraus nach der gegebenen Definition NICHT sicher ableiten?","options":["Dass genau der definierte Metamerie-Fall vorliegt.","Dass ein Farbtonunterschied beobachtet wird.","Dass beide Lichtquellen zur Betrachtung genutzt wurden.","Dass die Farben nicht bei der ersten Lichtart gleich aussehen."],"correct":0,"why":"Für Metamerie verlangt die Quelle zunächst Gleichheit bei einer Lichtart.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q01","lesson":"b6l2","prompt":"Welche zwei Lichtarten nennt Aufgabe 22 ausdrücklich als Beispiele im Zusammenhang mit Metamerie?","options":["Tageslicht und Kunstlicht.","UV-Licht und Infrarotlicht.","Rotlicht und Blaulicht.","Laserlicht und Röntgenlicht."],"correct":0,"why":"In Klammern nennt der Lösungsbogen Tageslicht und Kunstlicht.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q02","lesson":"b6l2","prompt":"Warum werden im Metamerie-Beispiel unterschiedliche Lichtarten betrachtet?","options":["Weil sich ein Farbtonunterschied erst bei einer anderen Lichtquelle zeigen kann.","Weil nur Kunstlicht Farben sichtbar macht.","Weil Tageslicht keine elektromagnetische Strahlung ist.","Weil die Oberfläche dadurch automatisch glänzend wird."],"correct":0,"why":"Die Definition beruht darauf, dass die beiden Farben je nach Lichtquelle gleich oder verschieden wirken.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q03","lesson":"b6l2","prompt":"Welche Aussage beschreibt die Rolle der Lichtquelle bei Metamerie richtig?","options":["Sie kann entscheiden, ob zwei Farben gleich oder unterschiedlich erscheinen.","Sie ändert immer die RAL-Nummer einer Farbe.","Sie macht aus Körperfarben additive Lichtfarben.","Sie bestimmt allein die Oberflächenstruktur."],"correct":0,"why":"Nach Aufgabe 22 hängt die sichtbare Übereinstimmung der beiden Farben von der Lichtquelle ab.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q04","lesson":"b6l2","prompt":"Warum reicht die Betrachtung unter nur einer Lichtart nicht aus, um den beschriebenen Metamerie-Effekt sichtbar zu machen?","options":["Weil die Abweichung laut Definition erst unter mindestens einer anderen Lichtquelle auftreten kann.","Weil Farben unter einer Lichtart grundsätzlich unsichtbar sind.","Weil Metamerie ausschließlich bei Dunkelheit vorkommt.","Weil dafür zwingend ein Prisma benötigt wird."],"correct":0,"why":"Die Definition enthält ausdrücklich den Vergleich mit mindestens einer anderen Lichtquelle.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q05","lesson":"b6l2","prompt":"Zwei Beschichtungen sehen bei Tageslicht gleich aus. Was wäre nach Aufgabe 22 der passende nächste Vergleich, um einen Metamerie-Effekt zu erkennen?","options":["Sie zusätzlich unter einer anderen Lichtquelle, zum Beispiel Kunstlicht, betrachten.","Nur die Schichtdicke messen.","Die RAL-Nummern addieren.","Die Oberflächen mit Wasser benetzen."],"correct":0,"why":"Tageslicht und Kunstlicht werden als Beispiele für den notwendigen Lichtwechsel genannt.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l2-q06","lesson":"b6l2","prompt":"Bei Tageslicht besteht ein Unterschied, bei Kunstlicht sehen zwei Farben gleich aus. Passt auch diese Beobachtung grundsätzlich zum in Aufgabe 22 beschriebenen lichtabhängigen Verhalten?","options":["Ja, weil Gleichheit bei einer Lichtart und Unterschied bei einer anderen vorliegen.","Nein, weil nur Tageslicht Gleichheit zeigen darf.","Nein, weil Kunstlicht in der Definition ausgeschlossen ist.","Nein, weil Metamerie nur mit drei Lichtquellen möglich ist."],"correct":0,"why":"Die Definition legt nicht fest, welche der Lichtarten die Gleichheit zeigt; entscheidend ist die Abhängigkeit vom Lichtwechsel.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l3-q01","lesson":"b6l3","prompt":"Was kann laut Farbtemperatur-Unterlage bei Lichtquellen gleicher Farbtemperatur trotzdem sehr unterschiedlich sein?","options":["Die spektrale Verteilung des Lichts.","Die Einheit Kelvin.","Die Definition des Schwarzen Körpers.","Der Name der Farbe Weiß."],"correct":0,"why":"Die Unterlage sagt ausdrücklich, dass die spektrale Verteilung bei gleicher Farbtemperatur sehr unterschiedlich sein kann.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l3-q02","lesson":"b6l3","prompt":"Wie nennt die Licht-Unterlage Lichtquellen gleicher Farbtemperatur mit unterschiedlicher spektraler Verteilung?","options":["Metamere Lichtquellen.","Komplementäre Pigmente.","Subtraktive Lichtquellen.","Unbunte Farbkörper."],"correct":0,"why":"Dafür verwendet die Unterlage den Begriff „metamere Lichtquellen“.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l3-q03","lesson":"b6l3","prompt":"Welche Aussage folgt aus der Beschreibung metamerer Lichtquellen?","options":["Gleiche Farbtemperatur bedeutet nicht automatisch gleiche spektrale Verteilung.","Gleiche Farbtemperatur bedeutet immer identisches Spektrum.","Unterschiedliche Spektren können niemals dieselbe Farbtemperatur haben.","Farbtemperatur beschreibt ausschließlich die Oberflächenrauigkeit."],"correct":0,"why":"Genau diese Unterscheidung macht die Unterlage.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l3-q04","lesson":"b6l3","prompt":"Was unterscheidet „Metamerie von Farben“ und „metamere Lichtquellen“ in den vorliegenden Unterlagen?","options":["Bei Farben geht es um lichtabhängige Farbgleichheit; bei Lichtquellen um gleiche Farbtemperatur trotz unterschiedlicher Spektren.","Beide Begriffe bezeichnen exakt dasselbe ohne Unterschied.","Metamerie von Farben betrifft nur RAL, metamere Lichtquellen nur NCS.","Metamere Lichtquellen sind matte Oberflächen."],"correct":0,"why":"Die beiden Quellen verwenden den Wortstamm in zwei klar unterschiedlichen Beschreibungen.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l3-q05","lesson":"b6l3","prompt":"Zwei Lampen haben laut Angabe dieselbe Farbtemperatur, ihre spektrale Verteilung ist aber verschieden. Welcher Begriff passt nach der Dino-Unterlage?","options":["Metamere Lichtquellen.","Farbe-an-sich-Kontrast.","Transmission.","RAL-Classic-Farben."],"correct":0,"why":"Das ist genau die Definition, die die Farbtemperatur-Unterlage für metamere Lichtquellen gibt.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l3-q06","lesson":"b6l3","prompt":"Du kennst von zwei Lichtquellen nur denselben Kelvinwert. Welche Aussage wäre nach der Unterlage zu weitgehend?","options":["Daraus folgt sicher, dass beide dieselbe spektrale Verteilung besitzen.","Beide können dieselbe Farbtemperatur besitzen.","Ihre Spektren können trotzdem verschieden sein.","Sie können als metamere Lichtquellen auftreten."],"correct":0,"why":"Die Unterlage warnt gerade davor, aus gleicher Farbtemperatur auf gleiche spektrale Verteilung zu schließen.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q01","lesson":"b6l4","prompt":"Welches Beispiel nennt die Unterlage für metameres Licht mit kontinuierlichem Spektrum?","options":["Glühlampen.","Energiesparlampen.","Flachbildschirme.","Pigmentmischungen."],"correct":0,"why":"Die Unterlage nennt Glühlampen als Beispiel für ein kontinuierliches Spektrum.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q02","lesson":"b6l4","prompt":"Welche Beispiele nennt die Unterlage für Licht, das sich auf einige schmale Spektralbänder beschränken kann?","options":["Energiesparlampen und Flachbildschirme.","Glühlampen und Sonnenlicht.","Prismen und Spiegel.","RAL-Fächer und NCS-Karten."],"correct":0,"why":"Diese beiden Beispiele werden für schmale Spektralbänder genannt.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q03","lesson":"b6l4","prompt":"Was bedeutet „kontinuierliches Spektrum“ im Gegensatz zu den in der Unterlage genannten schmalen Spektralbändern?","options":["Die spektrale Verteilung ist nicht nur auf einige schmale Bänder beschränkt.","Das Licht besitzt keine Farbtemperatur.","Die Lichtquelle reflektiert ausschließlich Grün.","Die Oberfläche ist automatisch hochglänzend."],"correct":0,"why":"Die Quelle stellt kontinuierliches Spektrum und Beschränkung auf einige schmale Spektralbänder gegenüber.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q04","lesson":"b6l4","prompt":"Warum können zwei Lichtquellen trotz gleicher Farbtemperatur spektral verschieden sein?","options":["Weil ihre Strahlung unterschiedlich über das Spektrum verteilt sein kann.","Weil Kelvin die Oberflächenrauigkeit misst.","Weil jede Lichtquelle nur eine einzige Wellenlänge besitzt.","Weil gleiche Farbtemperatur automatisch unterschiedliche Helligkeit bedeutet."],"correct":0,"why":"Die Unterlage trennt Farbtemperatur und spektrale Verteilung ausdrücklich.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q05","lesson":"b6l4","prompt":"Eine Lichtquelle zeigt ein kontinuierliches Spektrum. Welches Beispiel passt nach der Unterlage am ehesten?","options":["Eine Glühlampe.","Eine Energiesparlampe mit einigen schmalen Spektralbändern.","Ein Flachbildschirm mit einigen schmalen Spektralbändern.","Eine RAL-Classic-Farbkarte."],"correct":0,"why":"Die Glühlampe ist das genannte Beispiel für das kontinuierliche Spektrum.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l4-q06","lesson":"b6l4","prompt":"Eine Lichtquelle verteilt ihre Strahlung nur auf einige schmale Spektralbänder. Welches Beispiel nennt die Dino-Unterlage dafür?","options":["Eine Energiesparlampe.","Eine Glühlampe als Beispiel für kontinuierliches Spektrum.","Eine matte Wand als Lichtquelle.","Ein NCS-Farbcode."],"correct":0,"why":"Energiesparlampen werden neben Flachbildschirmen ausdrücklich als Beispiel genannt.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q01","lesson":"b6l5","prompt":"Was gibt der Farbwiedergabeindex laut Licht-Unterlage an?","options":["Die Qualität der Farbwiedergabe bei Beleuchtung mit einer Lichtquelle.","Den Schwarzanteil eines NCS-Codes.","Die Rauigkeit einer Oberfläche.","Die Wellenlänge des gesamten sichtbaren Bereichs."],"correct":0,"why":"So wird der Farbwiedergabeindex in der Unterlage beschrieben.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q02","lesson":"b6l5","prompt":"Worauf bezieht sich der Farbwiedergabeindex in der Dino-Unterlage?","options":["Auf die Beleuchtung mit einer Lichtquelle.","Auf die Dicke einer Lackschicht.","Auf die Nummerngruppe von RAL Classic.","Auf die Größe einer Farbfläche."],"correct":0,"why":"Die Quelle verknüpft den Index direkt mit der Farbwiedergabe bei Beleuchtung durch eine Lichtquelle.","level":"basis","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q03","lesson":"b6l5","prompt":"Welche Frage beantwortet der Farbwiedergabeindex nach der gegebenen Definition am ehesten?","options":["Wie gut eine Lichtquelle Farben wiedergibt.","Wie viel Schwarzanteil eine NCS-Farbe hat.","Wie glänzend eine Oberfläche ist.","Welche Farbe im Farbkreis gegenüberliegt."],"correct":0,"why":"Er beschreibt die Qualität der Farbwiedergabe einer Lichtquelle.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q04","lesson":"b6l5","prompt":"Welche Aussage ist durch die vorliegende Dino-Unterlage NICHT belegt?","options":["Ein bestimmter Zahlenwert des Farbwiedergabeindex ist als Mindestgrenze vorgeschrieben.","Der Farbwiedergabeindex beschreibt die Qualität der Farbwiedergabe.","Die Bewertung bezieht sich auf eine Lichtquelle.","Lichtquellen können unterschiedliche spektrale Verteilungen haben."],"correct":0,"why":"Die Quelle nennt die Bedeutung, aber keine konkrete Skala oder Mindestgrenze.","level":"verstehen","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q05","lesson":"b6l5","prompt":"Du sollst nur mit der Dino-Unterlage erklären, wofür der Farbwiedergabeindex steht. Welche Formulierung ist zulässig?","options":["Er gibt die Qualität der Farbwiedergabe bei Beleuchtung mit einer Lichtquelle an.","Er muss immer mindestens 90 betragen.","Er wird in Prozent des HBW angegeben.","Er entspricht der RAL-Nummer der Lichtquelle."],"correct":0,"why":"Nur die allgemeine Qualitätsaussage ist in der Unterlage ausdrücklich enthalten.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l5-q06","lesson":"b6l5","prompt":"Jemand behauptet: „Aus dem vorliegenden Blatt kenne ich eine verbindliche Mindestzahl für den Farbwiedergabeindex.“ Wie ist das einzuordnen?","options":["Das Blatt liefert dafür keine konkrete Mindestzahl.","Das stimmt; dort steht zwingend 100.","Das stimmt; dort steht zwingend 80.","Das stimmt; dort steht zwingend 50."],"correct":0,"why":"Die Unterlage definiert die Bedeutung des Index, nennt aber keinen Zahlen-Grenzwert.","level":"anwenden","src":"DINO-LICHT-TEMP"},{"id":"f24-b6-l6-q01","lesson":"b6l6","prompt":"Wie wird das einfallende Licht bei einer glänzenden Oberfläche laut Lösungsbogen reflektiert?","options":["Gleichmäßig gerichtet.","Unregelmäßig diffus in mehrere Richtungen.","Vollständig absorbiert.","Vollständig durchgelassen."],"correct":0,"why":"Aufgabe 8 beschreibt glänzende Oberflächen mit gleichmäßig gerichteter Reflexion.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l6-q02","lesson":"b6l6","prompt":"Wie wird das einfallende Licht bei einer matten Oberfläche laut Lösungsbogen reflektiert?","options":["Unregelmäßig diffus in mehrere Richtungen.","Gleichmäßig gerichtet.","Ausschließlich nach innen absorbiert.","Nur durch Transmission weitergeleitet."],"correct":0,"why":"Aufgabe 8 beschreibt matte Oberflächen mit diffuser Reflexion in mehrere Richtungen.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l6-q03","lesson":"b6l6","prompt":"Welche Oberflächenbeschaffenheit ordnet der Lösungsbogen einer glänzenden Wirkung zu?","options":["Eine glatte Oberfläche.","Eine unebene Oberfläche.","Eine vollständig lichtdurchlässige Oberfläche.","Eine Oberfläche ohne Reflexion."],"correct":0,"why":"Glänzend wird mit glatt und gerichtet reflektierend erklärt.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l6-q04","lesson":"b6l6","prompt":"Welche Kombination passt laut Unterrichtsantwort zu einer matten Wirkung?","options":["Uneben + diffuse Reflexion.","Glatt + gerichtete Reflexion.","Glatt + vollständige Transmission.","Uneben + ausschließlich gerichtete Reflexion."],"correct":0,"why":"Matt wird mit unebener Oberfläche und diffuser Reflexion beschrieben.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l6-q05","lesson":"b6l6","prompt":"Eine Oberfläche ist glatt und wirft das Licht gleichmäßig gerichtet zurück. Welche Wirkung erwartet der Lösungsbogen?","options":["Hochglänzend bzw. glänzend.","Matt.","Transparent.","Metamer ohne Lichtwechsel."],"correct":0,"why":"Die Merkmalskombination entspricht der Erklärung für glänzende Oberflächen.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l6-q06","lesson":"b6l6","prompt":"Eine Oberfläche streut das einfallende Licht unregelmäßig in mehrere Richtungen. Welche Einordnung passt?","options":["Matt bzw. diffuse Reflexion.","Glänzend bzw. gerichtete Reflexion.","Additive Farbmischung.","NCS-Farbcode."],"correct":0,"why":"Mehrere unregelmäßige Reflexionsrichtungen kennzeichnen laut Lösungsbogen die matte Oberfläche.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l7-q01","lesson":"b6l7","prompt":"Woraus entsteht Farbwahrnehmung laut „Farben sehen“?","options":["Aus der Zusammenarbeit von Auge und Gehirn.","Nur aus der RAL-Nummer eines Farbtons.","Nur aus der Oberflächenrauigkeit.","Ausschließlich aus der Farbtemperatur ohne Wahrnehmung."],"correct":0,"why":"Die Unterlage bezeichnet Auge und Gehirn ausdrücklich als Team der Farbwahrnehmung.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l7-q02","lesson":"b6l7","prompt":"Was verarbeitet das Gehirn laut Unterlage beim Farbsehen?","options":["Licht- und Helligkeitsimpulse.","Nur RAL- und NCS-Nummern.","Ausschließlich Schichtdickenwerte.","Nur Temperaturwerte des Untergrunds."],"correct":0,"why":"„Farben sehen“ beschreibt, dass das Gehirn Licht- und Helligkeitsimpulse empfängt und verarbeitet.","level":"basis","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l7-q03","lesson":"b6l7","prompt":"Welche Aussage beschreibt die Farbwahrnehmung nach „Farben sehen“ richtig?","options":["Unser Sehen wird fortlaufend verarbeitet und interpretiert.","Farbe wird unabhängig von Auge und Gehirn immer identisch wahrgenommen.","Das Gehirn ist am Farbsehen nicht beteiligt.","Nur die Stäbchen erzeugen alle bunten Farbeindrücke."],"correct":0,"why":"Die Unterlage beschreibt die Wahrnehmung als kontinuierlich neu verarbeitet und interpretiert.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l7-q04","lesson":"b6l7","prompt":"Warum verwendet die Unterlage das unterschiedlich wahrgenommene Kleid als Beispiel?","options":["Um zu zeigen, wie stark Auge und Gehirn gemeinsam die Farbwahrnehmung beeinflussen können.","Um RAL 3001 zu erklären.","Um die subtraktive Primärfarbe Cyan zu beweisen.","Um einen vorgeschriebenen Kelvin-Grenzwert festzulegen."],"correct":0,"why":"Das Kleid wird ausdrücklich als Beispiel für die gemeinsame Farbwahrnehmung von Auge und Gehirn genutzt.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l7-q05","lesson":"b6l7","prompt":"Zwei Personen beschreiben beim gezeigten Kleid unterschiedliche Farben. Welcher Unterrichtspunkt wird damit illustriert?","options":["Farbwahrnehmung ist das Ergebnis der Verarbeitung durch Auge und Gehirn.","Jede Farbe besitzt zwingend zwei RAL-Nummern.","Matte Oberflächen sind immer metamer.","Farbtemperatur wird in Nanometern gemessen."],"correct":0,"why":"Genau dafür dient das Kleid-Beispiel in der Übersicht.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l7-q06","lesson":"b6l7","prompt":"Bei einer Farbbeurteilung sollst du einen Wahrnehmungsfaktor aus den Dino-Unterlagen nennen. Welcher passt?","options":["Auge und Gehirn verarbeiten und interpretieren Licht- und Helligkeitsimpulse.","Der NCS-Code verändert sich beim Hinsehen.","Der RAL-Fächer erzeugt additive Lichtmischung.","Die Farbwahrnehmung findet ohne Gehirn statt."],"correct":0,"why":"Die Quelle beschreibt die Farbwahrnehmung ausdrücklich als Zusammenarbeit und Verarbeitung.","level":"anwenden","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l8-q01","lesson":"b6l8","prompt":"Welche drei Einflussbereiche behandelt Block 6 auf Grundlage der Dino-Unterlagen getrennt?","options":["Lichtquelle, Reflexionsverhalten der Oberfläche und Wahrnehmung durch Auge/Gehirn.","Schichtdicke, Trocknungszeit und Verbrauch.","Bindemittel, Lösemittel und Füllstoff.","Gerüstklasse, Leiterwinkel und PSA."],"correct":0,"why":"Diese drei Bereiche sind durch die Metamerie-, Reflexions- und Wahrnehmungsabschnitte der Unterlagen belegt.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l8-q02","lesson":"b6l8","prompt":"Welcher Faktor ist für die Definition der Metamerie unmittelbar entscheidend?","options":["Der Wechsel der Lichtquelle bzw. Lichtart.","Die RAL-Tausendergruppe.","Die Größe der Farbfläche.","Die Anzahl der Pigmentsorten."],"correct":0,"why":"Metamerie wird über Gleichheit bei einer Lichtart und Unterschied bei einer anderen Lichtquelle definiert.","level":"basis","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l8-q03","lesson":"b6l8","prompt":"Welche Beobachtung beschreibt einen Oberflächeneffekt und nicht die Metamerie-Definition?","options":["Gerichtete Reflexion an einer glatten, glänzenden Oberfläche.","Zwei Farben sind bei einer Lichtart gleich und bei einer anderen verschieden.","Die Übereinstimmung zweier Farben hängt von der Lichtquelle ab.","Nach einem Lichtwechsel wird ein Farbtonunterschied sichtbar."],"correct":0,"why":"Gerichtete Reflexion gehört zur Erklärung von Glanz; Metamerie wird über den Lichtwechsel definiert.","level":"verstehen","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l8-q04","lesson":"b6l8","prompt":"Welche Aussage gehört zur Wahrnehmung und nicht zur spektralen Beschreibung einer Lichtquelle?","options":["Auge und Gehirn verarbeiten und interpretieren die Licht- und Helligkeitsimpulse.","Lichtquellen gleicher Farbtemperatur können unterschiedliche spektrale Verteilungen haben.","Glühlampen können ein kontinuierliches Spektrum aufweisen.","Energiesparlampen können sich auf schmale Spektralbänder beschränken."],"correct":0,"why":"Die erste Aussage stammt aus dem Abschnitt über Auge und Gehirn; die anderen betreffen die spektrale Lichtbeschreibung.","level":"verstehen","src":"DINO-FARBEN-SEHEN"},{"id":"f24-b6-l8-q05","lesson":"b6l8","prompt":"Bei einem Farbvergleich ändert sich die Übereinstimmung erst nach dem Wechsel von Tageslicht zu Kunstlicht. Welcher Faktor erklärt diesen Fall direkt?","options":["Die lichtabhängige Metamerie.","Nur die gerichtete Reflexion einer Hochglanzfläche.","Nur die RAL-Classic-Nummerngruppe.","Nur die Flächengröße des Quantitätskontrasts."],"correct":0,"why":"Der Fall entspricht genau der Metamerie-Definition und den genannten Beispielen Tageslicht/Kunstlicht.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b6-l8-q06","lesson":"b6l8","prompt":"Welche zusätzliche Arbeitsregel darf aus den aktuell verwendeten Dino-Unterlagen für diesen Block NICHT als verbindlich behauptet werden?","options":["Eine konkrete vorgeschriebene Musterflächen- oder Normlicht-Prozedur.","Dass Metamerie vom Wechsel der Lichtquelle abhängen kann.","Dass glänzende Oberflächen Licht gerichtet reflektieren.","Dass Auge und Gehirn gemeinsam an der Farbwahrnehmung beteiligt sind."],"correct":0,"why":"Die vorliegenden Unterlagen belegen die drei anderen Aussagen, enthalten hier aber keine konkrete Musterflächen- oder Normlicht-Prozedur.","level":"anwenden","src":"DINO-FARBE-LSG"},{"id":"f24-b7-l1-q01","lesson":"b7l1","prompt":"Was beschreibt der TSR-Wert laut TSR-Übersicht?","options":["Das solare Reflexionsvermögen einer pigmentierten Oberfläche.","Nur den Glanzgrad einer Lackoberfläche.","Nur den sichtbaren Farbton ohne Energiebezug.","Die Wasserdampfdurchlässigkeit einer Fassade."],"correct":0,"why":"TSR beschreibt den Anteil der Sonnenstrahlungsenergie, der zurückgestrahlt wird.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l1-q02","lesson":"b7l1","prompt":"Wofür steht die Abkürzung TSR in der Dino-Unterlage?","options":["Total Solar Reflectance bzw. Total Solar Reflexion.","Total Surface Resistance.","Thermal Shade Ratio.","Transparent Solar Reaction."],"correct":0,"why":"Die Überschrift nennt „Total Solar Reflexion – TSR Wert“, im Fließtext „Total Solar Reflectance“.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l1-q03","lesson":"b7l1","prompt":"Welche Energiegröße steckt unmittelbar im TSR-Wert?","options":["Der Anteil einfallender Sonnenstrahlungsenergie, der von der Oberfläche zurückgestrahlt wird.","Der Anteil Wasser, der in den Untergrund eindringt.","Die Menge Bindemittel im Beschichtungsstoff.","Die reine Helligkeitswahrnehmung des Auges."],"correct":0,"why":"Die Definition ist ausdrücklich energetisch auf die Sonnenstrahlung bezogen.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l1-q04","lesson":"b7l1","prompt":"Wie verändert sich die solare Reflexion, wenn der TSR-Wert steigt?","options":["Sie nimmt zu.","Sie nimmt zwangsläufig ab.","Sie bleibt definitionsgemäß immer gleich.","Sie wird durch den TSR-Wert nicht beschrieben."],"correct":0,"why":"Ein höherer TSR bedeutet stärkere Reflexion der solaren Strahlung.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l1-q05","lesson":"b7l1","prompt":"Zwei pigmentierte Oberflächen haben TSR 20 % und TSR 45 %. Welche reflektiert nach der Definition den größeren Anteil der Sonnenenergie?","options":["Die Oberfläche mit TSR 45 %.","Die Oberfläche mit TSR 20 %.","Beide immer exakt gleich.","Das lässt sich selbst über den TSR-Wert nicht vergleichen."],"correct":0,"why":"Der höhere TSR-Wert steht für einen größeren zurückgestrahlten Anteil.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l1-q06","lesson":"b7l1","prompt":"Eine Produktinformation nennt einen hohen TSR-Wert. Welche Aussage darf daraus direkt abgeleitet werden?","options":["Die Oberfläche reflektiert einen hohen Anteil der solaren Strahlungsenergie.","Der Farbton ist zwingend weiß.","Der HBW ist automatisch identisch hoch.","Die Oberfläche besitzt zwingend hohen Glanz."],"correct":0,"why":"Der TSR beschreibt die solare Reflexion, nicht automatisch Farbton, HBW oder Glanz.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l2-q01","lesson":"b7l2","prompt":"Wie verhält sich der TSR-Wert laut Unterlage zur Aufheizung?","options":["Er ist umgekehrt proportional zur Aufheizung.","Er ist immer proportional zur Schichtdicke.","Er bestimmt ausschließlich die Trocknungszeit.","Er ist unabhängig von jeder Sonneneinstrahlung."],"correct":0,"why":"Die Unterlage formuliert ausdrücklich einen umgekehrten Zusammenhang zur Aufheizung.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l2-q02","lesson":"b7l2","prompt":"Was bewirkt laut TSR-Unterlage ein höherer Reflexionswert bei Sonneneinstrahlung?","options":["Eine niedrigere Oberflächentemperatur.","Eine höhere Oberflächentemperatur.","Immer stärkere Vergilbung.","Immer eine höhere PVK."],"correct":0,"why":"Mehr zurückgestrahlte Energie bedeutet laut Unterlage weniger thermischen Anstieg.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l2-q03","lesson":"b7l2","prompt":"Warum fällt der Temperaturanstieg bei höherem TSR geringer aus?","options":["Weil ein größerer Anteil der solaren Energie zurückreflektiert wird.","Weil der Untergrund dadurch automatisch dicker wird.","Weil sichtbares Licht vollständig verschwindet.","Weil der Bindemittelanteil auf null sinkt."],"correct":0,"why":"Der Zusammenhang wird über die reflektierte statt aufgenommene solare Energie erklärt.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l2-q04","lesson":"b7l2","prompt":"Welche Aussage trifft den Zusammenhang aus der Unterlage am besten?","options":["Hoher TSR → stärkere solare Reflexion → geringere Aufheizung.","Hoher TSR → stärkere Absorption → höhere Aufheizung.","Niedriger TSR → stärkere Reflexion → geringere Aufheizung.","TSR beschreibt nur den optischen Glanz ohne Temperaturbezug."],"correct":0,"why":"Das ist die in der Übersicht dargestellte Wirkungskette.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l2-q05","lesson":"b7l2","prompt":"Eine dunkle Fassade soll bei Sonne thermisch weniger belastet werden. Welche Eigenschaft wäre nach der TSR-Unterlage günstig?","options":["Ein möglichst hoher bestätigter TSR-Wert.","Ein möglichst niedriger TSR-Wert.","Ein möglichst hoher Wassergehalt.","Ein möglichst niedriger Glanzgrad unabhängig vom TSR."],"correct":0,"why":"Ein höherer TSR führt nach der Quelle zu geringerer Aufheizung.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l2-q06","lesson":"b7l2","prompt":"Bei zwei ansonsten vergleichbaren Beschichtungen ist der TSR von Produkt A höher als der von B. Welche thermische Tendenz nennt die Unterlage?","options":["A hat tendenziell die niedrigere Oberflächentemperatur bei Sonne.","A hat zwingend die höhere Oberflächentemperatur.","B reflektiert zwingend mehr Solarenergie.","Aus einem höheren TSR folgt eine stärkere Aufheizung."],"correct":0,"why":"Die Quelle verknüpft höheren TSR mit geringerer Oberflächentemperatur.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l3-q01","lesson":"b7l3","prompt":"Welchen Spektralbereich bezeichnet die Unterlage mit NIR?","options":["Den nahen Infrarotbereich.","Den sichtbaren Grünbereich.","Den ultravioletten Bereich.","Den Bereich der Schallwellen."],"correct":0,"why":"NIR wird als „Nahes Infrarot“ erläutert.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l3-q02","lesson":"b7l3","prompt":"Welche Pigmenteigenschaft kann bei sehr dunklen Farbtönen niedrigere Oberflächentemperaturen ermöglichen?","options":["Eine möglichst geringe Absorption im NIR-Bereich.","Eine möglichst hohe NIR-Absorption.","Eine möglichst hohe Wasseraufnahme.","Eine möglichst geringe Haftung."],"correct":0,"why":"Die Unterlage nennt gezielt Pigmente mit geringer NIR-Absorption.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l3-q03","lesson":"b7l3","prompt":"Warum kann ein sehr dunkler Farbton trotz seiner sichtbaren Dunkelheit thermisch günstiger ausfallen?","options":["Weil geeignete Pigmente im NIR-Bereich wenig absorbieren können.","Weil dunkle Farbtöne grundsätzlich keine Sonnenenergie aufnehmen.","Weil der HBW automatisch das gesamte Infrarot erfasst.","Weil dunkle Beschichtungen immer transparent sind."],"correct":0,"why":"Die Quelle trennt sichtbare Wirkung und NIR-Verhalten der Pigmente.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l3-q04","lesson":"b7l3","prompt":"Für welchen Systemtyp hebt die Unterlage einen möglichen Vorteil niedrigerer Oberflächentemperaturen besonders hervor?","options":["Für wärmegedämmte Oberflächen.","Nur für unbeschichtetes Glas.","Nur für Innenputz ohne Sonneneinstrahlung.","Nur für Metall im Wasserbad."],"correct":0,"why":"Die Quelle nennt ausdrücklich wärmegedämmte Oberflächen.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l3-q05","lesson":"b7l3","prompt":"Eine dunkle Beschichtung nutzt Pigmente mit geringer NIR-Absorption. Welche Wirkung ist laut Unterlage möglich?","options":["Eine niedrigere Oberflächentemperatur als bei ungünstigerer Pigmentwahl.","Eine zwangsläufig höhere Oberflächentemperatur.","Eine vollständige Vermeidung jeder Alterung.","Eine automatische Erhöhung der Schichtdicke."],"correct":0,"why":"Die Pigmentauswahl kann die Aufheizung dunkler Farbtöne beeinflussen.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l3-q06","lesson":"b7l3","prompt":"Warum kann die Pigmentauswahl bei einem WDVS thermisch relevant sein?","options":["Weil geringe NIR-Absorption die Oberflächentemperatur senken kann und dies die Dauerhaftigkeit möglicherweise begünstigt.","Weil Pigmente die Dämmstoffdicke automatisch vergrößern.","Weil nur sichtbares Licht ein WDVS erwärmt.","Weil NIR bei Sonneneinstrahlung keine Rolle spielt."],"correct":0,"why":"Genau diesen möglichen Vorteil beschreibt die TSR-Übersicht.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l4-q01","lesson":"b7l4","prompt":"Welchen Strahlungsbereich berücksichtigt der HBW laut TSR-Unterlage?","options":["Die sichtbare elektromagnetische Strahlung (VIS).","Nur den infraroten Bereich.","Nur den ultravioletten Bereich.","Das gesamte Sonnenspektrum vollständig."],"correct":0,"why":"Die Übersicht grenzt den HBW ausdrücklich auf VIS ein.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l4-q02","lesson":"b7l4","prompt":"Auf welchen Bereich bezieht sich die TSR laut Unterlage?","options":["Auf die Energieeinstrahlung im gesamten Sonnenspektrum vom UV- bis zum Infrarotbereich.","Nur auf sichtbares Grünlicht.","Nur auf ultraviolette Strahlung.","Nur auf Wärmeleitung im Untergrund."],"correct":0,"why":"TSR betrachtet den gesamten für die Sonneneinstrahlung beschriebenen Spektralbereich.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l4-q03","lesson":"b7l4","prompt":"Warum korrelieren HBW und TSR laut Übersicht nicht zwingend?","options":["Weil HBW nur den sichtbaren Bereich erfasst, TSR aber das gesamte Sonnenspektrum berücksichtigt.","Weil beide exakt dieselbe Größe messen.","Weil TSR ausschließlich die Oberfläche misst und HBW nur die Schichtdicke.","Weil der HBW nur Infrarot und TSR nur UV erfasst."],"correct":0,"why":"Die beiden Kennwerte betrachten unterschiedliche Spektralbereiche.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l4-q04","lesson":"b7l4","prompt":"Welche Aussage zur Beziehung von HBW und TSR entspricht der ausführlichen TSR-Unterlage?","options":["Aus dem HBW lässt sich der TSR nicht einfach gleichartig ableiten.","Ein hoher HBW garantiert immer denselben hohen TSR.","TSR und HBW sind definitionsgemäß identisch.","Ein niedriger HBW bedeutet immer TSR 0 %."],"correct":0,"why":"Die Produktzusammensetzung kann dazu führen, dass beide Werte nicht gleich zueinander verlaufen.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l4-q05","lesson":"b7l4","prompt":"Ein Farbton hat einen bekannten HBW. Reicht dieser Wert laut TSR-Unterlage aus, um den TSR sicher festzulegen?","options":["Nein, der TSR muss vom Hersteller bestätigt werden.","Ja, TSR und HBW sind immer identisch.","Ja, man verdoppelt einfach den HBW.","Nein, weil TSR grundsätzlich nicht messbar ist."],"correct":0,"why":"Die Unterlage fordert ausdrücklich die Herstellerbestätigung des TSR.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l4-q06","lesson":"b7l4","prompt":"Zwei Produkte haben denselben sichtbaren Farbeindruck. Welche Aussage ist nach der TSR-Unterlage möglich?","options":["Sie können aufgrund unterschiedlicher Produktzusammensetzung unterschiedliche TSR-Werte besitzen.","Sie müssen zwingend denselben TSR-Wert besitzen.","Sie besitzen automatisch dieselbe PVK und dasselbe Bindemittel.","Sie können nur dann verschieden sein, wenn einer unpigmentiert ist."],"correct":0,"why":"Gleicher sichtbarer Eindruck bedeutet nicht automatisch gleiches Verhalten im gesamten Sonnenspektrum.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l5-q01","lesson":"b7l5","prompt":"Welchen Anteil weist die Grafik dem sichtbaren Bereich der relevanten Solarstrahlung zu?","options":["39 %.","3 %.","58 %.","100 %."],"correct":0,"why":"Die Grafik kennzeichnet 39 % als sichtbar.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l5-q02","lesson":"b7l5","prompt":"Welchen Anteil weist die Grafik dem Infrarotbereich zu?","options":["58 %.","39 %.","3 %.","20 %."],"correct":0,"why":"Die Grafik kennzeichnet 58 % als infrarot.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l5-q03","lesson":"b7l5","prompt":"Wie groß ist der in der Grafik angegebene UV-Anteil?","options":["3 %.","39 %.","58 %.","25 %."],"correct":0,"why":"Die Grafik nennt 3 % ultraviolett.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l5-q04","lesson":"b7l5","prompt":"Was zeigt die Verteilung 3 % UV, 39 % sichtbar und 58 % infrarot für die HBW-Betrachtung?","options":["Der sichtbare Bereich ist nur ein Teil des gesamten solaren Energieeintrags.","Der sichtbare Bereich umfasst die gesamte Solarenergie.","Infrarot spielt laut Grafik keine Rolle.","UV macht den größten Anteil aus."],"correct":0,"why":"Die Grafik verdeutlicht, warum eine nur sichtbare Bewertung die gesamte Wärmelast nicht abbildet.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l5-q05","lesson":"b7l5","prompt":"Welche Kombination gibt die Grafik der TSR-Unterlage korrekt wieder?","options":["3 % UV · 39 % sichtbar · 58 % infrarot.","58 % UV · 39 % sichtbar · 3 % infrarot.","39 % UV · 58 % sichtbar · 3 % infrarot.","25 % UV · 25 % sichtbar · 50 % infrarot."],"correct":0,"why":"Nur diese Aufteilung entspricht der abgebildeten Grafik.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l5-q06","lesson":"b7l5","prompt":"Warum kann der HBW die solare Aufheizung nur eingeschränkt beschreiben?","options":["Weil er laut Unterlage den sichtbaren Bereich erfasst, während ein großer Energieanteil im Infrarot liegt.","Weil er ausschließlich die Luftfeuchte misst.","Weil die Sonne nur aus sichtbarem Licht besteht.","Weil der Infrarotanteil laut Grafik 0 % beträgt."],"correct":0,"why":"Die Grafik zeigt 58 % Infrarot gegenüber 39 % sichtbar.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l6-q01","lesson":"b7l6","prompt":"Bei welchen Wandaufbauten nennt die Unterlage eine besondere Notwendigkeit zur Machbarkeits- bzw. Funktionsbewertung?","options":["Bei WDVS und hochwärmegedämmtem Mauerwerk.","Nur bei Tapeten im Innenraum.","Nur bei ungedämmten Holzdecken.","Nur bei Bodenbelägen ohne Sonneneinstrahlung."],"correct":0,"why":"Diese beiden Aufbauten werden ausdrücklich genannt.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l6-q02","lesson":"b7l6","prompt":"Welchen HBW nennt die Unterlage für eine generelle Ausführung nach den anerkannten Regeln der Technik?","options":["HBW > 20.","HBW < 5.","HBW = 0.","HBW > 90 als einzige Möglichkeit."],"correct":0,"why":"Die TSR-Übersicht nennt derzeit HBW > 20.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l6-q03","lesson":"b7l6","prompt":"Warum genügt der HBW allein laut Unterlage bei der thermischen Beurteilung nicht?","options":["Weil seine Aussagekraft zu Aufheizverhalten und resultierender Oberflächentemperatur unzureichend ist.","Weil er nur die Haftfestigkeit beschreibt.","Weil er ausschließlich den Wassergehalt misst.","Weil er immer höher als 100 ist."],"correct":0,"why":"Die Quelle formuliert diese Einschränkung ausdrücklich.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l6-q04","lesson":"b7l6","prompt":"Welche Größe trägt laut Unterlage umfassender zur Bewertung der physikalischen Belastung durch Solarstrahlung bei?","options":["Der TSR-Wert.","Nur der Glanzgrad.","Nur die Nassschichtdicke.","Nur die Trocknungszeit."],"correct":0,"why":"TSR berücksichtigt einen größeren Anteil des Sonnenspektrums als der HBW.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l6-q05","lesson":"b7l6","prompt":"Ein dunkler Farbton auf einem WDVS unterschreitet HBW 20. Was fordert die Unterlage für die weitere thermische Beurteilung?","options":["Den TSR-Wert heranzuziehen.","Den HBW zu ignorieren und nur den Glanz zu messen.","Die Beschichtung grundsätzlich ohne weitere Prüfung auszuführen.","Nur die Raumluftfeuchte zu messen."],"correct":0,"why":"Bei Unterschreitung HBW 20 soll laut Fazit der TSR herangezogen werden.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l6-q06","lesson":"b7l6","prompt":"Ein Farbton liegt über HBW 20. Welche Aussage wäre nach der Unterlage trotzdem zu weitgehend?","options":["Der HBW allein beschreibt in jedem Fall vollständig Aufheizung und Oberflächentemperatur.","HBW > 20 ist die genannte Regel für die generelle Ausführung.","Bei speziellen Wandaufbauten kann eine Funktionsbewertung nötig sein.","TSR kann zur umfassenderen thermischen Beurteilung dienen."],"correct":0,"why":"Die Quelle sagt ausdrücklich, dass der HBW allein thermisch nur begrenzt aussagekräftig ist.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l7-q01","lesson":"b7l7","prompt":"Welchen TSR-Grenzwert nennt die Unterlage als thermisch sichere Einordnung für eine funktionstaugliche Ausführung?","options":["Mindestens 25 %.","Mindestens 5 %.","Genau 10 %.","Mindestens 75 % als einzige zulässige Grenze."],"correct":0,"why":"Die Übersicht nennt Herstelleruntersuchungen mit TSR ≥ 25 %.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l7-q02","lesson":"b7l7","prompt":"Wer muss den TSR-Wert laut Fazit der Unterlage bestätigen?","options":["Der Hersteller.","Der Endkunde ohne Messung.","Ausschließlich der Gerüstbauer.","Der Farbtonfächer selbst."],"correct":0,"why":"Die Herstellerbestätigung wird ausdrücklich gefordert.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l7-q03","lesson":"b7l7","prompt":"Auf welche Prüfbedingung verweist die Fußnote beim TSR-Wert von 25 %?","options":["ASTM G173 mit 1000 W/m².","DIN 4108 mit 100 W/m².","RAL Classic mit 1000 Kelvin.","ISO 9001 mit 25 Lux."],"correct":0,"why":"Die Fußnote nennt ASTM G173 (1000 W/m²).","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l7-q04","lesson":"b7l7","prompt":"Wie ist der Wert TSR ≥ 25 % in diesem Trainer zu verstehen?","options":["Als in der verwendeten Dino-Unterlage genannte thermisch sichere Einordnung unter dem dort beschriebenen Bezug.","Als universelle Garantie für jedes Produkt und jeden Aufbau ohne Herstellerprüfung.","Als identische Bedeutung zu HBW 25.","Als Mindestglanzgrad einer Fassade."],"correct":0,"why":"Der Trainer gibt die konkrete Aussage der Quelle wieder und koppelt sie an die Herstellerbestätigung.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l7-q05","lesson":"b7l7","prompt":"Der Hersteller bestätigt TSR 29 % für den vorgesehenen dunklen Beschichtungsstoff. Wie ordnet die Dino-Unterlage diesen Wert ein?","options":["Er liegt über dem genannten Mindestwert von 25 % und wird thermisch sicher eingeordnet.","Er liegt unter dem Mindestwert von 25 %.","Er ist automatisch identisch mit HBW 29.","Er sagt laut Unterlage nichts zur solaren Reflexion aus."],"correct":0,"why":"29 % erfüllt den in der Quelle genannten TSR-Mindestwert.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l7-q06","lesson":"b7l7","prompt":"Ein Datenblatt nennt keinen bestätigten TSR-Wert. Darf man nach der Unterlage allein aus dem HBW einen TSR von 25 % annehmen?","options":["Nein, der TSR-Wert soll vom Hersteller bestätigt werden.","Ja, jeder HBW ergibt automatisch denselben TSR.","Ja, sofern die Farbe dunkel aussieht.","Ja, wenn der Untergrund rau ist."],"correct":0,"why":"Die Übersicht warnt vor einer einfachen Gleichsetzung und verlangt die Herstellerbestätigung.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l8-q01","lesson":"b7l8","prompt":"Wann soll laut Fazit der TSR-Wert bei dunklen Farbtönen herangezogen werden?","options":["Wenn ein HBW von 20 unterschritten wird.","Nur wenn HBW über 90 liegt.","Nur im Innenraum ohne Sonne.","Nur bei transparenten Lasuren."],"correct":0,"why":"Das Fazit nennt ausdrücklich die Unterschreitung HBW 20.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l8-q02","lesson":"b7l8","prompt":"Welche zwei Kennwerte stehen im Zentrum der thermischen Farbtonbeurteilung dieses Blocks?","options":["HBW und TSR.","sd-Wert und w-Wert.","pH-Wert und Taupunkt.","Gitterschnittwert und Schichtdicke."],"correct":0,"why":"Die Unterlage stellt TSR in Bezug zum HBW.","level":"basis","src":"DINO-TSR"},{"id":"f24-b7-l8-q03","lesson":"b7l8","prompt":"Welche Reihenfolge entspricht dem Fazit der TSR-Unterlage bei einem dunklen Farbton mit HBW < 20?","options":["TSR heranziehen → Herstellerbestätigung beachten → TSR-Mindestwert der Unterlage prüfen.","Nur den Farbtonnamen ansehen → ohne weitere Prüfung ausführen.","HBW verdoppeln → Ergebnis als TSR verwenden.","Nur den Glanzgrad bestimmen → daraus TSR berechnen."],"correct":0,"why":"So verbindet das Fazit HBW-Unterschreitung, TSR und Herstellerbestätigung.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l8-q04","lesson":"b7l8","prompt":"Warum ist „dunkler Farbton = automatisch niedriger TSR“ nach der ausführlichen TSR-Übersicht keine sichere Regel?","options":["Weil die Pigmentierung besonders im NIR das TSR-Verhalten beeinflussen kann und HBW/TSR nicht zwingend korrelieren.","Weil dunkle Farbtöne immer 100 % reflektieren.","Weil TSR ausschließlich die Lufttemperatur misst.","Weil NIR nur bei Innenräumen vorkommt."],"correct":0,"why":"Die Übersicht trennt sichtbare Dunkelheit und solare Reflexion ausdrücklich.","level":"verstehen","src":"DINO-TSR"},{"id":"f24-b7-l8-q05","lesson":"b7l8","prompt":"Fall: WDVS, sehr dunkler Farbton, HBW 15, bestätigter TSR 28 %. Welche Bewertung folgt aus der Dino-Unterlage?","options":["TSR ist wegen HBW < 20 heranzuziehen; 28 % liegt über dem genannten 25-%-Wert und wird thermisch sicher eingeordnet.","Die Ausführung ist allein wegen HBW 15 immer ausgeschlossen.","TSR 28 % ist zu niedrig, weil mindestens 50 % gefordert werden.","HBW und TSR müssen zwingend identisch sein, daher ist ein Datenfehler bewiesen."],"correct":0,"why":"Der Fall erfüllt die im Fazit beschriebene Entscheidungsfolge.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b7-l8-q06","lesson":"b7l8","prompt":"Fall: dunkler Farbton, HBW 17, aber kein bestätigter TSR. Was fehlt nach der Unterlage für die TSR-basierte Beurteilung?","options":["Die Bestätigung des TSR-Werts durch den Hersteller.","Eine RAL-Signalfarbe.","Ein Gitterschnitt GT 0.","Eine NCS-Weißanteilberechnung."],"correct":0,"why":"Die Quelle verlangt die Herstellerbestätigung des TSR.","level":"anwenden","src":"DINO-TSR"},{"id":"f24-b8-l1-q01","lesson":"b8l1","prompt":"Welche Themen umfasst der Geltungsbereich des BFS-Merkblatts Nr. 25 laut Lösungsbogen?","options":["Planung der Farbgebung, Ausschreibung, Bemusterung, Abtönung und handwerkliche Verarbeitung.","Nur Korrosionsschutz an Stahl.","Nur Wärmedämmung und Tauwasser.","Nur Gerüstbau und Arbeitsschutz."],"correct":0,"why":"Diese Stationen werden im Geltungsbereich ausdrücklich genannt.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l1-q02","lesson":"b8l1","prompt":"Worauf beziehen sich die beschriebenen Farbdifferenzen im BFS-25-Lösungsbogen?","options":["Auf bestimmte Anwendungen von Beschichtungsstoffen in und an Bauwerken.","Nur auf Textildruck.","Nur auf Fahrzeuglackierung im Werk.","Ausschließlich auf Tapetenkleister."],"correct":0,"why":"Der Geltungsbereich nennt Beschichtungsstoffe in und an Bauwerken.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l1-q03","lesson":"b8l1","prompt":"Wie werden handwerklich ausgeführte Beschichtungsfarben am Bau in aller Regel abgemustert?","options":["Durch visuellen Vergleich.","Nur durch Wiegen des Farbtons.","Nur durch Messung der Schichtdicke.","Ausschließlich über den Produktnamen."],"correct":0,"why":"Der Lösungsbogen nennt den visuellen Vergleich als übliche Abmusterung.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l1-q04","lesson":"b8l1","prompt":"Warum ist der visuelle Vergleich im BFS-25-Lösungsbogen zentral?","options":["Weil damit die am Bau übliche Farbübereinstimmung beurteilt wird, sofern die beschriebenen Einflüsse beachtet werden.","Weil Farbtöne am Bau grundsätzlich nicht von Licht beeinflusst werden.","Weil nur die Viskosität sichtbar ist.","Weil das Merkblatt keine Farbdifferenzen behandelt."],"correct":0,"why":"Die Quelle verbindet visuelle Abmusterung mit den zu beachtenden Einflussfaktoren.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l1-q05","lesson":"b8l1","prompt":"Bei einer Ausschreibung soll ein Farbton für handwerkliche Beschichtung festgelegt werden. Welches Merkblatt-Thema trifft der Lösungsbogen damit direkt?","options":["Planung/Ausschreibung und Bemusterung der Farbgebung.","Ausschließlich Tragwerksberechnung.","Ausschließlich Abwasserentsorgung.","Nur Leiternprüfung."],"correct":0,"why":"Diese Punkte gehören ausdrücklich zum Geltungsbereich.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l1-q06","lesson":"b8l1","prompt":"Ein Maler vergleicht eine ausgeführte Fläche mit dem vereinbarten Muster direkt vor Ort. Welche im Lösungsbogen genannte Methode nutzt er?","options":["Visuelle Abmusterung.","Thermische TSR-Prüfung.","Gitterschnittprüfung.","pH-Wert-Messung."],"correct":0,"why":"Der direkte visuelle Vergleich ist die genannte übliche Methode.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l2-q01","lesson":"b8l2","prompt":"Was muss bei der Verwendung von Farbmusterkarten eindeutig feststehen?","options":["Nach welcher Vorlage die farbige Beschichtung auszuführen ist.","Welche Leiterklasse verwendet wird.","Wie hoch der sd-Wert der Wand ist.","Welcher Putzmörtel im Sockel liegt."],"correct":0,"why":"Der Lösungsbogen warnt vor verschiedenen Codierungen und fordert eine eindeutige Vorlage.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l2-q02","lesson":"b8l2","prompt":"Wodurch entsteht der Farbeindruck laut BFS-25-Lösungsbogen?","options":["Durch Licht bzw. Beleuchtung zusammen mit den Reflexionseigenschaften der Oberfläche.","Nur durch den Namen des Farbtons.","Nur durch die Schichtdicke ohne Licht.","Nur durch die Raumtemperatur."],"correct":0,"why":"Das Auge nimmt die Summe aus Licht und Oberflächenreflexion wahr.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l2-q03","lesson":"b8l2","prompt":"Warum können Farbmusterkarten trotz gleicher Codierung problematisch sein?","options":["Weil Codierungen in unterschiedlichen Farbvarianten im Umlauf sein können.","Weil Farbmuster grundsätzlich farblos sind.","Weil jede Codierung nur die Schichtdicke bezeichnet.","Weil Farbkarten laut Quelle nicht verwendet werden dürfen."],"correct":0,"why":"Genau darauf weist der Lösungsbogen hin.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l2-q04","lesson":"b8l2","prompt":"Welche Lichtgröße beeinflusst laut Lösungsbogen die Erscheinung einer Farbe?","options":["Das Spektrum des einwirkenden Lichts bzw. seine Farbtemperatur.","Nur die Luftgeschwindigkeit.","Nur die Oberflächenhärte.","Nur die Dichte des Untergrunds."],"correct":0,"why":"Die Farbwirkung hängt ausdrücklich vom Lichtspektrum ab.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l2-q05","lesson":"b8l2","prompt":"Ein Farbpaar wirkt unter Kunstlicht nahezu gleich, bei Tageslicht deutlich verschieden. Welcher Effekt wird im BFS-25-Lösungsbogen genannt?","options":["Metamerie-Effekt.","Kapillarwirkung.","Kreidung.","Gitterschnittbruch."],"correct":0,"why":"Der Lösungsbogen nennt genau dieses Beispiel als Metamerie.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l2-q06","lesson":"b8l2","prompt":"Auf einer Baustelle soll eine Farbkarte als Vorlage dienen. Was ist vor Ausführung besonders zu klären?","options":["Die genaue Farbkarte bzw. Variante, auf die sich die Ausführung bezieht.","Nur die Größe der Karte in Zentimetern.","Nur der Hersteller des Pinsels.","Nur die Raumhöhe."],"correct":0,"why":"Die Vorlage muss wegen möglicher Codierungsvarianten eindeutig bestimmt sein.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l3-q01","lesson":"b8l3","prompt":"Wie können gleichfarbige Oberflächen mit zunehmender Rauigkeit wirken?","options":["Dunkler.","Immer heller.","Immer transparenter.","Immer metallischer."],"correct":0,"why":"Die Quelle nennt Schattenbildung und verringerte gerichtete Reflexion als Ursache.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l3-q02","lesson":"b8l3","prompt":"Welche zwei grundsätzlichen Wege der Abtönung nennt der Lösungsbogen?","options":["Manuelle Abtönung und Zubereitung über Tönautomaten.","Nur Spritzen und Rollen.","Nur Schleifen und Spachteln.","Nur Erwärmen und Kühlen."],"correct":0,"why":"Die Quelle unterscheidet manuelles Mischen und maschinelle Tönung.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l3-q03","lesson":"b8l3","prompt":"Warum kann eine rauere Oberfläche trotz gleichen Farbtons dunkler erscheinen?","options":["Weil die Struktur Schatten bildet und gerichtete Reflexion verhindert.","Weil die Pigmente dadurch automatisch chemisch schwarz werden.","Weil Rauigkeit jede Lichtquelle ausschaltet.","Weil die Oberfläche dadurch immer nass ist."],"correct":0,"why":"So erklärt der BFS-25-Lösungsbogen die Wirkung der Struktur.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l3-q04","lesson":"b8l3","prompt":"Wovon hängt die Genauigkeit einer maschinellen Abtönung laut Lösungsbogen unter anderem ab?","options":["Von Pflege/Bedienung der Anlage, Rezepturqualität, Farbpasten und Basismaterialien.","Nur vom Wochentag.","Nur vom Glanzgrad des fertigen Untergrunds.","Ausschließlich vom Namen der RAL-Farbe."],"correct":0,"why":"Diese Einflussgrößen werden ausdrücklich genannt.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l3-q05","lesson":"b8l3","prompt":"Zwei gleich getönte Flächen unterscheiden sich stark in der Rauigkeit. Welche Ursache sollte bei einer optischen Abweichung zuerst mitbedacht werden?","options":["Der Einfluss der Oberflächenstruktur auf Schatten und Reflexion.","Nur eine falsche NCS-Codierung.","Zwingend ein anderer TSR-Wert.","Nur ein defekter Tönautomat."],"correct":0,"why":"Die Quelle sagt, dass Rauigkeit den Farbeindruck verändern kann.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l3-q06","lesson":"b8l3","prompt":"Ein Tönautomat liefert ungenaue Ergebnisse. Welche Maßnahme passt zu den im Lösungsbogen genannten Einflussfaktoren?","options":["Pflege und Bedienung der Anlage sowie Rezepturen, Farbpasten und Basismaterialien prüfen.","Nur die Gerüstbreite ändern.","Nur den HBW der Wand messen.","Nur die Raumbeleuchtung ausschalten."],"correct":0,"why":"Genau diese Faktoren beeinflussen laut Quelle die maschinelle Farbtongenauigkeit.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l4-q01","lesson":"b8l4","prompt":"Wann reicht die „normale Anforderung an die Farbübereinstimmung“ laut BFS 25 nicht aus?","options":["Wenn die Beschichtung direkt zu einer Fläche oder einem Objekt farblich übereinstimmen muss.","Wenn zwei Flächen deutlich durch Abstand oder Ecke getrennt sind.","Bei jeder weißen Innenwand automatisch.","Nur wenn keine Farbvorgabe existiert."],"correct":0,"why":"Ein direkter Bezug mit gewünschter Übereinstimmung erhöht die Anforderung.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l4-q02","lesson":"b8l4","prompt":"Was soll bei einer Nachbestellung für größtmögliche Farbübereinstimmung mitgeliefert werden?","options":["Ein Nassmuster.","Nur ein Foto auf dem Handy.","Nur die Rechnungsnummer.","Ein Stück Gerüstbohle."],"correct":0,"why":"Der Lösungsbogen fordert bei Nachlieferungen ein Nassmuster.","level":"basis","src":"DINO-BFS25"},{"id":"f24-b8-l4-q03","lesson":"b8l4","prompt":"Welche Trennungen können laut Lösungsbogen dazu führen, dass die normale Anforderung wieder ausreicht?","options":["Deutlicher Abstand, Spalt, Innen- oder Außenecke.","Nur eine Klebebandkante.","Nur eine Schicht Grundierung.","Nur ein unterschiedlicher Pinsel."],"correct":0,"why":"Diese vier Trennmöglichkeiten nennt der Lösungsbogen.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l4-q04","lesson":"b8l4","prompt":"Warum soll ein Vergleich mit einem vorgegebenen Bauteil vor Ort erfolgen?","options":["Wegen des Einflusses der Beleuchtung bzw. Belichtung am tatsächlichen Ort.","Weil Farbvergleiche nur draußen erlaubt sind.","Weil das Originalmuster dort seine RAL-Nummer ändert.","Weil Tönautomaten nur auf Baustellen funktionieren."],"correct":0,"why":"Der Lösungsbogen begründet die Vor-Ort-Abmusterung mit dem Lichteinfluss.","level":"verstehen","src":"DINO-BFS25"},{"id":"f24-b8-l4-q05","lesson":"b8l4","prompt":"Ein neuer Anstrich soll exakt zu einem Einrichtungsgegenstand passen. Welche Vorgehensweise nennt BFS 25?","options":["Originalmuster bereitstellen, Muster mit vorgesehenem Material und Applikation anfertigen, vergleichen und als Vertragsgrundlage vereinbaren.","Nur den Farbnamen telefonisch nennen.","Nur einen beliebigen RAL-Fächer danebenhalten und sofort ausführen.","Ausschließlich den HBW des Gegenstands messen."],"correct":0,"why":"So beschreibt der Lösungsbogen die besondere Farbübereinstimmung.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l4-q06","lesson":"b8l4","prompt":"Der Untergrund ist sehr dunkel, die Deckbeschichtung deutlich heller und der Untergrund scheint farblich durch. Was empfiehlt der Lösungsbogen?","options":["Zusätzliche auf den Deckfarbton abgestimmte Beschichtungen, bis der Untergrundeinfluss ausgeschaltet ist.","Nur stärkeres Licht zur Abmusterung.","Die Nachbestellung als Erstlieferung kennzeichnen.","Die Oberfläche absichtlich rauer machen."],"correct":0,"why":"Zusätzliche angepasste Beschichtungen sollen den Untergrundeinfluss neutralisieren.","level":"anwenden","src":"DINO-BFS25"},{"id":"f24-b8-l5-q01","lesson":"b8l5","prompt":"Was ist nach dem BFS-26-Lösungsbogen eine „Beschichtung“?","options":["Eine durch ein- oder mehrmaliges Auftragen von Beschichtungsstoff entstehende durchgehende Schicht.","Der noch ungeöffnete Gebindeinhalt.","Nur ein einzelnes Pigmentteilchen.","Ausschließlich die sichtbare Farbe ohne Material."],"correct":0,"why":"So lautet die im Blatt wiedergegebene Definition.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l5-q02","lesson":"b8l5","prompt":"Was versteht der Lösungsbogen unter „Bindemittel“?","options":["Den nichtflüchtigen Anteil eines Beschichtungsstoffs ohne Pigmente und Füllstoffe.","Nur das Lösemittel.","Die Summe aller Pigmente.","Nur den Untergrund."],"correct":0,"why":"Die Definition grenzt Bindemittel von Pigmenten und Füllstoffen ab.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l5-q03","lesson":"b8l5","prompt":"Wie unterscheidet sich der Beschichtungsstoff von der Beschichtung?","options":["Der Beschichtungsstoff ist das aufzutragende Produkt; die Beschichtung ist die daraus entstandene Schicht.","Beide Begriffe bezeichnen nur den Farbton.","Die Beschichtung ist das flüssige Gebinde, der Stoff nur die getrocknete Schicht.","Es gibt laut Quelle keinen Unterschied."],"correct":0,"why":"Die Definitionen trennen Produkt und entstandene Schicht.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l5-q04","lesson":"b8l5","prompt":"Welche Größen nennt BFS 26 neben der Zeit als mögliche Einflussgrößen für Farbveränderungen?","options":["Bindemittelart, Art/Anteil von Pigmenten und Füllstoffen sowie Additive.","Nur Gerüsthöhe, Raumgröße und Werkzeuggewicht.","Nur Deckvermögen und Nassschichtdicke.","Nur Farbname und Gebindegröße."],"correct":0,"why":"Diese Parameter stehen im Abschnitt „Allgemeines“.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l5-q05","lesson":"b8l5","prompt":"Bei der Auswahl eines Beschichtungsstoffes für außen wird die Witterungsbeanspruchung betrachtet. Welches weitere Kriterium nennt der Lösungsbogen?","options":["Art und Zustand des Untergrundes.","Nur die Verpackungsfarbe.","Nur die Leiterlänge.","Ausschließlich den Preis des Pinsels."],"correct":0,"why":"Untergrund, Nutzung, Witterung und Oberflächeneffekt werden genannt.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l5-q06","lesson":"b8l5","prompt":"Ein Auftrag fordert eine bestimmte Oberflächenwirkung und liegt stark bewittert. Welche Auswahlfaktoren aus BFS 26 sind direkt berührt?","options":["Gewünschter Oberflächeneffekt und Witterungsbeanspruchung des Objekts.","Nur die Farbkarte und das Abdeckmaterial.","Nur die Raumhöhe und das Gerüst.","Nur das Alter des Werkzeugs."],"correct":0,"why":"Beide Kriterien nennt der Lösungsbogen für die Bindemittelauswahl.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l6-q01","lesson":"b8l6","prompt":"Welche zwei Witterungseinflüsse greifen laut BFS-26-Lösungsbogen die Beschichtungsoberfläche an?","options":["Feuchte und UV-Strahlung.","Schall und Magnetismus.","Nur Druckluft und Vibration.","Ausschließlich Raumbeleuchtung."],"correct":0,"why":"Der Abschnitt nennt Feuchte- und UV-Einwirkung.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l6-q02","lesson":"b8l6","prompt":"Welche Erscheinung kann bei oxidativ trocknenden Lacken unter Lichtabschluss auftreten?","options":["Dunkelvergilbung.","Metamerie.","Transmission.","Quantitätskontrast."],"correct":0,"why":"Die Quelle nennt Vergilbung in Bereichen wie Fensterfalzen.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l6-q03","lesson":"b8l6","prompt":"Welche Umwelteinflüsse nennt BFS 26 als mögliche Ursachen für Farbveränderungen?","options":["Saurer Regen, Industrieabgase, Schmutzablagerungen und mikrobiologischer Befall.","Nur Windstille und Raumtemperatur.","Nur RAL-Codierungen und NCS-Werte.","Nur Pinselspuren und Walzenbreite."],"correct":0,"why":"Diese vier Beispiele stehen unter „Umwelteinflüsse“.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l6-q04","lesson":"b8l6","prompt":"Wie bewertet der Lösungsbogen Feuchte- und UV-Einflüsse in Innenräumen im Vergleich zu außen?","options":["In Innenräumen sind sie in der Regel so gering, dass keine merkliche Farbveränderung erfolgt.","Sie sind dort grundsätzlich stärker als außen.","Sie werden dort als einzige Ursache jeder Farbänderung bezeichnet.","Sie sind laut Quelle identisch mit NIR-Strahlung."],"correct":0,"why":"Der Hinweis im Lösungsbogen grenzt die Innenraumbeanspruchung ab.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l6-q05","lesson":"b8l6","prompt":"Eine Außenfassade ist UV, Feuchte und Industrieabgasen ausgesetzt. Welche Einordnung folgt aus BFS 26?","options":["Mehrere witterungs- und umweltbedingte Einflussfaktoren können die Farbbeständigkeit belasten.","Diese Einflüsse betreffen laut Quelle nur Innenräume.","Farbveränderungen sind unter solchen Bedingungen ausgeschlossen.","Nur der Farbtoncode kann sich dadurch ändern, nicht die Beschichtung."],"correct":0,"why":"Alle drei Einflüsse werden als mögliche Ursachen genannt.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l6-q06","lesson":"b8l6","prompt":"In einem lichtgeschützten Fensterfalz vergilbt ein oxidativ trocknender Lack. Welcher in BFS 26 beschriebene Mechanismus passt?","options":["Dunkelvergilbung bei Lichtabschluss.","Aufhellung durch direkte UV-Bestrahlung.","Metamerie durch Wechsel von Tages- zu Kunstlicht.","Transmission durch transparenten Untergrund."],"correct":0,"why":"Das Fensterfalz-Beispiel steht ausdrücklich im Lösungsbogen.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l7-q01","lesson":"b8l7","prompt":"Welche Pigmentgruppe ist laut BFS-26-Lösungsbogen in der Regel farbbeständiger?","options":["Anorganische Buntpigmente.","Organische Buntpigmente grundsätzlich immer.","Nur metallische Füllstoffe.","Ausschließlich transparente Bindemittel."],"correct":0,"why":"Die Quelle nennt anorganische Buntpigmente in der Regel als farbbeständiger.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l7-q02","lesson":"b8l7","prompt":"Welche vier untergrundbezogenen Faktoren nennt der BFS-26-Lösungsbogen?","options":["Alkalität, unterschiedliche Untergründe/Strukturen, Holzinhaltsstoffe und Weichmacher.","Nur Glanz, TSR, Kelvin und RAL.","Nur Wasser, Sand, Zement und Gips.","Nur Temperatur, Luftdruck, Wind und Schall."],"correct":0,"why":"Diese Punkte stehen im Abschnitt zu untergrundbezogenen Einflussfaktoren.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l7-q03","lesson":"b8l7","prompt":"Wie beeinflusst die PVK bei organisch gebundenen Fassadenfarben laut Unterlage die Pigmenteinbindung?","options":["Niedrige PVK bzw. hohe Bindung bindet die Pigmente besser ein als hohe PVK.","Hohe PVK bindet Pigmente immer besser ein.","PVK hat laut Quelle keinen Zusammenhang mit der Bindung.","Niedrige PVK bedeutet automatisch kein Bindemittel."],"correct":0,"why":"Die Quelle stellt hochgebundene/niedrige PVK der schwach gebundenen/hohen PVK gegenüber.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l7-q04","lesson":"b8l7","prompt":"Welche Rolle spielt die Bindemittelart bei Fassadenbeschichtungen laut BFS 26?","options":["Das Bindemittel sollte möglichst UV-stabil sein und beeinflusst die mögliche Farbveränderung.","Es beeinflusst nur die Gebindegröße.","Es hat laut Quelle keinerlei Wirkung auf Farbe.","Es bestimmt ausschließlich die RAL-Nummer."],"correct":0,"why":"Der Lösungsbogen hebt die Bindemittelart als wichtigen Produktfaktor hervor.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l7-q05","lesson":"b8l7","prompt":"Ein nicht alkalibeständiges Pigment liegt auf stark alkalischem Untergrund. Welche Farbveränderung nennt BFS 26 als möglich?","options":["Ausbleichen der Farbe.","Automatische Erhöhung des TSR auf 100 %.","Zwangsläufige Metallkorrosion ohne Farbänderung.","Ausschließlich Glanzsteigerung."],"correct":0,"why":"Starke Alkalität kann nicht alkalibeständige Pigmente ausbleichen.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l7-q06","lesson":"b8l7","prompt":"Eine Holzbeschichtung verfärbt sich bei Feuchte und Wärme. Welcher untergrundbezogene Faktor passt zur Quelle?","options":["Holzinhaltsstoffe.","Nur der Farbwiedergabeindex.","Nur die NCS-Sättigung.","Nur der Quantitätskontrast."],"correct":0,"why":"Holzinhaltsstoffe können, durch Feuchte und Wärme forciert, Farbveränderungen verursachen.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l8-q01","lesson":"b8l8","prompt":"Welche Lackbindemittel nennt die BFS-26-Tabelle im Fb-Code A1?","options":["Acryl-Lack und PUR-Lack.","Alkydharzlack und Öllack.","Epoxidharzlack und Mischpolymerisatharzlack.","Nur Silikonharzfarbe und Silikatfarbe."],"correct":0,"why":"Im A1-Feld der Lackspalte stehen Acryl-Lack und PUR-Lack.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l8-q02","lesson":"b8l8","prompt":"Welche zwei Lackarten nennt der Lösungsbogen als typische Beispiele für Dunkelvergilbung?","options":["Alkydharzlacke und Öllacke.","Acryl-Lacke und PUR-Lacke.","Nur Epoxidharzlacke und Dispersionsfarben.","Silikatfarben und Kalkfarben."],"correct":0,"why":"Aufgabe 8 nennt diese beiden ausdrücklich.","level":"basis","src":"DINO-BFS26"},{"id":"f24-b8-l8-q03","lesson":"b8l8","prompt":"In welche Richtung nimmt die alterungsbedingte Farbveränderung in der Fb-Code-Tabelle zu?","options":["Von Pigmentgruppe 1 zu 2 zu 3 und von Bindemittelklasse A zu B zu C.","Von 3 zu 2 zu 1 und von C zu B zu A.","Nur innerhalb Klasse A, nie bei B oder C.","Die Tabelle nennt keine Richtung."],"correct":0,"why":"Der Hinweis unter der Tabelle gibt genau diese Richtung an.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l8-q04","lesson":"b8l8","prompt":"Wie sind die Pigmentgruppen 1 bis 3 in der Tabelle qualitativ geordnet?","options":["Gruppe 1: sehr gut lichtbeständige anorganische Pigmente; Gruppe 2: gut lichtbeständige organische und/oder anorganische; Gruppe 3: eingeschränkt lichtbeständige organische und/oder anorganische.","Gruppe 1 ist eingeschränkt, Gruppe 3 ist sehr gut.","Alle drei Gruppen sind identisch.","Die Gruppen ordnen nur die Schichtdicke."],"correct":0,"why":"Die Tabellenüberschriften definieren diese Abstufung.","level":"verstehen","src":"DINO-BFS26"},{"id":"f24-b8-l8-q05","lesson":"b8l8","prompt":"Ein Lack ist als A1 eingeordnet. Welche Kombination passt zur Tabelle?","options":["Bindemittelklasse A mit Pigmentgruppe 1; bei Lacken nennt die Tabelle Acryl- oder PUR-Lack.","Bindemittelklasse C mit Pigmentgruppe 3; nur Alkydharzlack.","Bindemittelklasse B mit Pigmentgruppe 2; nur Öllack.","Keine Bindemittelklasse und keine Pigmentgruppe."],"correct":0,"why":"Der Code kombiniert Buchstabenklasse und Pigmentgruppe; A1 ist das entsprechende Feld.","level":"anwenden","src":"DINO-BFS26"},{"id":"f24-b8-l8-q06","lesson":"b8l8","prompt":"Ein oxidativ trocknender Alkydharzlack vergilbt in einem lichtgeschützten Falz. Welche zwei Aussagen aus BFS 26 treffen zusammen?","options":["Alkydharzlacke werden als dunkelvergilbungsgefährdet genannt; Lichtabschluss begünstigt diese Vergilbung.","Acryl-Lacke sind A1 und vergilben deshalb zwangsläufig im Dunkeln.","Der Effekt ist laut Quelle ausschließlich Metamerie.","Lichtabschluss verhindert laut Quelle jede Vergilbung."],"correct":0,"why":"Die Quelle verbindet oxidativ trocknende Lacke und Lichtabschluss mit Dunkelvergilbung und nennt Alkydharzlacke als Beispiel.","level":"anwenden","src":"DINO-BFS26"}];

  var root=null,current=null;
  function byId(id){return typeof document!=='undefined'?document.getElementById(id):null;}
  function q(sel,base){return (base||document).querySelector(sel);}
  function qa(sel,base){return Array.prototype.slice.call((base||document).querySelectorAll(sel));}
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;}
  function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
  function lessonById(id){return LESSONS.find(function(x){return x.id===id;});}
  function blockById(id){return BLOCKS.find(function(x){return x.id===id;});}
  function lessonQuestions(id){return EXERCISES.filter(function(x){return x.lesson===id;});}
  function blockLessons(id){return LESSONS.filter(function(x){return x.block===id;});}
  function blockQuestions(id){var lessonIds=blockLessons(id).map(function(x){return x.id;});return EXERCISES.filter(function(x){return lessonIds.indexOf(x.lesson)>=0;});}

  function validateData(){
    if(EXERCISES.length!==346)throw new Error('Farbenlehre-Trainer: 346 Aufgaben erwartet, gefunden '+EXERCISES.length);
    var ids=new Set(),prompts=new Set();
    EXERCISES.forEach(function(x){
      if(ids.has(x.id))throw new Error('Doppelte Trainer-ID: '+x.id);ids.add(x.id);
      var pk=String(x.prompt||'').trim().toLowerCase();if(prompts.has(pk))throw new Error('Doppelte Trainerfrage: '+x.prompt);prompts.add(pk);
      if(!Array.isArray(x.options)||x.options.length!==4||new Set(x.options).size!==4)throw new Error('Ungültige Optionen: '+x.id);
      if(x.correct<0||x.correct>3)throw new Error('Ungültige Lösung: '+x.id);
      if(!SOURCE_NOTES[x.src])throw new Error('Fehlende Quelle: '+x.id);
      if(!lessonById(x.lesson))throw new Error('Fehlende Lektion: '+x.id);
    });
    LESSONS.forEach(function(l){if(!LEARNING[l.id]||!LEARNING[l.id].length)throw new Error('Fehlende Lernkarten: '+l.id);if(!lessonQuestions(l.id).length)throw new Error('Fehlende Aufgaben: '+l.id);});
    return {ok:true,exerciseCount:EXERCISES.length,lessonCount:LESSONS.length,blockCount:BLOCKS.length,activeBlocks:ACTIVE_BLOCKS};
  }
  var VALIDATION=validateData();

  function defaultState(){return {version:VERSION,unlockedBlock:1,lesson:{},blockTests:{},finalTest:{best:0,passed:false,runs:0},mistakes:{},seen:{},lastBlock:1,lastLesson:null,updatedAt:Date.now()};}
  function sanitizeState(s){if(!s||typeof s!=='object')return defaultState();s.version=VERSION;s.unlockedBlock=clamp(Number(s.unlockedBlock)||1,1,ACTIVE_BLOCKS);s.lesson=s.lesson||{};s.blockTests=s.blockTests||{};s.finalTest=s.finalTest||{best:0,passed:false,runs:0};s.mistakes=s.mistakes||{};s.seen=s.seen||{};for(var bi=1;bi<ACTIVE_BLOCKS;bi++){if(s.blockTests[bi]&&s.blockTests[bi].passed)s.unlockedBlock=Math.max(s.unlockedBlock,bi+1);}s.lastBlock=clamp(Number(s.lastBlock)||1,1,ACTIVE_BLOCKS);return s;}
  function loadState(){try{return sanitizeState(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'));}catch(e){return defaultState();}}
  var state=typeof localStorage!=='undefined'?loadState():defaultState();
  function saveState(){state.updatedAt=Date.now();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}updateLauncher();}
  function lState(id){return state.lesson[id]||(state.lesson[id]={best:0,passed:false,runs:0,read:false});}
  function bState(id){return state.blockTests[id]||(state.blockTests[id]={best:0,passed:false,runs:0});}
  function fState(){return state.finalTest||(state.finalTest={best:0,passed:false,runs:0});}
  function lessonPassed(id){return !!(state.lesson[id]&&state.lesson[id].passed);}
  function blockLessonsPassed(id){var ls=blockLessons(id);return ls.length>0&&ls.every(function(l){return lessonPassed(l.id);});}
  function blockPassed(id){return !!(state.blockTests[id]&&state.blockTests[id].passed);}
  function allBlocksPassed(){for(var i=1;i<=ACTIVE_BLOCKS;i++)if(!blockPassed(i))return false;return true;}
  function completedLessons(){return LESSONS.filter(function(l){return lessonPassed(l.id);}).length;}
  function activeLessonCount(){return LESSONS.filter(function(l){return l.block<=ACTIVE_BLOCKS;}).length;}
  function totalMistakes(){return Object.keys(state.mistakes).filter(function(id){return Number(state.mistakes[id]&&state.mistakes[id].wrong)>0;}).length;}
  function exerciseById(id){return EXERCISES.find(function(x){return x.id===id;});}

